/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020508-7","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"厚生委員会","time":"午後１時６分～午後３時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"障害者ホームヘルプサービスについて、まずお伺いしたいと思います。「品川区の福祉」の障害者ホームヘルプ派遣事業のところを見ますと、平成１０年度から実績の数が減ってきているんですが、どうして減ってきてしまっているのでしょうか。","respondent":"日下部障害者福祉課長","answer":"これは平成１２年度から介護保険制度が導入されましたので、基本的には６５歳以上の方については介護保険のほうに移行いたしましたので、かなり対象者が急減したです。","id":"exchange-001"},{"speaker":"船波委員","kind":"質問","question":"東京都の政策の見直しに伴っての変更というご報告ですけれども、２・３・４段階の方々の無料の部分を廃止するというのも、東京都がやめてしまうから仕方なくやめるということなんですか。","respondent":"日下部障害者福祉課長","answer":"東京都がやめるから仕方なくと、品川区としては必ずしもそういうことではなくて、先ほども説明の中で触れましたけれども、もともと品川区としても実施にあたっては要綱のもとに実施しております。","id":"exchange-002"},{"speaker":"船波委員","kind":"質問","question":"そうしますと、週３回９時間を無料にする分の費用的な負担というのは、東京都がすべて担っているわけですか。","respondent":"日下部障害者福祉課長","answer":"ここに週３回９時間とありますけれども、実は東京都の制度では週２回６時間、これに品川区が加算をして週３回９時間まで無料ということで対応してまいりました。","id":"exchange-003"},{"speaker":"船波委員","kind":"質問","question":"１番に関しては、東京都が減らしても品川区が事業の重要性を認めて継続していくという考え方であるのに対して、２番の障害者ホームヘルプサービス事業は東京都が減らすから品川区も減らすという、１番と２番の考え方の違いはどこから出てくるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ただ、先ほども申し上げましたけれども、９０％の、一定の収入しかない方については、利用者負担についてはいただかない。ただ、相応の収入のある方については、収入に応じまして一定のご負担をいただくという考え方をきちんと生かしてまいりたいということです。","id":"exchange-004"},{"speaker":"船波委員","kind":"質問","question":"ですから、収入に応じた負担をしてもらうという考え方も一方では理解できるものの、無料を継続したところで品川区側が非常に大きな経済的な負担を強いられるわけでもないので、これぐらいだったら継続してはどうかと思うんですけれども、そういう検討はされなかったんでしょうか。","respondent":"日下部障害者福祉課長","answer":"トータルの金額でいけば、それほどではないではないかと、それは確かに１１世帯について利用実績と掛け合わせても、確かに金額としてそんなに大きいものではありませんけれども、やはり先ほども申し上げましたけれども。","id":"exchange-005"},{"speaker":"船波委員","kind":"質問","question":"わかりました。この方々がどれぐらいこのサービスを利用しているかお伺いしたいんですけれども、「品川区の福祉」によりますと、回数をどれぐらい利用するかは当事者の状況に応じて決定されるということですけれども、今までは無料で利用できていたものが有料になってしまうという方々の場合、その人が全体で利用している時間のうち週３回９時間というのはどれぐらいの割合のものだったんですか。","respondent":"日下部障害者福祉課長","answer":"そういうことを比べて勘案してみますと、あくまでも障害の程度に応じて派遣の時間とか回数については品川区で決めするということですけれども、必ずしも今後負担があるから利用を抑制されてしまうという結果にはなってこないのではないかと考えております。","id":"exchange-006"},{"speaker":"船波委員","kind":"質問","question":"１番のほうと２番の障害のある方に対するサービスですけれども、平成１５年度以降に新規制度ということになった場合、どういうふうに変化していくものなんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ホームヘルプサービスというのは、支援費制度に措置制度から移行することになります。ただ、これは以前の委員会でもご説明させていただきました。","id":"exchange-007"},{"speaker":"船波委員","kind":"質問","question":"３番のほうですけれども、指定廃止をされてしまう二つの病気に関しては、どうして廃止されてしまうのでしょうか。","respondent":"日下部障害者福祉課長","answer":"私のほうでご説明させていただいて、もしそれ以上の話になれば、専門家のほうから補足をさせていただきたいというふうに思います。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１点目のところからお聞きしたいんですが、今度改正になるところで小規模と中規模となっているんですが、小規模と中規模の違いについて教えていただきたい。２点目の障害者ホームヘルプサービス事業についてですが、II、III、IV段階の所得階層について無料制度をなくすということなんですが、１１名でどれぐらいの予算になっているのか教えていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"人数ですけれども、全体でどのぐらいかということであたってみましたら、最大で２００世帯ぐらいいくのではないかというふうに見込んでおります。ですから、全体の３分の１ぐらい、かなりの方が対象になっております。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１番については、今までは玄関は４９万円までしか使えなかったのが、かかった分はかなり使えるということになってよかったなと思うんです。２番目についてですが、１１人で７８３万円ということなんですが、これが実際に利用者負担額が生じて、本人がこれだけ負担するとなると、品川区が少なくて済む額というのはどれぐらいになるのか、そのことについて教えていただきたい。","respondent":"日下部障害者福祉課長","answer":"ですから、これはそういう意味ではかなり負担のＩ階層も含めるとかなり低いということになります。ただ、Ｉ階層分を除くと大体１８％ぐらいの負担ということになってくるわけです。ですから、確かに介護保険の１割より若干高めにはなってまいります。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そんな中で３０４万５,０００円以上所得があると無料のホームヘルプサービスが受けられないというのは、本当に大変じゃないかなと思うんですけれども、この辺の３０４万５,０００円という考え方というか、しかも生計中心者というところではどういうふうに考えられているのでしょうか。","respondent":"日下部障害者福祉課長","answer":"そういう形で、必要な対応というのを品川区として実施をしていく責任があると思います。そこで生み出された財源も含めて、新たな福祉サービスの拡充に充てていくと、それが品川区としての基本的な考え方でありますので、その辺は十分にご理解をいただきたいと思います。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"Ｃ型肝炎にしても、輸血とか血液製剤によって感染が広がったというところで大きな問題になって、新聞紙上でも話題になっているところですけれども、そういうところでは厚生労働省がきちんとした対応をされなかったためにＣ型肝炎になって、そして慢性肝炎になって治療せざるを得ないという状況になっていると思うんですけれども、そういうところで治療がきちんと、しかも外来の中で完了していきながら。","respondent":"日下部障害者福祉課長","answer":"そういった点では、品川区としても今回の経過措置で医療費助成と手当の支給は別問題ですけれども、品川区は品川区なりに経過措置という形で、おそらくほかの区でもこの辺の実現は難しいところはあろうかと思いますが、少なくとも平成１５年３月までは現行を継続する。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう方が早期発見したら治療に結びついて、そして適正な治療をきちんと続けていくためにも、東京都の先駆けた施策がすごく大事な役割を果たしてきたんじゃないかと思うんですけれども、そういう点ではぜひ東京都に対して難病指定から外すなというところを、品川区からも言っていただきたいなという思いがするんですけれども、その点に関してはいかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"これは専門の委員会の答申を受けて、そのような判断をしたということでありますので、私どもとしましてはその辺の専門的な考え方も含めて、なかなかそれについてものを申すというのは非常に難しい立場にあります。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その中で適切な治療ということに結びついていくというところで、ぜひ品川区からもそういうふうに言っていただきたいということと、あわせて認定というところはそういう形でこれからもできるということであれば、せめて医療費助成が打ち切られ、その上に手当が打ち切られといったら、本当に二重の大変さになるわけですから。","respondent":"小林品川区保健所保健サービス課長、日下部障害者福祉課長","answer":"医療費助成についての申請の経由窓口として、保健所は今まで仕事をしておりましたけれども、患者に対しての療養上の支援については、今までと何ら変わらなく対応してまいりますし。手当の関係ですけれども、先ほどから再三ご説明していますように、おそらくこういう形での経過措置というのは、２３区の中でも非常に一番手厚い形で対応する中身だと思います。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、保健サービス課長からお話がありましたけれども、Ｃ型肝炎、慢性肝炎の通院治療の必要性というところについてはいかがでしょうか、その辺のところが一番大事なところかなと思うんですけれども、その辺について専門家としてご意見をお聞かせいただきたいと思うんです。","respondent":"小林品川区保健所保健サービス課長","answer":"もちろん治療の必要性ということについては、私どもも十分認識しております。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてまた、通院の中で高額なお金がかかるというところでは、それに対しての治療の医療費助成を打ち切るということは、本当に大変な事態になるなと思っているので、ぜひこのことについてはさらに実態を見ながら考えていただいて、品川区としても対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"嶋委員","kind":"質問","question":"そういう中で、所得制限もあるということでお聞きしたいのは、これを使わせていただく場合、障害の程度が進んでいく場合もありますので、特に台所は足の悪い方は車いすで、手も不自由の方もいっぱいいらっしゃいますけれども、何とか家事をやりたいという方がいらっしゃるんですが、こういう場合は限度が超えた部分はお金がかかる場合、もちろん利用者が負担をするんですが。","respondent":"日下部障害者福祉課長","answer":"私もそういうお話を今回初めて伺いましたので、その辺のやり方が、実際の制度の運用上も含めて可能なのかどうかということについては検討をさせていただきたい。できるだけ前向きにその辺が解決できればというふうに思います。","id":"exchange-017"},{"speaker":"嶋委員","kind":"質問・要望","question":"確かに「肝炎の希望者に関しては検査をします」というのが広報であったと思うんですが、ウイルス性という形ではどんどん増えている状況があるので、区民健診での啓発が広報紙以外にどのようにされているのか、もしわかったら教えていただきたい。それから２番目の新規難病指定の６疾病のことなんですが、６疾病がわかりましたら教えていただきたいと思います。","respondent":"田中健康課長","answer":"もともとＣ型肝炎のお話というのは、昨年の６月に当時の厚生労働省が緊急に検査をということで、保健所等でＨＩＶ検査の中に取り込みまして、昨年１０月まで実施をいたしました。","id":"exchange-018"},{"speaker":"嶋委員","kind":"意見","question":"これは後で勉強したいと考えています。これは患者出現率から推計して、５０名ということなんですが、これから新しくスタートするということで、これから状況がわかるということなので、これだけ新しい病気が難病指定になったということは、それだけのスピードでこういう方たちがいらっしゃるということを私たちも認識していきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"須藤委員","kind":"意見","question":"１点だけお願いします。ここまで書いてあるならば、国から来ているからそれを利用するということではなくて、品川区の姿勢としてそういうことがあるならば、その辺はどうなのかなということ。それから、介護保険との兼ね合いというのはどういうふうに絡んでくるのかなと、２点お願いします。","respondent":"日下部障害者福祉課長","answer":"ただ、これ以外にも１級の方、歩行が全くできなくて、最重度の方については屋内移動設備の取り付けということで、屋内に一種のリフトみたいなものをはわせまして、そこで住宅の中を移動ができるように、これはかなり大規模なものですけれども。","id":"exchange-020"},{"speaker":"鶴副委員長","kind":"質問","question":"そこで、一、二点、障害者福祉サービスの改正についてお伺いをしたいのでありますけれども、給付の今回の変更にあたっては２種目に小規模、中規模というふうに改修できるようにあるんですが、給付を受けたいと思う人は事前に設計図とか、そういうものを当該課に申請して、そして当該課が職員を派遣するなり審査を行って給付の額を決定するということになるのでしょうか、そうではないのでしょうか。","respondent":"日下部障害者福祉課長","answer":"それをもとにそれぞれ利用者の方がお考えになっているような改修の内容とか、経費の問題とかいろいろ付け合わせをさせていただいて、正式にご申請をいただくという形で手続を進めていくという形になっております。","id":"exchange-021"},{"speaker":"鶴副委員長","kind":"質問","question":"従来、介護保険制度がスタートする前にありました高齢者等を対象にいたしました住宅改修リフォームについて、いろいろな助成制度がありました。段差解消とかお風呂の改修だとか、手すりの改修だとか、もろもろが入って上限が決められておりましたが、その比較においては遜色のあるものですか、ないものですか、詳しく説明していただけませんか。","respondent":"日下部障害者福祉課長","answer":"障害者の住宅改造についても、かなりそれなりの歴史が長い経過をたどっておりまして、高齢者の住宅改修のほうと全く同一ではありませんけれども、大体中身としましては同じような中身を基本にして制度を運用してまいりましたので。","id":"exchange-022"},{"speaker":"鶴副委員長","kind":"質問","question":"今回大きくわけて三つのサービスの改正につきましての当該受益者がそういう事業の対象となるであろうと思われる障害者の方々に対する説明というか、改正の徹底というのはどういう方法でなされるわけでしょうか。","respondent":"日下部障害者福祉課長","answer":"やはりこれについてはケースワーカーがそれぞれの障害者の方の状況を一番把握しておりますので、ケースワーカーがしっかりとそれぞれの方について、対象となるような方については、その辺の内容を十分に個別にも周知をしていくと。","id":"exchange-023"},{"speaker":"鶴副委員長","kind":"質問","question":"要するに、しかるべき措置をとっているという、他と違った施策の展開をやっているわけですから、そういうことも含めてしっかりと、広報「しながわ」にはスペースの関係があります。アンケート調査を取るということは大変ですので、ホームページに「意見があるならどんどんご意見を述べてください」というようなことを載せていたほうがいいのではないかというふうに思うんですが、いかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"委員の冒頭のご指摘の中に、説明責任ということがございました。品川区としましては、確かに制度を改正するわけですから、そういった意味では議会に対しての説明をしっかりと説明責任を果たす。それと同時に、やはり区民の皆さん方に対しても説明責任をしっかりと果たすと。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"説明、ご苦労さまでございました。何点かになろうかと思うんですけれども、一つ大きなことで、この提言が出た後、保険者としての品川区はこのことに対してどういうふうに取り組んでいくかということの大きな方向性を教えていただきたいのが一つ。だから、これをただ提言だけに終わらせるのではなくて、何かしら品川区としてやっていく必要があるのではないでしょうかということをお聞かせください。","respondent":"新美保健高齢事業部長","answer":"もう１点目が、第１期の２年間、介護保険導入準備段階を入れて３年が過ぎまして、ケアマネジメントは品川区の場合、何とか区民の方には９割以上の方におおむねご信頼はできているかと思うんですが、今後のことを考えますと、さらに今後成熟期といいますか。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"実際、提供しているサービスがどうなっているかということをフィードバックするシステムが今のところないというわけですから、これはおそらく業者も初めてのことでしょうから、いろいろ戸惑いながらやられていたんでしょうけれども、それをまたフィードバックしていいサービスがつくられていく仕組みをつくっていくことのほうが、はるかにこれからの傾向となっていくと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９ページに在宅介護支援センター別抽出結果というところで、ケアプラン作成数が出ているんですけれども、ケアマネージャー６３名のセンター別の数を教えていただきたいと思います。この報告書を見て、現場のケアマネージャーの方々が本当に大変な中で、悩みながら利用者の方との信頼関係をつくるというところで、本当に努力をしながら頑張っていて大変だなというのが実感したわけなんです。","respondent":"新美保健高齢事業部長","answer":"３点のお尋ねがあったんですが、長期基本計画の中でサービス評価につきましては、基本的なサービスについてサービス向上の仕組み、つまり手法の開発・実施ということを含めて、３年間で仕組みづくりをしようということで考えておりまして、３年目が今年度ですが。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そんな中で、ここのケアマネージャーの方々の質問項目の中で、「できている」「できていない」というのがあって、「できていない」の割合が相談時間が取れていないとか、情報収集、課題分析というところで３割とか５割を超える項目もたくさんあるわけなんですけれども、この結果に対しては品川区としてどういうふうに考えられているのかお聞かせいただきたいと思います。","respondent":"高橋介護保険担当課長、新美保健高齢事業部長","answer":"最後のケアマネージャーの研修について、福祉カレッジだけであるかという部分ですが、年が明けますとそれぞれの在宅介護支援センターに呼びかけて、新人を含めた研修を４日間ぐらいやってあります。訪問看護について、サービス評価の対象にするかどうかは、今年度が３年目で来年度以降どうするか品川区介護サービス向上委員会での検討の時期ですので、品川区介護サービス向上委員会の中で検討をしていきたい。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にこれだけ大変な声というのが出されて、やっぱり私も本当に大変だったなというのを改めて思ったわけですけれども、こんな中で一つは先ほど言われたように、研修や情報交換、悩み、それからカンファレンスとか、そういう形のものを充実させるというところと、やっぱり体制をきちんと取っていくということが求められているんじゃないかと思うんです。","respondent":"新美保健高齢事業部長","answer":"まさにここにつきましては、今年度介護保険事業計画の改定を含めて、第二期へ在宅も含めてどういう課題設定をしていくか、体制を敷いていくか、今年度の検討事項ですので、その中でこの提言も受けて十分ご意見もいただきながら、実態も見ながら。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところなんですが、ずっと民間の居宅介護支援事業者の方に対しても説明会をしてほしいということで、今年の２月にされたと思うんですが、その中でどのような民間の居宅介護支援事業者の方からの意見が出されたのかお聞かせいただきたいんですけれども。","respondent":"早津高齢福祉課長","answer":"２月に行った民間居宅事業者との話し合いですが、大きなテーマは東京都が実施した利用料軽減についてどう扱うかということを説明しつつ、いろいろなご意見をお伺いいたしました。こういった会を開催してほしいというような意見等、さまざま出ておりました。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはり、こういうところでは今回はケアマネジメントに関するサービス評価というところで、在宅介護支援センターだけでしたけれども、ケアマネジメントを行っているところは在宅介護支援センターだけではなくて、品川区の中では１割弱の区民が実際にケアプランをつくられている介護支援事業者があるわけですので、やはりそういうところも本当に一生懸命やっていると思いますので。","respondent":"早津高齢福祉課長","answer":"事業者の場合も、非常に少ない方もありますので、その場合に一人、二人というような方のご意見を聞いたのが、事業者の評価につながるのか、いいか悪いかというようなさまざまな問題もあります。介護サービス向上委員会の中で検討をしていきたいというふうに考えてあります。","id":"exchange-031"},{"speaker":"嶋委員","kind":"質問","question":"そういう意味では、いろんな意味で尊重していただく部分もあると思いますが、品川区として部課長クラスが１７在宅介護支援センターへの激励といいますか、「頑張っているね」という声とか、背中を押すというのがどのぐらいのペースで１７カ所を回っていらっしゃるのか、この１点だけお聞きをしたいと思います。","respondent":"早津高齢福祉課長","answer":"例えば、特別養護老人ホームと併設の在宅介護支援センターですと、特別養護老人ホームへ行く回数が、それ以外のところと比べると多いので、そのときに行くとかということで、在宅介護支援センターによってばらつきが出ているのは事実なんですが。","id":"exchange-032"},{"speaker":"須藤委員","kind":"質問","question":"平成１４年３月に答申が出されたんですけれども、答申が出された時期は介護保険制度が始まってどのくらいの期間が経ったんでしょうか。","respondent":"早津高齢福祉課長","answer":"３月ですので、約２年ということになります。","id":"exchange-033"},{"speaker":"須藤委員","kind":"意見","question":"去年の４月ならこの表現でいいんだけれども、１４年３月に出てきたときに、「まもなく２年を迎えよう」という表現で答申書を出してきてしまうと、ちょっとあれっという思いがあるんだけれども、カウントの仕方が私が違うのかな。","respondent":"新美保健高齢事業部長","answer":"確かに、よくご記憶をいただいております。昨年は確かに「まもなく１年を迎えよう」という形で最初のページが始まっておりました。","id":"exchange-034"},{"speaker":"須藤委員","kind":"質問","question":"「まもなく丸２年を迎える」とかという表現ならそれで済むけれども、「２年を迎える」というのは、「これから丸３年を迎えよう」という表現ならいいと思うんです。昨年もあったので、直るかなと思ったら直っていないので。もう１点、利用者の回答率が５８％、そのときの介護度については１１ページに載っているんだけれども、返答のない４２％の人の介護度というのはわかりますか。","respondent":"新美保健高齢事業部長","answer":"今回、抽出を全数ではなくて、全体の３分の１程度を無作為で抽出したので、介護度別にバランスを取るというのはなかなか難しくて、結果どういう要介護度かしか、ここではわかりません。","id":"exchange-035"},{"speaker":"須藤委員","kind":"質問・要望","question":"回答した中で１割も３割を回答していないというと、本当の回答者というのは、そのことに対しては逆に言うと３割、４割というような数値の回答しかないというふうに考えられると思うんですけれども、そうした場合と全部１００％回答しましたよという事業者、管理者、そういうところの回答者と同列に比較をして統計上の分析の仕方がいいのかどうか、その辺はいかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"ただ、ここにも見ておりますように、ホームヘルプと比べまして、確かに無回答の率が１０ポイントほど全体に高くなっておりますので、ケアマネジメントといったときのわかりにくさというのが、どうしても無回答の回答が多くなる傾向は受け止めざるを得ないので。","id":"exchange-036"},{"speaker":"須藤委員","kind":"質問","question":"先ほど質問したのは、無回答のところが多いのが３割なんぼ、少ないのは１割ちょっとあるわけです。そうすると、５８％ぐらいの回答率で４２％は回答しないという中で、まだ無回答がありますよといったパーセンテージと、それから１００％回答してきた事業者とか管理者と比較をそのまま同一にしちゃって、統計上それがきちんと見られるのかどうか、それでこの分析を最後に書いてあるわけです。","respondent":"新美保健高齢事業部長","answer":"やはり、数も３分の１やっておりますので、６割の回収率であれば大筋の傾向を見るべきものという認識でおります。３６ページの評価も、今申し上げた程度の、ただ全体の傾向としては、どうしても同じ局面に対してケアマネージャー側が厳しく評価している。","id":"exchange-037"},{"speaker":"須藤委員","kind":"質問","question":"半分以下の回答率でそれを評価しちゃうというと、違った方向に走っちゃう可能性も考えられてくるので、アンケートを取るときにその辺のところも今後考慮されて、先ほど言った返事がなかったのはどういう人たちなんだという、それは介護度がきついからできなかったんだとか、いろんな状況があろうかと思うので、そういうことをきちんとつかんでいただかないと。","respondent":"新美保健高齢事業部長","answer":"今回、初めてこういう形でやりましたので、ご意見あるいは今後の状況と、また何年かに１回ずつ繰り返しやっていく形を取っていきたいと現時点では考えておりますので、そういったところにもう１回工夫をしていきたいというふうに考えます。","id":"exchange-038"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"事業者がやるのか、あるいはやっぱり品川区が主体的となって、そういう場をつくって心の状況というか、サービスの職員としての心構えというか、つらいけれどもお年寄りのために、あるいは障害を持っている人たちのために使命と誇りを持って、困難を乗り越えてお世話することに喜びを感じていくというような、サービスを受ける側にとって安心を与えていくという。","respondent":"新美保健高齢事業部長","answer":"大変難しい課題についてのご質問ですが、ただ私どもも介護ということは、単に個々のサービスを提供すればいいというだけでは、なかなか在宅介護を全体的にサポートしていくことにはならないという認識は持っておりまして、そういう意味では今度の報告書も１ページ、２ページ。","id":"exchange-039"},{"speaker":"鶴副委員長","kind":"質問","question":"そこで働いている福祉職員といいましょうか、その人たちの処遇というのは一体どうなっているのか。それはあまり望ましいことではない、あるいは愚痴なのかもしれないけれども、一体どうなっているんだろうと思うんです。何かわかれば、わからなければわからないでいいんですが、どうなっているんだろうというものがありますので、わかれば教えていただけませんか。","respondent":"新美保健高齢事業部長","answer":"ただ、社会福祉法人については、今までどうしても措置時代の東京都としての一定の水準とかルールとかありましたので、それを踏まえておりますが、介護保険になりまして、やはり今後どうしていくのか、それぞれの法人ごとで独自に工夫をし。","id":"exchange-040"},{"speaker":"高木委員","kind":"質問・要望","question":"今の副委員長のご意見に私も感ずるところはいっぱいございまして、特に鶴委員とは同じ期間少し長めになったかどうかやらしてもらっているものですから、よく副委員長は手の届きすぎるような、そしてこれは表現がしにくいんですが、関心して聞いていたんですが、私も最初は介護事業という、とにかく大変な命題に向かって大層ご努力されているということは、私はもうまちの中へいっても一生懸命言うんです。","respondent":"新美保健高齢事業部長","answer":"今後は特別養護老人ホームは入所者の声をどういうふうにしていくかという、これにつきましてはなかなか単純にはいきませんけれども、今ご意見があったような利用者本人をどういうふうに声を把握するか、その辺を工夫していきたいというふうに考えております。","id":"exchange-041"},{"speaker":"高木委員","kind":"意見","question":"今年から保険料の通知が来まして、ぎょっとしました。私は１年間分６万５,０００円ぐらいかな、これは深刻になりましたね、１年間まとめて納めるとするとですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３３ページのところに質問１４「モニタリング情報の収集（事業者より）」というところで６８.３％が「できていない」、それから質問１７「必要に応じた再アセスメントの実施」というところで５５％が「できていない」という回答をしているんですが、この辺のところの実態についてと、本来あるべきモニタリングがどうなっているのかお聞かせください。","respondent":"早津高齢福祉課長","answer":"ただ、中には残念ながら行ききれていないのもあることは事実です。なるべくこのようなことのないように、私どものほうでもモニタリングを継続的に行うようにということをお願いしています。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本来であれば、１カ月に一度くらいは利用者のところにケアマネージャーがお伺いして、実態を見るということが必要だというところなんでしょうか。","respondent":"新美保健高齢事業部長","answer":"どの程度の頻度ですべてということになりますけれども、今のケアマネジメントの実態と介護報酬における体制の取り方からいいますと、すべてを１カ月に１回行くというのはなかなか難しいかと思いますし、それが本当に必要かどうかということにもなるかと思います。","id":"exchange-044"},{"speaker":"林（和）委員長","kind":"質問・要望","question":"その他に移ります。私のほうからご案内を申し上げます。継続となっておりました、平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願につきましては、次期の委員会に申し送りたいと思いますが、よろしゅうありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鶴副委員長","kind":"質問","question":"この１年、各委員の熱心な、かつ活発な質問、提言等をはじめ、各理事者の真剣かつ適切な各事業に対する事項の説明および造詣の深い答弁により、今年度の厚生委員会も多くの成果をおさめることができたのではないかと思うのは私ばかりではないのではないかというふうに、今ご推察をしています。この１年、本当にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270319?Template=document&Id=3016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":44792,"voices":103}},{"id":"h14-20020508-8","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"建設委員会","time":"午後１時０５分～午後３時１０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"平成１３年請願第５号、住友不動産による「仮称 大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","agenda":"平成１３年請願第５号、住友不動産による「仮称 大崎５丁目マンション」超高層、高さ１００ｍ、３０階建てに対する請願","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"ちょっとお尋ねなんですけど、４月２０日に守る会、地元の方々と本協定を結ばれたという話を伺ったんですが、あわせて、今その関係じゃないんですが、それとの係わり、今ご説明の中で、都の建築審査会ですか、住民が総合設計の取り消しですか、一言で言えば、それを出しているという話が、今説明あったかと思うんですが、現場のほうは工事が始まっているような状況のようなんですけれども。","respondent":"浜脇住環境整備課長","answer":"前回もお話ししましたけども、工事自身は２月１日から着工しているというふうになっておりまして、着工する前に、本来ならば工事協定書を結ぶというふうになっておったわけですけども、結べなかったので、やっと４月２０日の日に結んだから。","id":"exchange-001"},{"speaker":"築舘委員","kind":"質問","question":"この本工事協定を結んだ守る会というのは、この請願書を出している大崎および品川の環境を守る会ということでよろしいんですか。","respondent":"浜脇住環境整備課長","answer":"はい、冒頭にありましたでしょうけども、大崎および品川の環境を守る会ということで、請願代表者以下1,９６６名という方々だと思われます。しかし、そのうちの何名かがそういうことで、会じゃなくして、個人的な形で出されているというふうに聞いております。","id":"exchange-002"},{"speaker":"辻委員","kind":"質問・要望","question":"継続していただきたい。私も前から言っているように、４番目の違う部分、４番目は難しいなというのはわかります。ただ、個々の問題についてはちょっと大きい問題ですから、その部分、その分野分野、地域地域によって、このマンションではこれは日照の問題、こっちについては風害の問題とかというふうな交渉に入ったよということですね。継続で、できればお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"できることなら、紹介議員の方に、一部の方がそう出て反対するというのは、これは請願者とまた違うものですから、ある程度これで目的を達したんならば、じゃあ今まで継続して時間を持ったことで議会としての役割を終えたという評価をしていただけるんだったら、取り下げてもらうのが一番いいかなという気がするんですけど、そういう可能性があるかということでしたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"本間委員","kind":"意見","question":"大変難しいことになってしまいましたですね。ただ、今、辻委員のお話、知らなかったんですが、そういう部分をどういうふうにして配慮していくか、ここで結論を出すことによって、その皆さんに対して、逆の意味での、それを出したことによっておかしくなるのであれば困るということは確かにあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"辻委員","kind":"質問","question":"今の項目は、大崎および品川の環境を守る会が交渉してきたわけですよね、こういうのをやってくれないかというふうな、日照被害のこともやってきたと思う。それで、それが多少手直しができた、ですから、沢田委員が話したように、どういう扱いをするか、不採択で願意に沿いがたいというのもおかしな話だ。ですから、こういう状態になっているんですよということをもう一回請願代表者にちょっと話してみたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"それで、いつも悩んでいて、議会側として、それをその話し合いのさなかに採択するということは果たして妥当なのかどうなのかということもあって、継続をしながら調査したり審査して、ある程度当事者間の話し合いの進行を見届けるというか、それで、不満があっても協定できて解決をして、そこでやるんですけど、そのときの、一つはそうしたやり方でずっと来ていますよね、全体としては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-02","title":"平成１３年請願第６号、石井ビル建築計画に関する請願","agenda":"平成１３年請願第６号、石井ビル建築計画に関する請願","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"そうすると、これは誓約書を提出して着工したということは、基本点では合意に達したということなんですか。","respondent":"浜脇住環境整備課長","answer":"合意に、実は項目がたくさんあった、１２項目ぐらいあって、半分ぐらいしかその項目に対して誠意といいますか、変更できなかったという事情があったようでございまして、１００％のいわば言い分ですね、住民側の言い分を聞いたわけじゃございませんので。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"この問題についても請願者、区議会議員を通じて特に取り下げることはしないと。そのまま出してくださいということなんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"これは請願項目としては三つ挙げていて、中層棟の設計変更というのと、それから安全な工事を十分説明するようにというのと、みんなアンダーラインしてあるところがメインですよね。建築業者と十分話し合いできるようにと言っているんで、さっきの趣旨採択とのバランス上、こっちはだめだというふうにいかないから、この程度であれば趣旨採択としていいんじゃないでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"築舘委員","kind":"意見","question":"一番いいのは工事が進んでいるので、取り下げてもらえばいいかなというふうには思うんですけど、それが難しいというさっきの委員長のお話なので、大分進んでいて、そんなに、そういう意味では趣旨に関しての採択をしても、別にその後の影響がなければ趣旨採択ということでいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"辻委員","kind":"意見","question":"こういうの、ＣＰのやるの。区民にもうちょっとアピールして、やっていることを知らしたほうがいいと思うんですよ。そうすれば安心感もあるだろうし。だから、ギャラリーがどうこうというのは別として。やっぱり、そういうＰＲをして関心を持たせたほうがいいんじゃないかな。","respondent":"中谷まちづくり事業部長","answer":"本件につきましては、広報等につきましても連携いたしまして、パブリシティー等お願いするということになっておりまして、また、デジタルビデオ等で撮影いたしますので、そういうものでＣＡＴＶ等で周知できる余裕があれば、そちらにお願いするということにしていく予定です。","id":"exchange-012"},{"speaker":"辻委員","kind":"質問","question":"このデータを出したときに、沿線の住民に対しては、どういう形でバックするんですか。","respondent":"中谷まちづくり事業部長","answer":"将来的にはＣＡＴＶ等に放映するということも考えられますし、今年、事実ＣＡＴＶで情報等を提供するように今ちょっと検討しておりますが、それとあわせてやることも将来的には考えられますし、運用についてはちょっとしばらく思考させていただきたいというふうに考えております。","id":"exchange-013"},{"speaker":"辻委員","kind":"意見","question":"今度短い幹線の中で、その辺をどうやって知らせるか、地域の人との連携を十分その辺をやっていかないと、特に立会川も既に動いているようですけど、要するにどの辺まで知らせていいかというのも難しい。サイレンが鳴ったらどういうふうになるのか。クイックプランとしての全体的なそういうものをリアルタイムですることは非常にいいことで、ただそれをどう使うかということを要するに住民がどうすればいいか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"これは四角になっているけど、下水管の中の水位ですよね。そうすると、形は丸と。ちょっと初歩的な質問で。","respondent":"中谷まちづくり事業部長","answer":"普通下水管というと管が、円形管が多いわけですが、ここは戸越幹線と立会川幹線については矩形渠ということで、四角い断面になっておりまして、四角い断面の中に、真ん中のところに少し常時水が流れる。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"光ファイバーケーブルなんですけれども、東京都なんかは下水管に光ファイバーを通して、これを売って一もうけするみたいな、前にそんな報道があったと思うんですが、基本的には全部入っているものなんですか。","respondent":"中谷まちづくり事業部長","answer":"ただ、従来から、１０年近く前から都庁周辺では光ファイバーを試験的に敷設して、それで試験をやっていたということもありますし、今回についてはこれはあくまでいわゆる管の管理、下水道施設の管理、それを都民に役立てるという観点で、これを品川区にも提供するということで。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問","question":"ですから、それはやっぱり逐一ブザーかなんか、目視じゃなくてブザーかなんかで知らせてくれるんだと思うんだけども、そこら辺がどうなっているのか１点と、今の防災無線、要するに防災無線が品川全域に対して面というか、地域で何系統ぐらいに分かれているのか、こちらのほうで、要するに機械操作で品川区１方面、２方面、３方面という、そういう分布のもとで。","respondent":"中谷まちづくり事業部長","answer":"それから目黒川流域だけ知らせるもの、立会川流域だけのもの、それから戸越幹線流域だけでもできるようになっているということで、これは先般にいじくった際に、そのような形で変更しておりますので、今回ですから、このシステムが確立されれば。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問","question":"今、確かに幹線ごとにそういった防災無線系統ができているというのはよかったです。それとあわせて、品川全体、一つですかね、それとも荏原地区、大崎地区、品川とか、そういう分け方はされてなかったですかね。ちょっとその系統図、どういう系統、今言う河川はわかったんだけど、品川区全体じゃなくて、地域的に分割されていると思ったけど、その辺のちょっと内容を知りたい。","respondent":"中谷まちづくり事業部長","answer":"ちょっと防災課の所管で、私どももどの程度分割できるかという話、細かくは聞いておりませんが、あれはいずれにしても手を加えればできるというふうには聞いておりますが、どの程度細かくなるのかというのは、ちょっとそこまでは承知しておりませんので、もしよろしければ。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問","question":"片方でお家へ帰ろうと行っているのに、片方じゃほかのやつで、同じ５時にポーンと鳴り出すんだね。ですから、そういった地域には系統を外してほかのものをやるとか、何かやっぱりそういった配慮が必要かなと、そう思ったものだから、今これに引っかけて聞かせてもらったんだけど、そのあいだにいると、ほんとうにうるさく聞こえるというか、何を言われているかわからない。参考までに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"辻委員","kind":"質問","question":"月見橋の雨水対策工事でしょう。ですから、月見橋まで雨水下水管を引っ張ってくるの。立会川のあいているところはどうなるの。","respondent":"中谷まちづくり事業部長","answer":"前のとき、図面でこちらで下水道課長がこの図面の大きい図面ですが、これで説明させていただきましたが、月見橋までシールド工事で立会川幹線の放流橋ですが、これを内径3,２００mmの管を月見橋まで抜きまして、到達立坑をつくりまして。","id":"exchange-020"},{"speaker":"築舘委員","kind":"質問・要望","question":"立坑用地の整備ということで、樹木の撤去ということが書いてありますけど、前に桜があって、それを松にしたかな、本間委員からのご指摘があったんですけど、そういうことがありまして、だから、今回松が植わっているんですけど、それをどういうふうにして、どういうふうに今度持っていくか、ちょっと教えていただきたい。","respondent":"中谷まちづくり事業部長、佐藤委員長、中島街路事業担当課長","answer":"以前、大変私ども行き届かなくて失礼を差し上げたわけですけど、今回につきましては、これについては、撤去というのは概要の言葉で書いてありますが。ほかに。なければ、本件の質疑を終了いたします。先般、４月１５日の本委員会におきまして、４月２７日に用地説明会をするということでご報告させていただきましたけれども。","id":"exchange-021"},{"speaker":"上山委員","kind":"質問","question":"ちょっと、前にも聞いたかもわかりませんが、今回測量の説明会、用地の説明会を同日でやられているかと思うんですが、今これでまだ説明会は２７日ですから、連休を挟んでいるから、あるかと思うんですが、例えば、買収の話ですよね。","respondent":"中島街路事業担当課長","answer":"今のご質問は成立したということですか。","id":"exchange-022"},{"speaker":"上山委員","kind":"質問・要望","question":"ちょっとその関係で、私、さっき土地収容暫定補償の話がちょっと出ていたかと思うんですけれども、いろいろな形態だとか、いろんな状況でいろんなものが出るかと思うんですけれど、ちょっとわかりませんが、一般の話で恐縮なんですけれども、中にはこういう形で、例えば形状が小さくなって、買ってくれればいいんだけど、うまく折り合いがつかなくて、それは困ると、わかりませんけどね、もし。","respondent":"中島街路事業担当課長","answer":"そういった部分では、いろんな形で残地ということが生じる可能性があるわけですけれども、そういった不動産業者の方と連携を密にしながら、情報交換しながら残地について、うまく、いわゆる民民での売買可能な形にできればというふうに判断しております。","id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"その問題で、買収を進めていくという問題は、どうとらえたらいいんでしょうか。","respondent":"中島街路事業担当課長","answer":"それでもう一つ、例えば残り１軒とか２軒とかという場合、先ほどこちらの補償の説明の最後のほうにあるんですけれども、私ども、とにかく収容部分につきましての事業なもんで、実際そういうことのないようにということで進めていくわけですけれども、伝家の宝刀というんですか。","id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"成田だってそうですよね。ちょっと説明をお願いしたい。それから、再開発と街路事業としての用地買収というのは、再開発というのは、どっちかというと権利変換じゃないですか。例えば、用地買収して、うちは例えば再開発を希望するから売らないよと言った場合に、どう処理を、とりあえず買いましょうみたいな形でやるのか、そこらがもう一つ見えないんですけど。","respondent":"中島街路事業担当課長","answer":"最初にちょっと再開発との関係ですけれども、私どもが道路用地として買収する蓄積といいますかね、そこは再開発の区域とは違うところです。","id":"exchange-025"},{"speaker":"辻委員","kind":"質問","question":"要するに真ん中の新築でもいいわけですけれども、民民の境界をやっていくというのは慎重にうまくやっていかないと、真ん中に挟まれている人なんていうのは、要するにどこかで真ん中というのがよくあるんですよね。その辺の心配というのは非常にある。その辺の折衝なんていうのはまさしく課長のほうでやっていくんですか。","respondent":"中島街路事業担当課長","answer":"ですから、先ほどの資料ですけど、２ページ目にＡさんの土地とありますけど、すべての点を決めるのに、すべての線を決めるのに、こちらに隣接している人すべての合意を得られないと、要するに境界が確定していかないわけですので、そういった面で。","id":"exchange-026"},{"speaker":"辻委員","kind":"質問","question":"ぜひ慎重に、７７人という人しか来てないようですけど、もっともっと該当する人もいるでしょうし、そういう意味では、背後地にも関係するわけですから、慎重に、ここでボタンをかけ違っちゃうと、それこそ先ほど沢田委員から話が出たように、感情のもつれが出たって、それじゃどうしようもないと思いますので、ぜひお願いしたいと思います。","respondent":"佐藤委員長、田村住宅課長","answer":"ほかに。ほかになければ、本件を終了いたします。区民住宅の空き家入居者予定登録募集についてご報告申し上げます。１、募集内容ですが、１４年６月の区民住宅（空き家）の入居予定者の登録募集です。内容は家族用、単身用です。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"宅建管理センターに委託をしたというのは、どういう委託をしたのかというのと、株式会社宅建組合が会社を設立したんだと思うんですけれども、さっきの話だと、抽選もここに任せるんですか。ちょっとよく聞き取れなかったんで教えてほしいんですが。","respondent":"田村住宅課長","answer":"厳密に言いますと、品川都市整備公社と宅建との契約ということになりますが、３社で区のほうも入って、宅建品川支部と、そんなに前から、やはり既存の区民住宅、ご存じのとおり、かなり地域に分散しているというような状況がございまして。","id":"exchange-028"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、宅建管理センターに委託した委託内容というのは何と何なんですか。","respondent":"田村住宅課長","answer":"入居者管理というのは、具体的には使用料の徴収あるいは滞納、短期滞納者の対応、あるいは苦情があった場合の対応、よく中で水をこぼしちゃったとか、そういうような苦情があったときの対応、それと、建物の維持管理、大きく入居者管理と建物の維持。","id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"荏原青果の跡の区民住宅の管理を、あれはどこでしたっけ。大手にという話がありましたよね。それとこれとの関係はどうなんですか。","respondent":"田村住宅課長","answer":"Ｃ棟のほうは複合棟ですので、まだ具体的にどこに委託管理するかは決まっておりません。今後調整して検討していくという形になります。","id":"exchange-030"},{"speaker":"築舘委員","kind":"質問・要望","question":"さっきは都市計画道路事業により移転する方に対して品川区では区民住宅、区営住宅のあっせんする制度があるということが書いてありましたけど、あけておかなきゃいけないといいますか、区民住宅であけなきゃいけない部屋というんですか、そういうのはどの程度の間隔でとってあるのかということと、それからあと、空き家の２０団地というのが多いのか少ないのか、ちょっと今の時代わからないんですけど。","respondent":"田村住宅課長","answer":"今回の事業に基づく……。","id":"exchange-031"},{"speaker":"辻委員","kind":"質問","question":"その場合、資格審査は区がやるの、それとも、委託先ですか。","respondent":"田村住宅課長","answer":"やはり、入居決定そのものは区がやらなきゃだめ。先ほど自治法でやらなきゃならないとなっておりますので、最終的に区のほうでチェックして、抽選という形になります。","id":"exchange-032"},{"speaker":"沢田委員","kind":"質問","question":"２回目になってすみません。区民住宅ができてから１０年たちますか。だんだん前の家賃を引き上げていくということになっていますよね。そうすると、早く建ったものの家賃は、古いは、家賃が高くなるはというんで、だんだん空きが大きくなる傾向はないですか。","respondent":"田村住宅課長","answer":"一概に、確かに一番古いのですと、平成４年度の借り上げが一番古いですから、既に１０年経過ということで、ご存じのとおり２０年の傾斜家賃になっていますので、やはりかなり金額的な、最初の設置当時から比べると、金額的な面では上がっていますが、必ずしも立地条件だとか。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"最初、たしか５％ずつ上がりましたよね。それで、今３％になったんだけど、３％で２０年だと６割ですよね、上がるのが。上がっていくとなれば、早晩空きが出てくることを、埋まらないということを想定しておかないとまずいんじゃないかなと思うんですけど、それはないんですか。","respondent":"田村住宅課長、山室住宅指導担当部長","answer":"収入により家賃が異なりますので、支払いの、そうすると、やはり、例えば沢田委員がおっしゃっているように、収入部位が一番高いですから、そうすると、ほとんど補助金がつかない、本来規定の家賃に近い家賃だと。ですから、空き家がその時点で発生するかどうかというのは、民間の賃貸住宅市場の動向によるわけですが、基本的にその間、２０年たてば我々のほうの家賃補助といいますか、公的な住宅としての性格は今度借上型の場合は手を離れて。","id":"exchange-034"},{"speaker":"沢田委員","kind":"質問","question":"１０年前というと、バブル崩壊して２年ぐらいたったときで、家賃はまだグーンと今より高くて、そこから地価がグーッと落ち込んでいるわけですね。品川が持ち出せばいいけど、そんなのはやっぱり制度としてはあり得ないことですから、どうも私は不安でしようがないんですけど、ここで言ってもしようがないですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/923086?Template=document&Id=3718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34167,"voices":135}},{"id":"h14-20020508-9","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"文教委員会","time":"午後１時０３分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"川西委員","kind":"質問","question":"ですから、一貫校の第二日野小学校が目指して、平成１８年開校のモデルとして、既存の小・中学校はすぐ一貫校にはならないですね。意見です。それで、多少は説明の中でおっしゃっていたけれども、平成１８年開校までの施設計画というのは、組織づくりはできているんですか。それから、ここにあります準備委員会の開催の計画というのは、例えば月に一遍やるとか、二遍やるとか、その辺を教えてください。","respondent":"富田教育改革担当課長","answer":"小中一貫校準備委員会の開催計画につきましては、昨日第２回目を開催したところですけれども、当面、月に２回ペースで開催していきたいと考えておりまして、施設計画検討部会につきましては月１回程度。","id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"もう１点、施設計画検討部会の庁内のスタッフというのはもう大体固まったんですか。何課がどういうふうに参加するか。","respondent":"富田教育改革担当課長","answer":"施設計画検討部会のメンバーですが、予定校の第二日野小学校長、日野中学校長、第二日野小学校ＰＴＡの代表、日野中学校ＰＴＡの代表、地域の代表といたしまして、大崎第一地区町会自治会連合会の代表、建築専門家といたしまして国立教育政策研究所の総括研究官、若月教育長。","id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"今のはよく分かりました。体育館の複合化とか、お考えが多少ありますよね。それは区も含めてのことだと思いますが、その辺はいかがですか。","respondent":"鷹倉庶務課長","answer":"それの外側にといいますか、体育館のほうの検討委員会というのを大きく立ち上げていきたい。準備をすでに始めてありますけれども、それと、施設計画検討部会とのパイプをつなぎながら、建物全体の形を形づくっていきたい、こういう考えを持ってあります。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"小中一貫校検討準備委員会のメンバーの氏名をもう一度教えていただきたいと思います。二つ目には、説明会の関係ですけれども、この回数やられて、参加者が大体１２３名ですね。これで説明会は終わりだというつもりなのかどうなのか。とりあえず今の、例えば第一日野小学校から第四日野小学校までの生徒数は８６０名ですね。自分たちの問題としては、どういうニーズなのか。最初に教えてください。","respondent":"富田教育改革担当課長、鷹倉庶務課長","answer":"小学校ＰＴＡ連合会会長代理、中学校ＰＴＡ連合会会長、小学校校長会会長代理、中学校校長会会長、公募区民として２名、学識経験者といたしまして、帝京大学名誉教授、同じく学識経験者といたしまして、東京学芸大学教授。小中一貫校検討準備委員会とか部会があるわけですけれども、本来、ここを経てプラン２１推進委員会、教育委員会、あるいは文教委員会、こう説明をしながら、本来地元に入っていくのが筋かなと思っているんですけれども。","id":"exchange-004"},{"speaker":"桜井委員","kind":"提案","question":"漢字とかわからないので教えてください。だから、そういう点では、もちろん関係者もそうでしょうし、それから、今お話のあったＰＴＡ全体もそうだし、これから上がろうとしている、町会の回覧で回すということにとどめないで、以前、公聴会というところの設定をして、いろいろ広く意見を聞くということを提案したことがあるんですけれども、その辺についてはどうなんですか。","respondent":"鷹倉庶務課長","answer":"公聴会という部分については、今のところ考えてございません。いろいろお知らせする手だては考えていかなければいけないと考えていますけれども、今のところ委員ご提案のことについては考えてございません。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問","question":"それは何か理由があるんでしょうか。後で質問もしたいと思うんですけれども、もともと教育というのは基本的には親の願い、子どもの願いというか、地域の願いに沿ったものになるわけですね。だから、そういうことで、いろいろな意見を聞いて、あるいはこういう点についてはどうだとかと聞くというのが基本だと思うんですけれども、公聴会を避けるというのはどういうことなんでしょうか。","respondent":"鷹倉庶務課長","answer":"避けるということでなくて、意見を聞く場というのは、いろいろな機会があるわけです。我々はシステムを説明しているとおり、いろいろなところで意見を集約された形で固まったものでなくて、案という形でお示ししていって、話を聞くという形で、まさに聞く場を設けております。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問","question":"今の学生というか、学校教育法に基づいて、１年生、２年生、３年生は何歳で行くという形ですね。これを「年齢主義」という学問的な言い方というのはあるんですか。そのことをすごく問題にしているんでしょうか。６歳で１年生に上がるということを問題にしているんでしょうか。それは当然ですよね。だから、振り返って、何によってこういう分析をしたのか、何かデータがあるのかどうか、そこが知りたいんです。","respondent":"青木指導課長","answer":"そうした社会的な背景の捉え方というのが客観的な内容になっているかというふうに考えております。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問","question":"データはないというふうに言っていいんでしょうか。カリキュラムだって変えてやるわけですから、全然別のものでしょう。というのは、小中一貫というのは、基本的にはその学校だけですから、学校選択というのは、どこでもいいからというので自由でしょう。だから、私は小中一貫の言われる、親たちの願いとか、教師の願いの、何か具体的なデータがあるんですかという質問をしたんです。","respondent":"青木指導課長","answer":"小中連携の一つの一体化型の一貫校ということで、その連携の中でのノウハウというのは当然生きてきますし、また逆に、一体化された一貫校での成果もそこに戻されます。そういう意味で、先ほどの連携については、そのように考えていただきたいと思います。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういう声があったら、次回に具体的に示していただきたいと思います。もしそういう声があるとしたら、日野中学校のＰＴＡ会長から要望書が出ておりますよね。前回も幾つか紹介されたんですけれども、ここに書いてある要望書というのは、まさに突然学校の小中が決められた。拘束されないでやるということは、これは文部科学省の研究開発校だからなんですか。そこだけちょっと確認しておきたいんです。","respondent":"青木指導課長","answer":"学習指導要領そのものに対して、今もすでに、委員もご存じのように、複数学年によって目標なども示されておりますので、学習指導要領自身が極めて弾力的になってきておりますけれども。","id":"exchange-009"},{"speaker":"桜井委員","kind":"確認","question":"ほかの学校でもこういう考え方でいいという理解でしょうか。品川区のほかの小・中学校でも弾力的にやっていくということでいいのかどうか。この地域というのは東五反田二丁目ですよね。どこまで説明するかどうかは別としても、全体像といったものがないという、その捉え方というのがよくわからないんですけれども、それはそれで説明されたならばいいですけれども、それだけ確認します。","respondent":"鷹倉庶務課長、青木指導課長","answer":"これが東五反田地区のところの核的な役割を担えばいいな、担いたいなと、こういうような話をしたところです。他校においては、基本的には一定程度の拘束性というのはありますけれども、それにしましても弾力的な取り組みというのは今後検討していくことになるというふうに思います。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先に確認的なところですけれども、小中一貫校が第二日野小学校と日野中学校で進めていきますが、今後の品川区内の展開としてどういうふうに考えていらっしゃるのかという点。それから、先ほど小中連携校７校と言いましたが、その実績的なもの、どのように取り組まれて、その制度の進み方はどうなっているかという点を教えてください。説明会の開催経緯の中で、参加者が少ないと思ったんです。","respondent":"鷹倉庶務課長、青木指導課長","answer":"説明会の開催の人数が少ない、あるいは時間の問題云々ということですが、これは当初、プレス発表された中身をお知らせするですので、役員の方にお知らせしたいという形でお話し申し上げました。今までの考え方からいけば、第二日野小学校と日野中学校の教員がどのような形で人事異動していくのかというようなことになるかと思いますけれども、これも一つの課題として今後検討してまいりたいと思います。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"一番最後のほうから確認させていただきたいんですけれども、当然東京都の人事権という問題だと思いますけれども、せっかく品川区でこれだけの認識を持ってやっていただく、その中でもうちょっと強く出せないのかなと感じるんです。もっと強くやってもらいたいなという希望を持っています。その中で支援をしていっていただきたい。それに対してどんなふうにお考えか、お答えをお願いします。","respondent":"青木指導課長、富田教育改革担当課長","answer":"１点目の教員の配置につきましては、強く希望されるということで、私たちもそれを受けて進めてまいりたいと思います。それぞれの方が自分に合った学校を選んでいくように、それぞれ選ばれる側として頑張っていけるような近隣の小・中学校となるように、特色づくりの部分でも教育委員会としては支援をしていきたいというふうに考えております。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これだけすばらしい体制をとっている学校だという意識があるところに、普遍性をどう考えるのかを、選びやすいと同時に、選ばない方も当然出てくると思うので、そこら辺をよく考えておいていただきたいなという意識もあります。それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"小中一貫校については、これだけ説明会を開いていただいているということが分かりました。説明材料もよくできているので、今後とも、話し合いをしていけば、理解者は出てくるのかなという気がいたします。でも、できた学校は小中一貫校ですからという中で、どのように地元に説明していけばいいのかというのはなかなか難しい問題なんだけれども、その辺をどう考えているのか。","respondent":"鷹倉庶務課長","answer":"それも説明をしながら、ご理解を得ていきたいなと考えています。なくなるわけではございません。こちらに移転するだけだという理解を懇切丁寧にしていきたなと考えています。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"第五日野小学校と一緒になったりした過程がありますからね。そういうのがまたなくなってしまうわけですね。幾ら日野中学校が移転したんだよと言っても、同窓会そのものは、今度は小中一貫校の第１回の卒業生が出て、そこから同窓会が始まっていくわけですから、今までの日野中学校の同窓会、第二日野小学校の同窓会そのものの居場所がなくなってしまいますよね。まちではそうなんです。","respondent":"指田教育次長","answer":"当然のことながら、移転ですから、従来培ってきた日野中学校なら日野中学校の伝統というものをドッキングさせながら新しいスタートを切っていきます。したがって、それが平成１８年４月１日から全く新しい学校になるなどということはゆめゆめ考えていません。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"理屈から言えばそうかもしれないですけれども、現実、第二日野小学校の周年行事かに出たときに、第五日野小学校の同窓会があるんですね。そういう人たちはどういうところを根拠に、どういうところを居場所にしているのかなと思ったものですから、そういうような中で、一つは語られる場というものを、今度小中一貫校につくる。ということなんです。","respondent":"指田教育次長","answer":"当然心の中で持つ部分もあるでしょうし、ハード的にもしそういうふうな部屋が必要であるならば、これはＰＴＡ室というのが大抵どこの学校でも設けますから、そういう中において、同窓会の方々がお集まりになる、あるいはふだんでも入ってこれるような。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"全体で何回の説明会をやったのかわからないですけれども、それぞれ関係する学校のＰＴＡの役員や地元町会の役員に説明会をしているようですけれども、全体を通じてどういうイメージを持つのか、先ほど来の話だと、これからもご理解いただく場で説明会をやっていくんだという方向だから、一人ずつにご理解をいただいているという中身でないんだろうというふうに思うんだけれども。","respondent":"鷹倉庶務課長","answer":"しかし、我々はお話し申し上げているとおり、検討をこういう形でしていくのが筋だと考えていますし、教育委員会、あるいは議会に報告する中で、我々にできるのは精いっぱい、今日報告申し上げているとおり、途中経過ですよというものを、こういう場でお話ししつつ。","id":"exchange-017"},{"speaker":"高星委員","kind":"質問・要望","question":"それは、ここに掲げられているお題目は大変立派なものだと思うけれども、これからそういう声が沸き上がってくるだろうというふうに思うので、その辺のところは十分にクリアしてもらうように、そのことだけは確認させてもらうというか、どういうふうにやっていくかということを、先ほど桜井委員の話にも出てきたんですけれども、もう一度そのところをきちっと話をお聞きしたい。","respondent":"指田教育次長","answer":"何回も繰り返しになるかもわかりませんけれども、２月９日から４月１６日までの説明会というのは、冒頭申し上げましたように、小中一貫校のプレス発表資料の域までしか出ていない中での説明でございましたので。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"今、高星委員に答弁していただいた、たとえばですけれども、有楽街を通って来るのは第三日野小学校の子どもだという、これは基本的に選択制の中では、第三日野小学校の子どもが、あそこに行きなさいというわけではないんですから、最初に第三日野小学校を選んでいただいて、中学校のときに中学校を選択していただければいいのであって、それは全く誤解ではないんですか。そういう点はどうなんですか。","respondent":"指田教育次長","answer":"ただ、高星委員から今お話のあった、有楽街を抱えているというふうなところで、地域の方々の中にもそういうふうに言っている方もいらっしゃいますから、したがって、そういうことのないような安全面に配慮した、例えば通学ルートについてはきちんと立てるとか。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問","question":"質問のところには、「文教施設を設置することで、これがまちづくりの核となっていってほしいと考えている」と書かれてありますけれども、まちづくりというのはこれから大きなところで検討をしていくと思うんですけれども、教育委員会としてはこういうふうなまちづくりにしていきたいんだという意向がとても大事だと思うんです。そこをどういう部分で出していかれるのかということ。二つお伺いします。","respondent":"鷹倉庶務課長、青木指導課長","answer":"やはり我々は、説明会に行ったときも、どちらかというと、ニュートラルな発言を心がけるようにしております。一貫校におけるカリキュラム開発とか、指導法の研究の中で、当然現状の小学校、中学校で生かされるものというのはあるかと思いますので、そういう意味で、まず一貫校で行うカリキュラム開発や。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問","question":"今の子どもたちのいろいろ問題点が書いてあるんですけれども、こういう問題ももちろんあると思うんですけれども、小学校へ入った段階から子どもたちの受験のストレスというか、競争の教育の中でのストレスをすごく感じて育っているなという意味では、子どもたちの意見を、これからの子どもたちもそうですけれども、特に高校受験を終わった後の子どもたちの意見なども。","respondent":"鷹倉庶務課長、青木指導課長","answer":"１点目の、学校づくりの進め方という形でのお話かと思います。教師のほうも子どもの声に耳を傾けていくという、そういう子どもと教師の関係というのは今以上に強いものにしていきたいし、９年間にわたっての子どもの理解ということになりますと。","id":"exchange-021"},{"speaker":"桜井委員","kind":"意見","question":"小中一貫校準備委員会で検討する課題の案の中に、「実現に向けて考えられる課題」とありますね。教育課程、施設計画、学校経営、その他とありますけれども、もう一度整理して言っていただけますか。","respondent":"富田教育改革担当課長","answer":"両部会のほうから上がってきた課題検討の結果等々もこの準備委員会で報告を受けながら、プラン２１の推進委員会のほうに上げていくというような構成で考えているところです。","id":"exchange-022"},{"speaker":"桜井委員","kind":"質問","question":"少しイメージが違っていたんですけれども、今のお話はかなり事務的なことですよね。私はむしろ準備委員会の、今日文教委員会にお出しいただいた、こういう資料は大変ありがたいと思うんです。小・中学校はどういう目的を持って、どういう学校をつくっていくのかという、理念の部分が多いと思うんですけれども、こういうところをもう少し論議をしていくことかなと思ったんですが、そうではないんですか。","respondent":"富田教育改革担当課長、藤田委員長、上川内生涯学習課長","answer":"先ほど申し上げましたのは、個別の検討課題ということでございまして、それぞれの課題検討の前提といたしまして。ほかにございませんでしたら、以上で、本件を終了いたします。続きまして、報告事項の２番、平成１４年度情報通信技術（ＩＴ）講習事業の実施について、ご説明をお願いします。予算につきましては、補正予算を計上する予定ですが、６月３日から実施する予定ですので。","id":"exchange-023"},{"speaker":"山路委員","kind":"質問・要望","question":"それに関連して品川区はどういうふうな支援をしていくのか、その辺も決まっていたら教えていただきたい。テキスト１,０００円というのがありますね。できたら、こういう時代ですから、地元の商店の活性化のために、そういうところを通じて地元の書店で買えるとか、そういう形のものを利用していただいたらと思うんですが、その２点をお聞きいたします。","respondent":"上川内生涯学習課長","answer":"障害者のパソコンにつきましては、生涯学習課のほうではなくて、障害者福祉課のほうでトータルで扱っておりますので、今年度は私どももまだ細かいこれ以上の計画は立てていないように、ほかのところも立てていないようで、詳細は分かりかねますが、昨年度と同様ということで。","id":"exchange-024"},{"speaker":"山路委員","kind":"質問","question":"直接でなく、関連性において何か情報があったらということを聞きたかっただけなんです。もう１点は、クラスを変えてやるという計画がありますね。この内容だと、基本操作ですね。それはどういう形でやるんでしょうか。","respondent":"上川内生涯学習課長","answer":"このほかに生涯学習課、ほかのところでもパソコンの講習会、教室等は今までどおり、また、平成１４年度新たに組まれていると思いますが、生涯学習課ではシルバー大学とか、パソコン教室、通常の講座の中で、ほかの講座と同じような形で入れてはあります。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の関連でお聞きしたかったんですけれども、レベルアップ講座を、前回の委員会で説明があったと思うんですが、これとはまた別個だということは分かりますけれども、そちらに対してはどのような形をとっているのか、もう一度お願いいたします。","respondent":"上川内生涯学習課長","answer":"基礎の部分だけではつまらないというお話もありましたので、通常の講座の中に、平成１４年度はレベルアップ講座を一講座入れておりまして、基礎講座で習った復習と、それから、もう少し上級の、レベルアップ分の学習もしていく講座を組んでおります。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ちょっと疑問だったのは、前回の請願のことに絡んできてしまうのですけれども、レベルアップ講座を一講座というのもちょっともったいないなと。今度の基礎講座の予算は分かりますけれども、区としてレベルアップぐらいまでは、あまり強調したところは言わないですけれども、一講座というのは少ないんじゃないかなという思いでお聞きしました。","respondent":"上川内生涯学習課長","answer":"一講座と言いましても、２０人で、２０回。４００人分の講座を、平成１３年度の基礎講座を引き継いで復習の講座として設けました。いつやるかという細かいことはまだです。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認ですけれども、２０人で２０回、４００人は受けられるということですか。","respondent":"上川内生涯学習課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"高星委員","kind":"意見","question":"３０回ということで、平成１３年度と同様の内容ということですが、随分金をかけてやるのかなと思ったら、「違うんですよ。規模は５００人ですよ」という話で、講習の内容が、成人（２０歳以上の都民）になっているけれども、その辺はどういう内容なのか。","respondent":"上川内生涯学習課長","answer":"すみません、分かりにくくて。二つのものが別にあるんです。今日の報告というのは、平成１３年度に国全体でやったＩＴ講習会の平成１３年度の延長事業なんです。","id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"意見","question":"振り返ると、教科書の採択の問題とか、ＩＴ講習会もありましたし、すまいるスクールもできまして、学校の安全管理の問題とか、小中一貫校とか、たくさんあって、あっという間の１年間であったなと思います。議会の役割の重要性と、議員の力量がすごく問われると痛感をした１年でありました。委員の皆様と、理事者の皆様のご協力に感謝いたしたいと思います。どうもありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/207072?Template=document&Id=4436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34724,"voices":86}},{"id":"h14-20020508-5","meetingId":"h14-cm05","date":"2002年5月8日","dateIso":"2002-05-08","committee":"総務委員会","time":"午後１時０５分～午後２時５２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","topics":[{"id":"topic-01","title":"の財団法人品川文化振興事業団の財産運用","agenda":"の財団法人品川文化振興事業団の財産運用","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"目的のところで、地方公共団体の公金管理については、安全性と効率を同時に求められてきたが、今後は安全性の確認を最優先し、効率性も求めるというような、そういうふうに書いてある。この表現は基本財産も運用財産も同じなんですけれども、品川区の公金管理のこの方針とちょっと考え方が違うんじゃないかと私は思うんですけれども、そこら辺の見解というか、どういうふうに変わるのか、まずお聞きしたい。","respondent":"中尾根企画部長","answer":"私がご説明しました区に準じたというところは、運用要綱の運用指針、第２条の中の金融機関等の情勢分析だとか社会経済状況をよく適確にとらえなさい、この規程のところはペイオフ解禁等の絡みもあり、ここの部分は公金に準じた扱いだと言ったことでございまして。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっとそれで質問なんですけれどもね。今回のやっぱり一番の反省点というのは、危ないものを買っちゃったということだと思うんですよね。そこで今までの、例えば前回の品川区の公金管理運用の方針、ここで言いますと、今までは安全性と効率を同時に求める。そういう規程だった。前提が安全確実という品川区の公金管理運用方針とはちょっと考え方が違うというふうに思うんですけれども、どうですか。","respondent":"中尾根企画部長","answer":"ここでそういう表現のもとに運用するということについては、今回少なくとも品川文化振興事業団についてはそういう運用方針はとらないということで、今回のように安全かつ運用益が得られるということ、ここは大きな変更点です。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと私が聞いたのは、品川区の公金管理運用方針の考え方と、この品川文化振興事業団の資産管理運用規程、ここのところの考え方というのはちょっと違うんじゃないですかということを聞いているんです。","respondent":"中尾根企画部長","answer":"それは何回もそのようにご説明しているつもりですので、よろしくお願いします。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"そのことで、同じことをちょっと言っているんですけれども、私が言っているのは、一番の反省点がここにどういうふうに生かされているかというところが、やっぱり問題だと思うんですね。その点では、前回も総務委員会で説明された、品川区のほうは、私はこれは当然だと思うんですよ。は安全だと。前提が確実ですという言葉にならないでしょうということを言っているわけです。","respondent":"濱野助役","answer":"「かつ」というのは、ＡかつＢというと、Ａであり、なおかつＢだということですね。ＡまたはＢというと、ＡかＢかということになってきます。図にしますと、Ａという丸とＢという丸が重なっている部分がＡかつＢです。したがって、安全かつ確実なんです。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"私がだから聞いたのは、品川区の公金管理運用と、この品川文化振興事業団の考え方が違うんですねと、ここはさっきから聞いているんだけれども、部長は法人があって人格が違うんだから違うんだと。私はそれは当然だと思うんですよ。私はそのことを言っているんじゃなくて、考え方が違うんじゃないですかと。","respondent":"濱野助役","answer":"委員のご質問は二つあるようですので、まず前半の、区の公金管理等の文章と、これと同一かどうかというお話ですけれども、同一ではございません。ただ、考え方というのは当然共通の部分もあるし、あるいは違う部分もある。全く同じであることはない。考え方は同じ。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"意見","question":"じゃあ、私は意見だけ言っておきます。これは、私が言ったのは、この表現が今までと同じなんです。国の指導との関係で。なんだけれども、これは規程ということになると、この文言で、表現でちょっと不十分だ。今後のところでちゃんと歯どめをかけておくには、ちゃんと文言のところもきちっと安全、確実がまず大前提という表現にしておく必要があるというふうに意見で言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"文言の話が出たので、文言の話でいくと、規程のほうの１ページの第５条の１の「ただし」というところから、「ただし、緊急な場合または、理事会を開催する暇がないとき」、こういう書き方って。〔「いとまと言う」と呼ぶ者あり〕いとま。だけど、決め事にこういう表現はあるんですか。","respondent":"中尾根企画部長","answer":"暇がないときに専決処分する、こういう表現です。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃあ、文言としては例えばどういうことですか。これは職務怠慢につながらないんですか。だって、重要なことを決めていこうというときに、それは何なんですか。専従じゃないからこういうことが起きるということなんですか。例えば品川区の企画部というところでこういう表現は使われますか。","respondent":"中尾根企画部長","answer":"私どもは、議会の関係の中で専決処分を、こういう似たようなことがありますけれども、議会は議会として開くだけの余裕ないしは何日前に通知してどうということはありますから、そういうことの暇がないときには専決処分をするというようなことでやってありますので、ただ。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"まさに今の話は、助役のインタビューで、理事会って年２回しか開けないんですよとしゃべったことがあるでしょう。始めから理事会はもう年２回しかやらないよという考えでこういう文言をうたっていると、僕はこれをそうとった。こういうふうに抜け道をつくっておくと、理事会は年２回でいい。だから僕は理事会の機能をもう少し持たすほうがいいような気がするんだけど、そうじゃないですか。","respondent":"濱野助役","answer":"したがって、寄附行為そのものを変えることはできないんでしょうかということを東京都の間でしました。しかし、東京都としては寄附行為を変えることはまかりならんと、やっぱり理事会で決めるということにすべきだ。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"質問","question":"とすると、やっぱり機能的に起きないようにしておくべきだと思う。個々の人は能力があり、そういう人が役につかれているというのは十分わかっているんだけれども、１人の判断でどうしても突っ走っちゃうときって、これに限らずいろんなところであるんじゃないですか。その辺はやっぱりきちんと今回のミスを繰り返さないような体制というか、運営をやっていくべきだと思いますので、よろしくお願いします。","respondent":"濱野助役","answer":"今、林委員が言われたことを規制しようということで、こういう規程をつくりましたので、そのご意見については十分に体して運用していくということをやってまいります。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"ということで前回の事件が起きたと思うんですね。それはすべて我々が組織文化みたいなものを否定していくんではないと思いますけれども、せっかく高い授業料を払ったんですから、そこを直すということについて、その一環として、まず手近なところから、運用規程みたいなのをつくる、これは結構なことだと思うんですけれども。向こうさんの言うものが見えてくるのかどうかちょっと教えてほしいんですけれども。","respondent":"濱野助役","answer":"たまたま今回保有しているものが比較的長期のものですから、今のところ、その満期が来るまで理事会を開く予定はありません。ただ、この債券に何かの異変があれば、当然それをつけかえる必要が出てくれば、理事会を開いて対応していく必要があるということです。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"特に金融財産の管理については、事故に遭うのは当たり前という時代に入ってきたわけですから、そういうことを踏まえて、委員会をしっかり意思決定ができる背景ができるような組織にしていっていただきたいと、これは要望を伝えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"三上委員","kind":"質問・要望","question":"お願いしておきたいと思うんですけれども。それからもう一つは、基本財産と運用財産について、先ほど一応４億円と１億円とかという、そういうふうなおっしゃり方をしましたけれども、特別、基本財産というのはこのすべての財産の中の何割とか、そういう決め方というのはあるんでしょうか。とってもらうことはできないということになりがちになってしまう。","respondent":"濱野助役","answer":"そういう意味では、まず役所の充て職と言って、出ない理事を減らしたということがあります。今後またそれぞれの理事の任期満了の機会には、承ったような意見を踏まえて対応していきたいと考えています。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"そこらあたりを、動かせないならないなりの、理事だけ、それから一部の人だけが知っているということではなくて、この部分についてはきちっと、こういうことは盾になっていますという、これは外部の方が知ろうとしても十分知れるような形の表現というものを使って、ある意味では公表していっていただきたい、こうお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと一つだけ確認させてくれますか。さっきの５条のところなんだけれども、真ん中あたりに、理事長は、理事会で別に定めた「資産管理運用要綱」に基づき資産運用することができる。この一言だけ読むと、すべて理事長の判断が要るというふうにとれるんだけれども、そう理解していいですか。","respondent":"中尾根企画部長","answer":"それ以外の財産ないしはそういう運用の部分については、これは処務規程の中の権限の中で実際上は分割する。ただ、最後の責任はやっぱり理事長であるのは、もうこれは間違いのないことです。そういうことです。","id":"exchange-015"},{"speaker":"中島委員","kind":"質問","question":"直近というのは、先ほど年に２回ではないと言いながらも、ちょっと期間があってもそれは直近の理事会だというふうにとられてしまう。ですから、やっぱり理事長の考え、考えというか、緊急性があって資産運用をしたときには、ただちに理事会を開催するという義務づけを私はここに入れておいたほうがいいんじゃないかなと思うんですけれども。","respondent":"中尾根企画部長","answer":"したがいまして運用の中でいくということで、先ほど副理事長が言いましたように、定款上は２回ということになっていますが、臨時で必要のあるときは積極的に、そのように持っていきたいという意向を示されたんですので、そのようにご理解いただきたいと思います。","id":"exchange-016"},{"speaker":"北野委員","kind":"質問","question":"ちょっと細かいことでお伺いしたいんですが、運用指針の部分で、理事長や理事の皆さんは専従じゃないですよね。それで、こういうことの情報把握とか、帳簿とか、常に管理するという方は、常駐として品川文化振興事業団の中でいらっしゃるのですか。","respondent":"中尾根企画部長","answer":"こういう関係で、区と財団との中では補助金を出している関係、ないしは基本財産を出している区でありますから、そういう関係で持っていきたい、そういう具体的な運用を考えているです。","id":"exchange-017"},{"speaker":"北野委員","kind":"質問","question":"そういうところをちょっとお伺いしたいんです。","respondent":"濱野助役","answer":"ただ、そういうような運用をするようなことになれば、やはり毎月なり何なりお送りする必要があるかと思いますが、現行の基本財産の中身を考えますと、何年か先まで変更する予定はありませんので。","id":"exchange-018"},{"speaker":"北野委員","kind":"質問・要望","question":"理事長の責任上というのがあって、いろいろ理事長には報告されるけれども、やはりほかの理事の方にどこまでの情報公開がされるのかなというのが一つあると思うんですね。やはりそういう中で、ある程度のそういう形にされて、決定へ持っていくということがすごく必要だと思うので、そういうところでは、やはり新たにつくった運用規程をしっかり有意義な形で実践していただきたいなと思います。","respondent":"中尾根企画部長","answer":"今回、それに新たに先ほど言いました債券に関する帳簿を載せたということ、これらについて、必ず備えつけしなくちゃいけないという規定と、要するに、ですから理事等がそのことについて見たいということがあれば、いつでも提供するという。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"確認","question":"一番直近が４月２３日の部長会ということで、(3)の都市計画決定の手続は、江東区が行うことで再確認というふうに書かれているんだけれども、やるということですか。それとも確認をしたということなんですか。","respondent":"小野（孝）政策担当課長、中尾根企画部長","answer":"江東区が都市計画決定の手続を進めるということについては、１月１７日の区長会の中で確認をされております。前提が崩れたら話し合いができないじゃないかということになる。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"帰属は５区だけと言っていいのか、いいでしょうね。５区で、うちだ、うちだとやっている。１７年度末の。都市計画決定が。ということから、非常に時間がないんですよね。帰属はまだ埋め立てが始まっていない部分も含めて帰属の問題をやっているんだから、その帰属はちょっと時間がかかっても別だけれども、施設建設については、非常に逼迫した時期に来ているというのを認識しておいていただきたい。","respondent":"中尾根企画部長","answer":"ただ、認識は、委員の指摘しているとおり私どももそういう危機意識を持って、これを、帰属の問題のおとりだとか、そういうことに使ってはならないはずだ、そういうふうには主張しております。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"このまま行くと、品川区に何のメリットも、領土が来るという可能性は薄いわけですから、品川区の利害を中心に考えると、ペンディングにしておいて、何らかの２４区目ができてもいいわけですし、あるいは再配分の中で違ったところになってもいいわけですけれども、そういうもっとフレキシブルな考え方もとれるのかどうかということを聞きたいんですが。","respondent":"中尾根企画部長","answer":"今委員がおっしゃったようなことは、実は品川区としてどう主張するかという点のときの検討の材料でもありましたし、検討もしてはきております。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"例えば建物をつくって、これは必ず灰溶融炉の方に属していなきゃいけないという縛りがほんとうにきついのかどうかというようなことだって考えられるわけですから、そういう意味から言うと、１００年というのを都市問題を考えていけば、ここが江東区だ、大田区だ、品川区だとやるよりも、そういうふうに悪い言葉で言えば先送り、だけれども、ある余裕を持たせておく判断。","respondent":"中尾根企画部長","answer":"大所高所からのそういうことについては私もいろいろ検討もしておりますし、例えば東京都の直轄地にそのまましておいて、そして何の不自然があって、ないしは都市計画決定がそれではまずいのかということのそういう法的な検証も十分してはおりますが、そういう背景がありますので。","id":"exchange-023"},{"speaker":"三上委員","kind":"質問・要望","question":"一つだけちょっと発言をさせていただきたいので。臨海トンネルの開通式のときに出席させていただいて、そのときに感じたのは、やっぱり議会も含めて、職員の皆さん、江東区と大田区が大挙して出席していたんですよね。議長と私もあれっと思ったのは、そういった情報をいち早く自分たちの領土戦争にもう取り組んでいるという実態が感じられたんです。ちょっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"意見","question":"モニターの方々の品川区に住んでいる年数とか、そういう情報等はつかんでいらっしゃいますか。今回来た人はこれからいろいろ仕事をしていく上でわかるんだけれども、例えば昨年度のモニターの人たちが品川区にどのくらい住んでいるだとか、そういうような在籍というのかな、そういうものはわかりますか。","respondent":"山田広報広聴課長","answer":"実を言いますと、そちらの年数について入れてあるんですけれども、今回の資料の中ではお出しできておりませんけれども、応募していただく段階で在住何年というところを記入をしていただく欄がありますので、把握はしています。","id":"exchange-025"},{"speaker":"林（宏）委員","kind":"意見","question":"ちなみに平均で何年ぐらいで、古い人は何十年という人はいる、例えば比較的新しい人だと１年とか２年とかいう人がいらっしゃるのかどうか、その辺、簡単でいいですけれども。","respondent":"山田広報広聴課長","answer":"特に男性の方が転勤をしていて、やはり品川に戻ってきて、退職をして、やっぱり品川区をもう１回見つめ直したい、それで自分がやれることが何があるのか参加してみたいということで応募される方ですから、平均すると大体４０年近い年数が出てくるというふうに考えております。","id":"exchange-026"},{"speaker":"林（宏）委員","kind":"意見","question":"区でいろいろな方々、区民の人たちへのサービスというのを、今日もシルバー大学がありましたけれども、そういうような区がイニシアチブというか、リードをしながら住んでいる人たちへのサービスをいろいろ考えていく。品川区のそういうサービスというか、そういう人たちとモニターの人たちとのつながりというのはどういうところに、何かありますか。","respondent":"山田広報広聴課長","answer":"託児については私ども託児制度を持っておりますので、若いお母さまはご参加くださいということで、いつも託児をやっているんですけれども、そういう方々が初めて区政にかかわってくるというような感じの、ある意味では二極分化しているのかなです。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問","question":"そういう人たちを原則として１年でかわっていかれるということだから、そういう人たちに、言葉はいけないけれども、お役人の天下りだとか、そういうところにはたくさん力を入れるんだけれども、こういう人たちに街の中に、ばらまくという言葉はいけないけれども、散らばってもらって、いろんなかかわってもらうということは考えないんですか。","respondent":"山田広報広聴課長","answer":"あくまでも区の制度というこの制度の中にのっとってモニター活動をなさるというところで参加をしていただいております。ただ、現実的には１年やってみて、自分たちなりにもう少し違った形でできないか、それを継続してできないかというのが昨年の離任式のときにお話がありました。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"最後にします。おっしゃるとおり、最後に言われたとおりなんです。特にモニターに手を挙げる人なんかは、そういうものに関心を持っている人たちですから、ぜひそういうところのきっかけづくりも、お忙しいでしょうけれども、広報広聴のこういう仕事を通してやっていただければ。関心の高い人だから、ぜひそういうことで、街の中に出てきてほしいなというふうに思うので、ひとつよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"北野委員","kind":"質問","question":"モニターのＥメールのほうなんですけれども、こちらはなかなか区のところに参加できないからということもあってＥメールモニターをというのがあるんですけれども、お願いするものというのは、Ｅメールの方もモニターの方も同じようなことをお願いするんでしょうか。ちょっとそこのところを。まだ、ホームページについて聞いてもらいたいんですけれども。","respondent":"山田広報広聴課長","answer":"例えば品川の教育改革ということで、集会モニターの場合であれば、指導課長が品川の教育プランというのはこういうものですよ、こういうふうに進めておりますよというので、あとはご意見をいただくというような形をとるわけですね。","id":"exchange-030"},{"speaker":"北野委員","kind":"質問・要望","question":"それと、昨年された区政モニターのご意見で、出産一時保育の予約が１カ月前から３カ月前になったとか、区民公園を、月曜日がお休みだったのが無休に近い状況になった、これは区政のモニターの方の意見の反映ということなんですが、一般の私たち利用したい側の区民に対しては、区政モニターの結果としてではなく。","respondent":"山田広報広聴課長、本多委員長、西島経理課長","answer":"事業部ホームページの中で、例えば公園の利用の仕方でありますとか、先ほどの制度の問題、これは出産一時保育という制度ですから。本件を終了いたします。入札予定価格の事前公表につきましては、平成１０年１２月から３,０００万円以上の建設工事について実施をしてまいったところです。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"確認","question":"ちょっと確認だけ。試行がされていて、高どまりではなかったよということなんだけれども、ちなみに、パーセントを教えてください。","respondent":"西島経理課長","answer":"正直なところ、もう少し下げていただければと、所管課としては思ってありますが、先ほどのよそで言うような高どまり傾向というのは見られなかったというふうには考えております。","id":"exchange-032"},{"speaker":"林（宏）委員","kind":"意見","question":"９５％、９６％が、両方が平均すると９６％ぐらい。やっぱり９４％、できれば９２％、９３％ぐらいのパーセンテージに行ってほしいなというのが、発注側とすれば、そのぐらいの競争が行われるのが適正じゃないのかなと、予定の価格に対してなんだから。９５％をオーバーしている。１,０００万円まで下げてどういう数字がまた出てくるかというのもありますので、そのときにまた聞かせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"塚本委員","kind":"意見","question":"各区が事前公表をどの程度導入しているのかということと、今のパーセンテージ、他区がもっと低くなっているよという、制度がみんな同じかどうかわかりませんので難しいところですけれども、そういう声が聞こえてくるんですが、その辺のところは。","respondent":"西島経理課長","answer":"他区の状況ですけれども、品川区が一番先に事前公表を開始いたしまして、始めたときは他区は事後公表でしたので、それが現在見ますと１１区が事前公表に移ってきております。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/891081?Template=document&Id=1578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":34558,"voices":82}},{"id":"h14-20020515-13","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"清掃・リサイクル特別委員会","time":"午後１時０９分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"このリサイクル率というのが仮の定義という説明で、これはどのあたりまで使われているのか、品川区だけの考え方か、一般に他の自治体でもこういう数値でカウントすることができるのかどうか。","respondent":"中山清掃リサイクル課長","answer":"例えば管路収集というのも、これは実は臨海副都心の事業系ごみを有明港へ管で経由しておるんですが、事業者としては別のリサイクルをやっていたり、要は事業系のリサイクルの把握ができないものですから、今回区で収集しているものということを中心に。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"それで、私はやはり拠点回収だとか、集団回収だとか、店頭回収も含めて、また私たちが自分の住んでいる住まいのそばで可燃ごみ、不燃ごみでいろいろ努力して意識啓発の効果もあって、随分出す側の意識も深まってきている、一定程度の影響や頑張りが見られるのではないかというふうに思っているんですが、そういう点で微増ではあっても増えているここのところをどうとらえたらいいのかなという。","respondent":"中山清掃リサイクル課長","answer":"廃棄物という大きな定義で言えば微増だということで、従来リサイクルは望ましいことですから、できるだけリサイクルに出してくださいという周知をし、このリサイクル量が増えること自体が望ましいというふうな、区としてもそういう認識を持っておったところですが。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"今回はできなかったわけですから、そこまでちょっと手を広げるということがなかなかできなかったので、その辺の当委員会の役割として位置づけていきたいなというふうに思っておりますので、もう少し早い時期に発言し、運動的に行動できればよかったんですけれども、この時期に来ておりますけれども、ちょっとそのことを思っておりますので。","respondent":"中山清掃リサイクル課長","answer":"それで、こういう発生抑制になりますと、区民だけではなく、事業者、それぞれいろいろなところでの役割ということもあろうかと思うんですが、これも区でできるチャンネルの中では、働きかけというのは常にいろんな場面の中で、２３区で一体であったり。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"さっきちょっと当初に言っておけばよかったんですけれども、ここは区で収集している量の数字の推移だけを示していただきましたが、事業系のごみというのはどの程度かというのは、もしわかっている範囲で推移がわかれば、これと比較して、私がちょっと質問したかったところもはっきり受け取れないのかなと思うので、もしわかったら教えてください。","respondent":"中山清掃リサイクル課長","answer":"実は、いわゆる事業系ごみの把握というものが、ちょっと区に清掃事業が移管されておりながら、区内のほんとうの事業系のごみはどうなっているかが明確に把握できないというのが一つの区の清掃事業の課題だという認識は持っております。","id":"exchange-004"},{"speaker":"北野委員","kind":"質問","question":"この不燃ごみなんですけれども、最終的には不燃ごみを京浜島のところで、今のお話の中だと一部分けられるものは分けているということですけれども、大体どういうものが主に分けられるのかというのと、これは全体だから、２３区全体の量的な割合になってしまうと思うんですけれども、不燃ごみの中から資源ですとかそれぞれの量というんですか、大体２３区全体で。そういう割合というのは出ているんですか。","respondent":"中山清掃リサイクル課長","answer":"アルミについては結構単価が上がっている。そのほか、瓶も機械的に色によって選別できるようになっていますから、これもリサイクルに回るようにやっております。ちょっと量は申しわけございません、別途お示ししたいと思います。","id":"exchange-005"},{"speaker":"北野委員","kind":"質問","question":"やっぱり燃えないごみは、トレーもあれば、ペットボトルも入ってしまう。私たちがどういう形でリサイクルをしてきたら、ほんとうに身近なところから。だから、資源回収が増えて、店頭回収が増えて、その分総体的には税金もかかっていく。もう一つの四つもあるんですよということをどこかで知らせていくべきじゃないかなと思うんですけれども、そういう考えはいかがですか。","respondent":"中山清掃リサイクル課長","answer":"むしろリデュース、発生抑制の中に、もともとごみになるものを断るということも概念としてあるんではないかということなんですが、具体的にどうやればいいのかということをお示しするという中に。","id":"exchange-006"},{"speaker":"北野委員","kind":"意見","question":"いつも四つ目のＲということで、この中で発言させていただいていますけれども、ほんとうにそれが行政もそうですし、私たち自身も考えていかなくちゃいけないことだというのは重々わかっていますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここにはリサイクル率ということで書いているんですけれども、例えば資源回収されるペットボトルだとかいろいろありますけれども、その中で、そういう資源回収のものが実際にどれくらい回収されているかという回収率みたいなものは区としては出せるんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"ただ、もちろんこれは１％でも上げ、ごみにしないのが原則だという認識は持っております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、品川区もこれからさらにごみを減らしていくということから考えると、私なんかもいつもごみを捨てるときに、いろんな容器包装リサイクル、そこら辺のところがもうちょっと徹底されたら、ごみはかなり減るんじゃないかなというふうなものを常々感じているんですけれども、名古屋なんかでは、そのプラスチックにしても、それから、紙製にしても。","respondent":"中山清掃リサイクル課長","answer":"品目については、そういった意味で検討は、今後どういうことができるかということは考えてまいります。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それとあと、前に、この間の予算特別委員会のときに飯沼委員のほうから、１人当たりのごみの量ということで、１日１人当たり８００グラムということでご答弁いただいていますけれども、この８００グラムの中なんですけれども、これは事業系とか、それから家庭内のごみとか全部合わせてということなのか、そこら辺のちょっと内訳について、どういう状況なのかをお聞かせいただきたいんですけれども。","respondent":"中山清掃リサイクル課長","answer":"１人当たりの廃棄物の量が約８００グラムというのは、区で収集しているものからしか把握ができませんものですから、基本的には家庭系のものだというふうにお考えいただいて結構です。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、家庭と小規模の事業者の合計を人口で割ったというようなことでとらえていいかと思うんですね。そうすると、それが８００グラムということで、あとは事業系としてはどれぐらいかというのは数字として出ているんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"事業系のごみの１人当たりどうかという計算すること自体がどれだけの意味があるかということはありますが、そういう統計はとってございませんが、さっき申し上げた２３区で清掃工場に持ち込まれているような、そういった一般廃棄物で言いますと。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"先ほどのご説明の中であったのかもしれませんが、参考までに。２番目の資源の回収量の中の拠点の回収等については年々回収量が減っていますが、これはその分店頭回収とか集団回収が増えてきたので拠点の回収が減ってきた、こういう理解ですか。あるいは拠点の回収の場所、形が減ってきたのか。この辺の関連を参考までに教えていただければと思います。","respondent":"中山清掃リサイクル課長","answer":"これもちょっと拠点回収等の等のところに幾つかあるということが説明が抜けておるんですが、一番典型的なものは、空き瓶ポストというものを従来設置しておりまして、大規模集合住宅、あるいは八潮地区等に設置しておったんですが。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"原価がどのくらいかかるかというところは関心のあるところでありますが、ここの時期に至ったというのを、ちょっとその背景というのかしら、担当課長会のところでそういう方向で計算しようよという共通の認識があって、こういう資料が提示されてきたのか、今何かその辺のところがちょっと私は十分理解、受けとめ切れなかったので、資料として提供してくださった、その背景を品川区段階の問題だけでなくて。","respondent":"中山清掃リサイクル課長","answer":"これは２３区の中で、区になったら全体像がわからないということではいけないんじゃないかということで始めようということを方針を決めた上で、そもそも今回の実績というか、実施自体がコストも含めて各区の執行になりますから、どこまでが清掃の経費であるのか、人件費も含めて。","id":"exchange-013"},{"speaker":"土井委員","kind":"質問・要望","question":"それから資源ごみにしても集め方が違うわけですね。集め方というか、やり方が。それも個別の車を使って別なルートで集めるというようなやり方ですから、コストが当然かかっているだろうと思えますね。そういうものが基準、当然それらも含めてこれは２３区ですから平均値という形で出てきたんだと、平均というか、トータルの形で出てきたんだろうな、こういうふうに理解しました。","respondent":"中山清掃リサイクル課長、松本環境清掃事業部長","answer":"そういった意味で、年度によって経常的なものというだけではなくて、例えばダイオキシン対策によっていろいろな排ガスに伴う工事を行う、こういったものを平成１２年度の中で行ったものは平成１２年度の中に入ってきておるですので。投資的経費のうち、減価償却と利子、これについては別途算定の形で入っています。土地については、これは控除をしています。","id":"exchange-014"},{"speaker":"土井委員","kind":"意見","question":"そこの算出によっては、一喜一憂していても何の意味もない中身にもなりかねない場合もあるわけで、要するに、先に工場を建てるということは、これから使っていくのに建てるわけですね。そうすると、その年にだけどかーんと経費が乗っかっちゃうというスタイルになるわけでして、今の状態がそうなっているということで理解してよろしいんですね。","respondent":"松本環境清掃事業部長","answer":"別途算入するというのは、年割に減価償却がきちんと計算をし直して、その年に算入をさせていただこうと。ですから、そのときにかかったものをそっくりそのまま計上しているのではなくて、いわゆる民間と同じような減価償却の計算方法を用いて、実際のコストを策定をしているです。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"そういうのがどれが適切なのか、どれがコストが安くて一番いいのか、コストの面ではこれがいいけれども、実態の面ではこちらがいいよとか、そういうメリット、デメリットも含めた啓蒙等も、このコストという面だけからでもやっぱり必要になってくるんじゃないかな、こんなふうに思うのですが、ここの中からそれは読み取れませんし、またそう簡単にデータが出るものではないと思いますので。","respondent":"中山清掃リサイクル課長","answer":"清掃工場等の件については、例えば新しい工場の建設等がまた平成１３年度等出てきますと、こういった部分も出てくるということで、どうしてもトータルの中でのコストにそういったものが反映されてくるという要素があるかと思いますので、品川区としては、今収集。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問","question":"単純なあれで。処理経費、ごみが少なくなってきているんだけれども、トータルとすると少し上がっていますよということはどういうことなんですか。","respondent":"中山清掃リサイクル課長","answer":"表をご覧いただきますと、処理量が平成１２年度に比べますと、収集運搬量で言いますと１８万２,０００トンと減っていますということですが、それに見合って、処理経費もそれぞれ収集運搬部門で、この表ですけれども３４億余、それから処理処分が５７億余、合計９１億。","id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"その辺なんですよね。結局処理量よりも経費が上回っているよということはどういうことなのか。経費がそんなにかかっている。これはもう落とし切れないことなのかどうなのかということです。その辺にまだ工夫のあれがあるのかないのかという。こっちは落っこってきて、それでごみ量の減ったぐあいに対して落ちてこないということは、何なんだろうと言っている。","respondent":"中山清掃リサイクル課長","answer":"とりわけ、これは、ちょっとこの表が冒頭申し上げたように中継輸送費の８５億というものは、平成１１年度と１２年度で扱いが変わっているものですから、収集運搬のほうがあまり減っていないように見えるんですが、実際には収集運搬の減が主というか。","id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"今言ったようなことになってきた、結果的にはこれだけ見ていてどうのこうのという話ではなくなっちゃうし、そうすると、もっと品川区自体で、うちの自治体としてはこういう数字になってくるよというと、そんなに大きな変動はないわけですよね。これはあくまでも２３区の平均だけを見て、一つの参考だよというふうに見ておくだけだね。そう理解していいね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"北野委員","kind":"提案","question":"これは個人的な資料、委員会に出せる資料でもあり、また区民に出される資料の中の１点としてもそういう比較ができることがいいのではないのかなということは提案なんですけれども、何か品川区としてはどうなんでしょうか。見れば、リサイクルよというのはわかるんですけれども、単価については、やっぱり出すべきじゃないかなと思うんですけれども。","respondent":"中山清掃リサイクル課長","answer":"これは総量でやればリサイクル品目のということで総額でも出せるんですけれども、そういう形で、これはほんとうに２３区でいろいろやり方が違っているものですから、各区の中で。","id":"exchange-020"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"さっきの須藤委員のほうの話の続きになってしまうんですが、この資料をつくったのは、清掃一部事務組合のどこでつくっている資料の一部なんですか。","respondent":"松本環境清掃事業部長","answer":"清掃協議会のほうで作成をしたものです。","id":"exchange-021"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"収集運搬量が。その逆の意味で、収集運搬事業が変わっているはずなのに、これが上がっているのでは何かおかしな資料になってしまう。ですから、これは資料として出すのだったら、これを処理部門の変更する前の数字を出しておいて、収集運搬したことにこれだけコストが下がったというのを出すのが区としての考え方じゃないかなと思うんですけれども、どうでしょうか。","respondent":"中山清掃リサイクル課長","answer":"これは先ほど申し上げたように、各区に中継部門が移管されたために、東京都時代と違う考え方にしたというのを注釈に書いておるんですが、確かに表としては平成１１年、１２年を、たまたまこの年度をこういうふうに比較すると誤解を招きやすいということで、補正計算してみますと。","id":"exchange-022"},{"speaker":"土井委員","kind":"質問・要望","question":"経済性の問題なのか、何性の問題なのかということだと思います。だから、そこら辺の選択肢がどうやって決められたのかというところが、やっぱり我々のこれからのごみの分別を含めた、要するにサーマルリサイクルをどこまで考えるかということのほうにつながるわけですけれども、その辺の発想が、だれがどんな形でいつやってこう決まったのというところを少しとりあえず聞かせていただきたい。","respondent":"中山清掃リサイクル課長、松本環境清掃事業部長","answer":"その中で炉を新しくし、自動化も図っていくという中で、現在の大井清掃工場もストーカ式ですので、そういった中で、ストーカ炉自体がある程度非常に安定的な燃焼が可能なものであるということを踏まえ、またプラント更新。プラスチックですけれども、基本的に、現在の性能基準から言えば、混焼については何ら支障はございません。","id":"exchange-023"},{"speaker":"土井委員","kind":"質問","question":"新しくプラントが更新をされるということですから、当然公害対策上の問題というものも出てくるでしょうけれども、今お話があったように、ごみの分別の仕方等々も含めて、逆の意味で、これがほんとうに生ごみばっかりになったときにはどうするんだということもあり得るわけですね。以上、とりあえず意見も含めて申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"１点だけ伺います。簡単な点なんですけれども、当初の計画で、この改修は３４０億ぐらい見込んでいたと思うんですけれども、これは今の状況、時点で金額的な変更はどのくらいですか。","respondent":"中山清掃リサイクル課長","answer":"実施計画の中では、一切コスト的なものは、この資料にありますように示されておりません。","id":"exchange-025"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"別はわかったんですけれども、契約自体は品川区ではないということにはなっているんですけれども、金額的なものとか、この実施計画、何かこれから品川区として物申すことができるのかどうか、その辺の状況はどうなんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"今いろいろと地域処理の検討等しておるわけですが、そのいずれ品川区の施設になるという際に、財産も引き継ぎ、負債も引き継ぐということが十分あり得るわけですから、そういった意味では、こういう建設時から極力コストを下げて合理的にやっていくというのは。","id":"exchange-026"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"重ねて申しわけないんですが、やっぱり品川区として、これはもう区の施設になっていくわけですから、いいものをつくってもらって負担を軽くするという考え方もあるかもしれないですけれども、ある意味品川区としてきちんとしたものを残していくといういただき方にもよろしくお願いしたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"環境保全のところなんですけれども、１項目から８項目ありますけれども、単純に土壌汚染のことが何でここにないのかなと率直に思っているので、その点についてと、あと最後の環境影響調査等のところに環境調査を行うと書いてありますけれども、この調査の時点とか拠点とか、その辺について教えてください。","respondent":"中山清掃リサイクル課長","answer":"今回の実施計画というのは、基本的にはせんだって当委員会等にもご説明した環境影響評価書案にかかる事項に伴う説明とは別ですので、従来環境影響評価においていろんな手順を踏んでご説明あるいはお示しした部分については、当然それに従ってやっていくということになります。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"環境調査を行う、このあたりの、いつなのか、どこの拠点で行うのかというのは決まっているんでしょうか。一番最後のところです。","respondent":"金井環境課長","answer":"前にご説明があったと思いますけれども、環境影響調査表というのが出ております。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"以前それもあったんですけれども、具体的に区内で拠点は何カ所ぐらいあるんでしょうか。特にダイオキシンの心配が強いんですが。","respondent":"金井環境課長、松本環境清掃事業部長","answer":"これは工場の影響範囲ということで、たしか数カ所やっていると思いますし、１.５キロぐらい離れた、西側のところで１.５キロぐらい離れたところで、それは随時公開しておりますからあれですけれども。それは、工場は一般的に基準を設けて、私は今ちょっと何点をやっているのかは記憶にないんですけれども、基準点を設けて年１回必ず調査を継続的にやっていますので、その辺の変化はとらえております。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"後でゆっくりそれは読むんですが、１.５キロメートルぐらいのところで１カ所、ほかには区内はないわけですか。具体的にどことどこで調査しているのかなというのがわかるとすごくありがたいなと思ったのと、あとこの実施計画に基づいて、新たに区内とか特に清掃工場の近くの八潮地域とかでこれに基づいて説明会が行われるのかどうか。その点を教えてください。","respondent":"中山清掃リサイクル課長","answer":"この更新事業の実施計画に基づいての地元説明等はございません。基本的な環境影響評価であるとか工事説明というのは別途行います。それは工事説明があるです。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"炉ごとに調査がされる。すみません、区内の土壌調査の場所を知りたいんですけれども。後でもいいので、どこの場所でどう行われているのか教えてください。","respondent":"金井環境課長","answer":"環境課でやっているのは、例えば水質の調査ですとか、そういったことをやっておりますけれども、土壌というのは民間の敷地とかいろいろありますけれども、特別に公共の施設を、直接やるとすれば公共の施設になりますけれども、定期的にそういうことはやっておりません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"やることはいいんだけれども、その後の先が進んでいかないために、どうしても途中でとんざしてしまう状況はありがちだと思うんですけれども、だから、そういう点で、例えばどこか処理した堆肥として利用できる、そういうものについて流れをつくっていくということは考えられないのですか。考えていないのかどうか。そこをちょっと伺いたいんです。","respondent":"中山清掃リサイクル課長","answer":"それで、やはりこれはごみを減らすという意味では一つそれだけでも意味はあるのかなと思うんですが、そこから先、その利用されるか否かについては、当面それぞれのご努力にゆだねたいと思っておるんですが、何年かやる中で。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱりやっている人は、それなりの意識が高い方たちが多いと思うので、そういう点で、何だとまっちゃっているのかみたいなことだったら、何となくこうちょっと残念に思いますので、生ごみ処理の、この間モデルでやった、そういうあれをきちんとリサイクルのルートに乗せていくことを私も求めたいと思っているのと同時に、せっかくやっている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"電動式生ごみ処理機というようのが、半分の助成で上限２万円という、この辺の助成金額の基準というんですか、あと８０台、前回人気があったということで増えていますけれども、この辺の台数をはじき出す根拠というか、その辺と、あと裏面に行くと、コンポスト化の容器のほうの助成金額なんかも妥当なのかなといろいろ思うんですけれども、とにかくごみにしないで、ごみにならないで万歳と。","respondent":"中山清掃リサイクル課長","answer":"今年度はこのままの状況で、３年やった上で、いろいろとその後の対応について考えていきたいと思います。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私もぜひ生ごみのごみを出さない方法を、自分でも何か参加したいなと日ごろ思って、なかなか困難が多くてできないので、なるべくやりやすい方法でとは思っているんですけれども、とにかく参加者が増えるということと意識が高まる方向性を求めて考えていってほしいなと思います。そういった面では助成金額をもうちょっと上げても、すごい件数が今少ないですよね。利用されている方が。","respondent":"中山清掃リサイクル課長","answer":"利用者への意見ということにつきましては、今回も助成対象になった方については、その後、利用者の方にアンケート等をとることは考えておりますので、その中で先ほどの出口処理のことも含めたご意見等は聞いてまいりたいと考えています。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひアンケートなどで広く意見を求めていってほしいなと思いますけれども、コンポストのほうというのは、場所も問題だけれども、やり方が結構正しくやらないとなかなか難しいというのがあるので、やっぱりその辺、普及のためのご努力も必要かなと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"中島委員","kind":"質問・要望","question":"今は電動的はあくまでもごみを減らすという、生ごみを出さないからカラスにもやられませんので、そういった面では非常に便利で今家族も少なくなったせいか、ほんとうに毎日かけなくても十分快適な生活を送らせていただいているわけですけれども、やっぱり環境に優しいとか、そういった点では、コンポストをもっと皆さんが利用できるように工夫していただきたいなと思っているんですが、いかがでしょうか。","respondent":"中山清掃リサイクル課長","answer":"それで、コンポスト化容器について、減傾向の中で再検討の余地というのは私ども認識は持っておるんですけれども、片やおっしゃるように非常に環境負荷が少ない中でごみ減量が行われる、あるいは意識づけとしても望ましいものということはありますので。","id":"exchange-038"},{"speaker":"北野委員","kind":"質問","question":"そういうところの基準ですか、結局８０台以上多ければ、もし抽選であれば、既に買ってしまった方が漏れてしまったという場合もあるだろうし、それから既に購入していて、領収書もあるけれども、大体どれぐらい前までの期間のものなのかとか、やっぱりそういうのを含めて、わざわざ５番にこういうふうに入れたのかどうか。ちょっと細かいことですみませんけれどもお伺いします。","respondent":"中山清掃リサイクル課長","answer":"別に予定価格とずれたからといって、あるいはここの額の多寡で抽選を恣意的に操作する考えはございませんが、もう一つの要素として、事業用のものは別ですということがありまして、一応家庭用ですと、せいぜい安くても４万、３万何千円、購入額でいうとそれぐらいから。","id":"exchange-039"},{"speaker":"北野委員","kind":"質問","question":"わかりました。たしかそういうこともあったと以前報告で伺ったこともあります。いろんな会社の方が来て。だからそういう機会もとらえて、日程が合うので、要するに実際のどこのお店に行って決めようかなとか、カタログを見てというのはいろいろあるんですけれども、そういう機会もとらえて参考にいかがですかという言葉も入れていただけたらよかったなということを。","respondent":"中山清掃リサイクル課長","answer":"チラシには入らなかったことは申しわけございません。それで、後ほどご説明しようかと思ったので、環境・リサイクルフェアの中でもこの辺のご案内をして、目に見える形でご案内したいと考えています。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"それと、あといろいろな内容豊かなクイズ形式というか、そういう形で積極的に認識が持てるような、そういう内容になっているので、非常にいろいろ工夫があったなということを思うんですけれども、また同時に子供たちの声だとか、そういう授業をする先生方だとか、そういう方々の声をこれからもいっぱい拾って、より豊かな内容にしていく必要があるんではないかというふうに思うんですが。","respondent":"中山清掃リサイクル課長","answer":"それで、当然作成するに当たっては、教育委員会、指導課等との連携をとってつくったわけですけれども、実際にこれの活用については、既に学校の先生方の勉強会の場面等でもご説明したところですが、使われてどうなのかという声については当然聞いてまいり、そこの中で。","id":"exchange-041"},{"speaker":"中島委員","kind":"質問","question":"地方に行くと、こういうごみのぱっと見たら百科事典みたいなものが出ていて、これは何はどこに捨てるとか、不燃ごみだとかリサイクルだとか、こういう仕分けができているようなものを出している自治体もあるようなので、これは非常に好評だというのをこの間も伺ったところなんですが、子供たちにもちろんこれを教えていくのは大事なんですけれども。","respondent":"中山清掃リサイクル課長","answer":"通常の分は、今お配りしている分け方、出し方を新たにつくる際には、そういうガイドを配る際の折り込み等をあわせて周知を図っていきたいと考えています。","id":"exchange-042"},{"speaker":"中島委員","kind":"質問","question":"ぜひお願いしたいと思います。私は今でも認識が弱いのかもわかりませんが、これを燃やしていいのかな、どうなのかなというのを迷う場合があるんですね。こういうマークがついている場合は燃やしててもいいだとか、明確に何か区民の方が覚えられるように、そういうものをある程度していただければありがたいなと思ったものですから、意見にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"土井委員","kind":"質問・要望","question":"それを大前提にいたしまして、これはつくられたのは、先ほどのカレンダーもそうなんですけれども、版権は当然区がお持ちだというふうに思いますが、ほかのところでそのままは使えませんけれども、アイデアは使えるものは使っていただけるんだろうと思いますので、ぜひこういうものをつくっているよという意味での、区内的なＰＲもさることながら。","respondent":"中山清掃リサイクル課長","answer":"端的に言いまして、約９５万円で１万２,０００部ということですから、税込みで約１部８０円弱の、単価になっております。","id":"exchange-044"},{"speaker":"北野委員","kind":"確認","question":"わりと小学生というのは、外であまり自動販売機を使って飲むとかというのはないかもしれないんですけど、中学生になると、結構行動範囲が広くて、そこでどんなものをちゃんと捨てるのか、そこにごみのところにリサイクルの缶とかボックスとかに直接捨てればいいですけれども、そういうところで。","respondent":"中山清掃リサイクル課長","answer":"いわゆる若い世代のうちにこういう環境意識、ごみ減量の意識を持つというのは、これは重要なことだということでまずねらいを絞ったのが小学生で、とりわけ先ほど申し上げたように社会科の中で、具体的に４年生にそういうごみについて考える単元がありますから。","id":"exchange-045"},{"speaker":"北野委員","kind":"意見","question":"そういう中では意識はされてきていると思うんですけれども、冊子ではなくても、何かこう簡単にわかるようになっているというところで、自分たちが学習の中で研究できるような材料として、何か使えるような資料としても提供があればいいんじゃないかなと思いますので、ぜひ研究をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"南委員","kind":"確認","question":"だから、表現が短いスペースで端的に物語らなきゃいけないのでこういうふうになっちゃったのかなと思うんですけれども、ちょっとこのところは性格からすると違うので、今さらあれなんですけれども、ちょっと違うのかな、訂正しておいたほうがいいのかなとちょっと思ったので確認をしていただいて、そんなことはいいや、不必要だというのであれば、それはそれでいいんですけれども。","respondent":"中山清掃リサイクル課長","answer":"ですから、そういった意味では、直接工場そのものが高温水をつくるプラントではないと言いますけれども、工場でできた電気という表現をもしするとすれば、同じように熱を燃やしたものを使って発電したり、そういう確かに水分を加えてという形になるんですけれども。","id":"exchange-047"},{"speaker":"南委員","kind":"質問","question":"だから、訂正する必要がないという見解であれば、それはそれで荒立てるつもりは全くないし、問題視するつもりは全くないんですけれども、だから。だから、違うんじゃないかというふうに思うんですね。お湯で来ているわけではありませんから。熱で来ているわけですから。それでいいということであれば別にいいと思いますけれども、ちょっと気になったので言いました。","respondent":"中山清掃リサイクル課長","answer":"高温水という言葉自体が難しいということは、確かにそういう面はあろうなとは、今伺って認識しました。","id":"exchange-048"},{"speaker":"南委員","kind":"意見","question":"仕組みはこれでいいんだろうと思うんですけれども、そういうふうな誤解というのをちょっと与えるという危惧があったので、全然問題ないよということであれば、それはそれで別にいいんですけれども、また改めてちょっと説明を要するということであれば、そういうふうに対応していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"学校の副読本としてお使いになるということの中で、これが継続的に使うのではなく、その中で、例えば授業の中で１時間なら１時間で終わってしまうと思うんですよね。例えば子供がやれば親はやらなきゃいけなくなってしまうという面があると思うんですよね。そういう意識づけのためにも、ぜひ教育委員会の、利用はできないのかなと。前の部長もいらっしゃいますし、その辺どうでしょうか。","respondent":"中山清掃リサイクル課長","answer":"こういう、これだけでなく、いろいろ環境清掃事業部等で用意している環境への取り組みについて、今後教育委員会にＩＳＯとの関係もあって、環境学習プログラムということで、各先生方が利用できるような資料もあわせて配っていくことになっておるんですが。","id":"exchange-050"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"ぜひそれは利用していただきたいと思って。要望しておきます。","respondent":"高木委員長、中山清掃リサイクル課長","answer":"なければ、５番目の項は終了します。これをもちまして、報告事項は終了します。その他に移りまして二つほどご報告がありますので、１環境・リサイクルフェアの実施について、ご説明をお願いいたします。表にも例示が書いてありますが、おめくりいただきますと主な内容が記載されてございまして、清掃・リサイクル関係の品物の展示。ご説明をいただきました。ご質疑がございましたらお願いをいたします。どなたも発言がございませんか。","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"ですからそういう点も、今まで聞いてはいても、なかなかこういう事故になっていないから、多少もう使い切っているつもりだから大丈夫だみたいな、ちょっと安易な意識がなくもないわけですから、ちょっとその辺の周知というのかしら、その辺をどういうふうに、原因究明が先ですけれども、考えていただきたいということをちょっと改めて。ご答弁はいいんですけれども、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"土井委員","kind":"質問・要望","question":"まさしく原因究明が必要なのは事実なんですけれども、現実問題、この種のものが起きる可能性ありということについては、前々からそのスプレー缶なども含めた、それでなくてもいろんな、漏れた油などにコンベヤーの摩擦等や油ぎれで熱を持って発火するとか、ぼろ布が発火するとか、そんなのはいろいろあるわけですから、そういうものに対する対応、対処等がもし不十分だということになると。","respondent":"松本環境清掃事業部長","answer":"それと、先ほど５億ないし６億の被害総額を申し上げましたけれども、当然これは消防庁のほうから改善命令が出るだろうと考えています。","id":"exchange-053"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"死傷者が出たのに申しわけない話かもしれないけれども、この改修に対して費用がかかってくる、これは火災保険みたいなものに入っていて、その分というのは負担はできるんですか。それを１点教えてください。","respondent":"中山清掃リサイクル課長","answer":"しかしながら、部長も答弁申し上げたさらなる改善、設備改善の部分等になると、この経費はまた別途清掃一部事務組合として出てくる可能性はありますが、基本的には保険で現状復帰可能というふうに我々は伺っております。","id":"exchange-054"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"もう１点ちょっと。大田のこれは不燃ごみをここを使っているわけですよね。大田区のほうの。今そこが使えないと、中央防波堤に持っていくというのは、東品川の中継所から持っていっているんですか。それともトンネル、新しくできた向こうから行くのか。それはどうなんですか。","respondent":"中山清掃リサイクル課長","answer":"先ほど申し上げたように、京浜島不燃ごみ処理センターには、大田区が３清掃事務所がありますが、これは直接車で運び込んでいるものが１３４トン毎日あります。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ノーレジ袋運動について、９月か１０月かぐらいから実施するというような方向だと思うんですが、いろいろ検討中だと思うんですが、その後、ここの所管かどうかちょっとはっきり。ここの所管ではない。ごみを減らすというところでリサイクルで関連しているので、そこら辺のところの状況がちょっとわかったら教えていただけるのかなというふうに思いましたんですが。","respondent":"金井環境課長","answer":"今お話がございましたように、これは所管が区民委員会ですので、まだそういう段階に至っておりませんが、区民委員会のほうに先に報告した後に、こちらがごみの減量という形で報告のようなつながりになってくるかと思います。","id":"exchange-056"},{"speaker":"鈴木（真）副委員長","kind":"提案","question":"本年１年間、清掃・リサイクル特別委員会の副委員長を受けさせていただきまして、ありがとうございました。１年間委員の皆様、理事者の皆様、事務局の方々に大変お世話になりまして、ありがとうございました。一言、最後に１回委員会を追加させてしまったというのが、自分のほうで提案させていただいて、２月に１回入れさせてもらっちゃいました。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/815229?Template=document&Id=5662#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":46145,"voices":146}},{"id":"h14-20020515-14","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"行財政改革特別委員会","time":"午後１時０８分～午後３時１２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"４点ほどちょっと質問しますが、一つは３ページの情報公開システムの特徴のことなんですけど、他の区はほとんど情報は無料ですよね。いろんな情報をね。最後に、こうした情報がいろいろ入るわけですから、新たに保護というのは個人保護というか、プライバシーの保護とか、そういう点なんかはどういうふうに考えられているのか、ちょっと大ざっぱなんですが、お伺いします。","respondent":"田中情報システム課長","answer":"情報公開手続の部分ですが、改善の余地があるかということなんですが、基本的に検討に当たりまして、情報公開の個々の件名の文書等を公開するわけではありませんので、現在でも情報公開の窓口ではファイル基準表というのをずっと置いておりまして。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、非常に情報公開の手続を、来て、３００円払うという、そういう取り方と、インターネットでどんどんとれるのと、すごくアンバランスというんですか、なんか全然脈略がないというのか、だから、そういう点で、私はもう一回きちっと整理をし、もっとより情報の公開を求めたいというふうに思うんですけど、そういう点での改正の余地があるんじゃないかということです。","respondent":"田中情報システム課長","answer":"先ほど言いましたように、ずっとこれをやり続けると、どうも圧迫感があって、何かどうなんだというようなことがあると思いますが、これはこれだけに限らず、仕事の部分やなんかでも、それなりに気晴らしだとか、ストレスの解消等ないとつらい部分があると思いますので。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"もちろんそれらに基づいて情報公開するわけですから。それからもう一つは、最後の住民サービスの関係ですけども、これからの課題だと思うんですが、この部分について、直接やっぱり住民への意見を聞くというんでしょうかね、どういう点でそうしたサービスの分野で情報が欲しいかという点で、ある面では住民システムということからも出発しているんではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"嶋委員","kind":"質問・要望","question":"すごい基本的なことなんですが、まず機械を見せていただいたんですが、富士通。全部、庁内ＬＡＮは富士通ですか。それからあと、全部質問申し上げます。それとあと、３ページの、先ほどもありましたけど、情報の共有化、キーワードじゃなくて、セキュリティを考えて、職員が閲覧した場合は、閲覧した履歴情報を記録するとありましたけど、これはどういう形で記録をされていくのか。","respondent":"田中情報システム課長","answer":"公開端末、家にインターネットやパソコンを持っていない方たちに対する対応を含めまして、２４時間、土曜日や日曜に空いている施設ですとかを含めまして、置くところを十分検討していきたいというふうに思っております。","id":"exchange-004"},{"speaker":"嶋委員","kind":"質問","question":"さっきのだれがというのがまだわからないことと、それと、役所の中でどこのほうに、いわゆる自由に使える場所が設置されていくのか教えてください。","respondent":"田中情報システム課長","answer":"どこに公開端末を置くんですかというところは、区民にとって利便性の高いところを検討していくという基本的な考え方で、いろいろな施設予約等を含めまして対応できるように十分検討していきたいと考えています。","id":"exchange-005"},{"speaker":"嶋委員","kind":"質問","question":"このＩＤ・パスワードを持っている人というのは、限定をされているということでしょうか。","respondent":"田中情報システム課長","answer":"ＩＤ・パスワードは個々人に振られています。今区役所ですと、２,２５０人程度ＩＤ・パスワードが配布されております。その人たちは自分の独自のもので入りますので、ちょっと現業系等、まだ振っていないところがあります。","id":"exchange-006"},{"speaker":"嶋委員","kind":"確認","question":"わかりました。じゃあ、２,２５０人の人が大体持っているということで、これは人のパスワードを知らないということを前提としているということで了解をしてよろしいんでしょうか。もし、私たち仲間は意外とわかっている場合があるじゃないですか、お部屋の中で。あの人のパスワードは幾つと。そういう場合なんかはありますよね。そういうことがあるのかないのかだけ、ちょっと確認をしておきたいと思います。","respondent":"田中情報システム課長","answer":"基本的にＩＤ・パスワードは個人を認識するものですから、これは必ず人には秘匿して、自分の、例えばキャッシュカードの暗証番号を人に教えないのと同じように、ＩＤ・パスワードは人に教えないということが前提ですので、個人を識別する手段になりますので。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"４ページ目のシステム開発の効果と経費のところですが、効果の考え方として、財務会計で９億６,０００万円ほど、文書で４４億円、勤怠管理で５億８,０００万円ほどの減額等、それぞれ平成２２年までの合計と、短縮される時間が省力化されると載っておりますが、時間はわかるんですけど、この金額はまずどういう形ではじき出されたのか、それにかかる、それぞれの時間が省力化されて。","respondent":"田中情報システム課長","answer":"前提として、大体このシステムを利用する対象職員を事務職員と、それから技術系の職員、あわせて１,６００人程度というふうに想定しております。年間稼働日数がそれぞれ職員の２２４日として、１人当たり年間稼働時間１,５６８時間ということで計算しております。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"そうすると、当初の初期投資の分と相殺されて、さらにそれぞれの効果が出るという考え方ではなくて、投資の部分は投資で経費として別にかかっているということで、トータルでの効果ということではないということですか。いずれ数字を出される予定とか。","respondent":"田中情報システム課長","answer":"定数減による効果と作業数、作業の工程等がなくなるとか、それから帳票等がなくなるとかというところを含めまして、最低限これぐらいが事業を実施した場合、最低限の効果はこれぐらい出るということです。システム開発の初期投資の部分は、３億円強の部分であります。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、経費としては１億２,０００万円毎年かかるけれど、それに上乗せして、この金額がかかるのではなくて、これがかかりながら、省力化によるプラスはかかるということで、切り離して考えるという、全くこれぐらいの金額がという理解でよろしいんでしょうか。","respondent":"田中情報システム課長","answer":"共同開発、共同運用の面では、一昨日に東京都と都下の市区町村で共同開発、共同運営の準備会を発足させました。これは電子調達の関係、それから電子申請、電子届出の関係、それから統合型ＧＩＳの関係を開発課題とした検討を進めるということでやっております。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"そこのシステム等の再構築のところなんですが、先ほどのように小型のサーバーが開発されて、そういうものを利用して、あとＷｅｂを利用して再構築をしていくということでありますが、先ほど嶋委員がおっしゃられたように、富士通のシステムが、メーカーにおいては富士通のシステムなんですが、今後こういう再構築するに当たっては、既存の財産といいますか。","respondent":"田中情報システム課長","answer":"ただ、今後のことを考えますと、業者の競争環境を担保するという意味で、できるだけ標準的なものを入れて、次の世代の段階では多くに競争できるようなところに移行していけばと思うんですが。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"ちょっと脱線してしまうんですが、これだけ区長部局と議会は車の両輪と言われておりますので、区長部局の情報といいますか、情報システム課がどんどん大きくなっていく中で、両輪である議会側の考え方というんでしょうか、それはぜひ再考し得るような構築を将来的には考えていきたいなと考えています。その辺の考え方だけちょっとお聞かせください。","respondent":"福田区議会事務局長","answer":"こちら本格的なシステムをスタートするという段階ではありますけれども、事務局として、どのような対抗が考えられるか、それは十分検討に値するというふうには考えております。","id":"exchange-012"},{"speaker":"辻副委員長","kind":"質問","question":"こんな字を使うの。何か違和感を感じるよね。これはその入り口を絞ればバーッと絞れるなという、そういうのでやれば、よりオープンな形の一般競争というものに対して参加を呼びかけていくというか、そういう何も研究という、まさしく私は、これから進む電子自治体という方向へ行くべきだと思うんですけど、その辺の今課題になっているというのはどの辺のことで、今後やっていくんですか。","respondent":"田中情報システム課長","answer":"２点あるかと思いますが、最初のネットワーク部分は、庁内と出先を含めて、すべての出先をネットワークで結んであります。庁内の特に第一庁舎については古い建物なので、なかなか有線のケーブルが引けないというところがありますので、無線ＬＡＮで第一庁舎はやっています。","id":"exchange-013"},{"speaker":"辻副委員長","kind":"質問","question":"もう一つ、先ほどから何件か出ていますけど、電子決裁での日常的な執務の内容の中なんですけど、今ワープロが入ってきたり、パソコンの時代に移ってきたわけですけど、職員の皆さん方がそれの流れの中で、要するに文書をつくって、今は事業部になるんでしょうか、前は一つ一つの部、あるいは課長単位でいろいろ集まって、いろいろやりますよね、日常的な、この事業はどうしようかとかというときに、それを。","respondent":"田中情報システム課長","answer":"執務のイメージですが、今でもイントラネットを入れまして、各課でいろいろ検討する際に共有フォルダというのがありまして、その文書の大きな保管庫みたいなものをコンピュータ上持っていまして、それで係員、課長を含めまして検討した内容を次々に入れていく。","id":"exchange-014"},{"speaker":"辻副委員長","kind":"質問","question":"いわゆる電子会議室というのはわかるんですよ。私もやっていないわけじゃないし。そのときに、ディスプレーを一つ持ってきて、まさしくそれは無線ＬＡＮであれば、全部８人、８人、１０人と持ってこれるわけですよ。これはこう思いますと。これを説明しながら、これはこうして文書をひょっと直そうかというのを、そういう会議室というのはあるべきじゃないんだろか。それが、どうなんですかと聞いているわけ。","respondent":"田中情報システム課長","answer":"各自のパソコンを持ってきて会議をやるという、できるように、この部分を無線ＬＡＮのときに検討したんですが、機能としてはローミングという機能で、それぞれどの階に行っても、持っていってもできるような機能があるんですが、ただそうすると、いろんな回線の容量ですとか。","id":"exchange-015"},{"speaker":"辻副委員長","kind":"質問・要望","question":"要望で終わりますけど、基本的には我々所管の委員会としては、行政改革の特別委員会ですので、費用対効果というのを考えなきゃいかん。今、今日ですか、有楽町でビジネスショーをやっている。そういうふうになってきたときに、民間企業から見たときに、何だと言われないようにやっていくだけの、やっぱりそういう感覚というのはぜひ持っていただきたいなと、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鶴委員","kind":"質問","question":"一体どうなっているんだ。４０分間ぐらいは何とか蓄電池で発電して、瞬時にデータが滅失しないように対応する。果たして４０分間で対応できるのかということもあるし、まず、危機管理というのは一体どうなっているんだ。そういう中で、果たして、その電子データというのは守られるのか、破壊工作に、破壊工作員がもし入ったとしたら、どう対処していくのか。どうなっているんですか、今の段階で。","respondent":"田中情報システム課長","answer":"すぐ地下の警備の人が飛んで来るという形になっております。その点で、最大のところでは、２４時間、その部分では入退室管理を続けているということで対応しております。","id":"exchange-017"},{"speaker":"鶴委員","kind":"質問","question":"それはそうだろうと思いましたが、問題は、そのセキュリティのマニュアルというのがしっかり守られているかどうかと、日常的にね。だからあえて聞いたんですね。このパスワードはだれだということがわかるけど、そういう場合は、どういうペナルティーがかかることになるわけですか。今の公務員法、地方公務員じゃなくて、あるいは国家公務員法の言うところの、どこが、何が適用されるわけですか、その人は。","respondent":"田中情報システム課長","answer":"例えば、契約の予定価格があります。これは決裁ルートの人は見ますけど、ほかの人は入札が終わるまで見てはならないし、見る必要もないわけですので、当然所属ですとか、その人の職ですとかに必要に応じてアクセス制限をするということで対応していきたい。","id":"exchange-018"},{"speaker":"金高委員","kind":"意見","question":"先ほどの設定の中で、ウイルスのチェックをざっと言われましたけども、これは今までそういうウイルスが侵入したということがあったのかどうか。それから、これからどんどん技術が発展していきます。そういったところから侵入経路が複雑になっているということですので、技術がこれから進歩していけば、それに対するウイルスのチェックをもっともっと厳しくしなけりゃいけない。見通しをお聞かせください。","respondent":"田中情報システム課長","answer":"システムの侵入の部分ですが、今まで、例えば１月に１０件ぐらいウイルスをはじいている履歴録があります。ですから、外から来るものはファイアーウォールで全部はじいて、その記録は残っています。","id":"exchange-019"},{"speaker":"辻副委員長","kind":"質問・要望","question":"どうも、この１年間ありがとうございました。今後とも、また行財政改革、さまざまな課題に取り組んでいただきたいし、また、我々もやっていきたいと思います。ほんとうに１年間ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/114679?Template=document&Id=5706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":25541,"voices":47}},{"id":"h14-20020515-16","meetingId":"h14-cm05","date":"2002年5月15日","dateIso":"2002-05-15","committee":"街づくり特別委員会","time":"午後１時０４分～午後３時３８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"ちょっと二、三、最初に基本的なことをお尋ねしたいんですけれども、前回もちょっと伺ったかと思うんですが、４街区全体にかかる区の方針区域という言葉を使っているわけですが、それから整備計画区域、中地区で言えば、今度は何というのか、いろいろな言葉が錯綜しているようなんです。それを最初に、ちょっとお願いいたします。","respondent":"南雲都市開発課長","answer":"再開発の地区計画というのは２段階になっておりまして、まず、土地利用の方針ということで、今後、こういう区域の土地利用をどういう方向に誘導していくのかということで、用途ですとか、どのような機能を持ってくるのか、こういう方針をまずある程度の広い範囲で定めます。","id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"何せいろいろな名前がついていてよくわからない、違いなどがよくわからなくなりまして、失礼いたしました。それで、最初に二つお尋ねをしたいんですが、あまり長くはなりませんので。それから、もう一つなんですけれども、遠いところに一番最初に網をかけるというんですか、実際に進めていく上で、妥当性というか、整合性というんですか、そこら辺はどうなんでしょうか。ちょっと２点、お願いしたいんですが。","respondent":"南雲都市開発課長","answer":"先ほどありましたように、ここはやはり幹線道路、１６３号線の奥まったところにありますので、奥にある中地区だけ先行しても駅にアクセスすることができませんので、こういう周辺の基盤の整備についてめどが立ちませんと、中地区だけでは整備が進められないということで。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問","question":"これで終わりにいたしますけれども、以前、これも一度伺ったことがあるんですが、再開発を進めていく上では、大きなネックとして保留床の問題があると、課長がどこかでのあいさつの中で一度触れたことがあるかと思うんです。私どもも一度質問したことがあるんですが、特に中地区の保留床について、買い手が決まったのかどうか。これで質問を終わりにいたします。","respondent":"南雲都市開発課長","answer":"そのうち、準備組合に加入てしておりますのが７６権利者でございまして、未加入が８権利者ということで、約９割の権利者が準備組合に加入しているという状況です。","id":"exchange-003"},{"speaker":"藤田委員","kind":"質問","question":"以前から西口につきましては話がありまして、ようやくここまで来たなという感があるんです。やっぱりまちをつくるには、人が集まって来なければあまり意味がないまちになってしまうんではないかということで、この地域の個性、特性は一体どういう。その辺を、まずちょっとお伺いしたい。交通広場の機能について、ご説明いただければと思います。","respondent":"南雲都市開発課長","answer":"バスにつきましては、具体的にどのような路線が入るかはまだ協議をおりませんが、機能としましては、バス、タクシーを対象にした施設を考えているです。","id":"exchange-004"},{"speaker":"藤田委員","kind":"質問","question":"だた単なる広場をつくって、人を集めて何かイベントをやるということだけはなくて、そういうのがあるかどうかという質問なんです。それにしたがって、例えば夜、イルミネーションをどんと張るとか、周辺に彫刻の小道にして、いろいろところから大崎に集まってくるというような、そういう人の集まり方の計画があるのかとお聞きしているんです。","respondent":"南雲都市開発課長","answer":"西口につきましても、単なるオフィスだけではなくて、ショールーム的なもの、人を呼ぶような施設ということも考えられるのではないかということで、具体的には、今後、各事業者と協議していきたいと考えております。","id":"exchange-005"},{"speaker":"藤田委員","kind":"質問","question":"目黒のアトレが、つい先日、完成しましたね。ですから、こういうまちづくり、再開発というのは、業務棟、住宅棟は確かに必要ですけれども、いろいろなところからまちに呼ぶという、レジャー施設も含めて、若者がすっと集まって来れるようなまちづくりを目指さなければ、今回はほんとうに概略の都市計画の話ですけれども、今のうちからそういう検討、話し合いをぜひお願いしたいなと思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"上山委員","kind":"質問・要望","question":"１点だけなんですけれども、今度、東口第３地区ということですが、１ページを見ると、相当あちこち色がかかって大変驚くというか、この前、一つ説明がありましたが、大変大きな計画もあるんだなと思うんですが、これは置いておいて、今後、進めるべきお願い、要望みたいなものがあるんです。そこら辺の思いといいましょうか、一言あれば、何かお返事していただければありがたいんですけれども。","respondent":"南雲都市開発課長","answer":"今後も、細かく話をお聞きして、その方の意向がそういうことであれば、その意向がかないますように、十分な対応をしていくように、組合に対しても、区のほうから、今後も十分な指導をしていきたいと考えております。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問・要望","question":"人の流れも、最近では大変多くなっているんです。当然、自動車や人の流れ、トリップ調査などをやっていると思うんですけれども、どんなふうに変化していくのか、あの商店街の交通渋滞などをどういうふうに緩和を図っていくのかなど、そういうことを含めて、本開発にあわせて、近隣との調和がどういうふうに検討され、今、進められようとしているのか、もしわかれば教えていただきたいと思います。","respondent":"南雲都市開発課長","answer":"青物横丁の駅からこのシーサイドフォレストまでの歩行者のルートというものを魅力あるものにしていこう、それから、シーサイドフォレストと青物横丁の間にあります接続点の部分には広場に設けて、人のたまり場になる、人を集客するような施設をつくるということで。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問・要望","question":"もしそういう調査をやっているのであれば、教えていただきたいと思うんです。その努力の成果も、具体的な形であらわれつつあるということも聞いております。地域では高齢化が進むなど、やっぱり地元、地域の商店街というのは、一方ではその必要性が増しているわけです。ですから、人の流れがどう変化するのか、具体的にそういう数字を示していただきたいと思うんですが、出ているのか、出ていないのか。","respondent":"南雲都市開発課長","answer":"この開発に先立ちまして、車、それから人、それぞれ開発に伴ってどのような発生、集中の増があるのかにつきましては、調査をいたしておりますが、ちょっと整理させていただきたいと思いますので、次回、ご説明します。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問・要望","question":"個別といいますか、今回、委員になっている皆さんにも、個別に示していただきたいということを、とりあえず要望しておきたいと思います。そういうことを含めまして、乖離した形の開発ではなくて、いかに地元の努力が実る、調和がとれたまちがこの一帯にできるかということを、行政サイドとしても、相当努力していただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"築舘委員","kind":"質問","question":"そんなことで、この駅ができることによって、交通広場があるわけですから、品川駅に行くバス、また大井町駅に行くバス、大井競馬場と品川の海岸通りのバスもありますけれども、それは一たん交通広場のバスの停留場にとまって、そして行くということだと思うんです。その辺の都のバス路線の計画というのは、いつごろ、どういうふうな形で、またどういう連絡が来ているかどうか、そこがわかれば教えてください。","respondent":"伊佐都市計画課長","answer":"交通局はその方向で検討しているですが、どういう形で出てくるかという具体的なことは時期とか、流れについては、ちょっと詳しい情報は来ておりません。いずれにしても、品川シーサイドの広場に八潮から乗り入れるバスについては必ず実現する。","id":"exchange-011"},{"speaker":"築舘委員","kind":"質問・要望","question":"単に、需要がないからと減らしたということなんですが、その後の推移ということで考えれば、需要が増えれば、またバス路線も増やすということも可能になってくるわけですから、そこのところをよく、品川区としての要望といいますか、この地域の思いというのを伝えておいていただきたいということで、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"上山委員","kind":"質問","question":"今回の二期工事に直接でないんで、それとの係わりで幾つかお尋ねしたいんです。最初にこちらを伺いたいんですけれども、前に説明があったかもしれませんし、私が聞き漏らしていたら申しわけないんですけれども、整備の計画、例えば駐輪場などを含めてどんな感じなのか、わかれば教えていただければと思ったんです。わからなければ、直接きょうのあれじゃないんで、後でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"上山委員","kind":"意見","question":"もう一つだけ。それで、ちょっとお尋ねなんですけれども、これもきょう直接の議題じゃありませんから、ここで論議するつもりもないんですけれども、戸数はわかりますけれども、例えば子育て世帯かどのぐらいがよくわかりませんけれども、学校だとか、保育園だとか、そういう施設を含めて、そういうことも現状から見ればぐっと増えて、大丈夫なのかなと思ったりするんです。","respondent":"南雲都市開発課長、岩田管理工事課長","answer":"その推計値でいきますと、周辺の隣接する小学校、中学校で十分に対応できるであろうという推計をしていると聞いてあります。やはり同じ戸数でも、これまでに比べますと、子どもが発生する数は減っている。駐輪場につきましては、四角く点線で囲ってあるのが品川シーサイド駅になるんですが、このちょうど真下の部分の交通広場部分に、約７００台の規模の駐輪施設を持つ。再開発事業で生み出す計画になって、現在、工事中です。","id":"exchange-014"},{"speaker":"上山委員","kind":"質問・要望","question":"江東区もそういうことで、何か要望だとか、変えるような話も伺いましたけれども、単純に品川区もそうしろとは、私は申し上げる気もありませんけれども、今度、そういう狭い、今まであまりなかったところにどんどん増えちゃうと、やっぱり人口の問題だとか、インフラの整備の問題も、区が担当を全部やるということではないと思うんですけれども、そういう問題も発生してくるんじゃないかと思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけ、ちょっと確認をしたいんですけれども、再開発地区にいろいろな工事をかけている中で、たまたまここに不幸にして火災が起こって、１人亡くなるという事故というか、そういうことが起こったんです。こういうことが起きた場合、区としてどのような対応をして、施工業者でも、開発業者でもどこでもいいけれども、そういうところにどういう対応を求めるのか、どこまで事情説明を求めるのか。","respondent":"南雲都市開発課長","answer":"今後の指名などについても、場合によってはなくなるというようなこともありますが、今回の場合には、都市計画を定める中で、どのような施設をつくるかについては行政としてもかかわっておりますが、その後の工事につきましては、民間の事業者が工事を発注しておりまして、直接。","id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"そうすると、個別の契約はもちろんわかりますけれども、こういう場合についての説明というのは、必ず来ることになっているんでしょうか。今のお話だと、説明責任というのか、こういう事故があったときの報告義務というのか、それは相手に任されていて、品川区に来るのか、来ないのかというのが明快じゃなかったような気がするんです。そこら辺のところはあるのか、ないのか、ちょっと明解に教えてください。","respondent":"南雲都市開発課長","answer":"提携にもよりまして、生命にかかわるようなこういう大きな事故の場合には、その都度、事業者から報告は受けております。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"都市計画はこれからいろいろなところがあると思うんですが、申し合わせ事項でも何でもいいんだけれども、そういう形の中で、そういう報告を受ける体制を、ある程度明解にしていただいて、ぜひ、それについて、区としても、それに対してものを申せるんであれば、ものを申していけるようなものが、もちろん法的には別なんだけれども、申し合わせ事項みたいな形の中で要望ができれば。","respondent":"南雲都市開発課長","answer":"やはり、労働災害を減らすという点からも、仮に事故が起きた場合には、現場の管理体制をさらに向上させるように、行政としても、各事業者にその辺の要請を行っていきたいと考えております。事故の内容によりましては、委員会でも報告をさせていただきたいと考えております。","id":"exchange-018"},{"speaker":"川西委員","kind":"質問・要望","question":"簡単なことです。そういうことがありますから、さっきのご質問の中でいただいた答弁では、今後、もう少し調整をしてみて働きかけるようなことですから、そういう答弁なのかと思うんですけれども、お答えができなければ、要望にとどめます。だから、そういう点では、住民の声としてお考えいただきたい。さっき、路線については細かいものを示されるということなんでしょうから、それでも結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"直接これに関係ないんですけれども、これまでの３件、大崎駅西口、東口、それにこれに係わる内容で、再開発で道路提供というか、道路の定義をちょっと教えてほしいんです。そういった整備の中で、８ｍだとか、１０ｍ、１２ｍと、いろいろと幅員の求め方が違ってくる。そして１２ｍを求めるときには、片側２車線、４車線を取ろうとして求めているのか。幅員に対して、車線をどう考えているのか。","respondent":"岩田管理工事課長","answer":"ですから、委員のおっしゃるような、ほんとうに望ましい道路というのは、東品川四丁目の中央に走っている区画街路がいわゆる１５ｍ。当時は、最低幅員１５ｍが都市計画の定めでありましたので、１５ｍ取っているのが一番望ましいものです。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"今、お答えをいただいたように、それぞれの地域で提供していただくというか、整備している道路幅がみんなまちまちなんで、どうしてかなというと、それぞれのまちの環境というか、実情がそこに反映されているんだと思うんです。それだったら、３本走っている、Ａ、Ｂ、Ｃ、Ｄだったか、何度も聞くけど、１２ｍ取っているんだけれども、これは全部車道ですか。それでいいですから。","respondent":"南雲都市開発課長","answer":"西口の道路でいきすと、１２ｍの道路というのは、歩道も含めたものでございまして、車の通る車道部分は８ｍございまして、両側に２ｍずつの歩道です。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"それに平行して、歩行者通路２号というのが、８ｍの１８０ｍ走っていますよね。前に戻っちゃって悪いんだけれども、これも、今言うように、そういう考え方でよろしいんですかね。","respondent":"南雲都市開発課長","answer":"歩行者通路２号といいますのは、これはペデストリアンデッキでございまして。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"直接関係ないんで、結構です。道路の定義をちょっとお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"石田委員","kind":"確認","question":"私もこういう数字のことはわからないので、今の横山委員のお話の中で、確認だけしたいんですが、公開空地を利用するというお話があったですよね。例えば東五反田で、今度民間でやるとかいろいろあると思うんですが、これは完全にお願いをしていく話になると、できるできないという場合が出てくる可能性もあるのですか。そこら辺の点を、法律的なことはわからないので、ちょっと教えてください。","respondent":"南雲都市開発課長","answer":"そういう場合には、セットバックするというか、後退することが物理的に不可能な場合もありますので、そういうものも含めて全部というわけにはいきませんが、計画的にされる規模の大きいものについては、最大限、地元のほうと協議を行いまして。","id":"exchange-024"},{"speaker":"本田委員","kind":"質問","question":"今の東品川四丁目について言えば、四丁目でも、新しく真ん中に道路をつくりますよね。それを、何％出しなさいというようなきつい言い方をするのかどうかわからないけれども、協議の中で、どういう道路づけがこの開発の形状としてどういう道路幅員がいいのか、それが減歩率に合っているのかどうなのかというようなことが、根拠としてあるんじゃないですか。そこはどうなんでしょうか。","respondent":"岩田管理工事課長","answer":"したがって、再開発地区計画で大もとに考えるのは、まず都市基盤整備をどういうふうに考えるのか。それだけ都市基盤整備ができれば、その土地に見合った容積としてはどれぐらいになりますよというのがまず第一の見直し容積になるわけです。","id":"exchange-025"},{"speaker":"本田委員","kind":"質問","question":"先ほど、横山委員の質問を聞いていながら、１２ｍとか、１５ｍとか、それぞれの置かれている地域の状況に応じて、原則的なものからその状況に合ったものを検討されてきたんだなということを理解するんですが、その法的な根拠として、行政が指導する際に、お願いしますじゃなくて、最低線、減歩というものの考え方があるならば、それだけ土地の価値が上がるんだから。","respondent":"南雲都市開発課長","answer":"これは、区画整備の減歩とは中身は違うんですけれども、考え方としては同じようなものでございまして、再開発地区計画の中では、道路ですとか、公園をどれだけ出したかに応じて、容積率をアップさせるということでバランスを取るということです。","id":"exchange-026"},{"speaker":"本田委員","kind":"質問","question":"減歩率何％というのは、区画整理でやるような決まり事とは違って、開発については、ものの考え方としては、道路確保をするについても、減歩的な考えはあるけれども、状況に応じてボーナスをどういうふうにつけるかを含めて、空地、道路の確保を協議の中で検討すると理解してよろしいんですか。","respondent":"南雲都市開発課長","answer":"それに基づいて計算して、容積を上積みしていくというやり方をとっております。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどの上山委員の質問に関連して、ちょっと聞きたいんです。住宅棟が２棟できて、住宅が８００戸できるということで、それに関連して、公共施設への影響がどうなのかという質問だったんですけれども、それは影響ないという結論は、先ほどのご答弁であったんですけれども、その調査の概要といいますか、どういう感じの内容だったのか、ちょっと教えていただければと思います。","respondent":"岩田管理工事課長、南雲都市開発課長","answer":"ただし、具体的に２ＬＤＫがどのぐらい占めるか、１ＬＤＫがどれぐらい占めるかといういわゆる間取りの規模によっても大きく左右されてまいりますので、これについては、現在の建築計画の中で、公団側がかなり詳細に発生率を出して。ただいま、都市整備公団ではいろいろ管理しておりまして、この近辺に、天王洲ビュータワーというのが平成７年にオープンしております。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"今、想定するに当たって、例えば小学生だと、２ＤＫで０.０４人とか、そういう係数があるということなんですけれども、先ほど、学校、保育園等で聞いたんですけれども、小学生、中学生、保育園児、ここら辺で具体的何人というのは出ているんですか。","respondent":"南雲都市開発課長","answer":"シーサイドフォレストで何人というのは、ちょっとはっきりしておりませんが、例として二丁目第１地区の場合、小学生で、分譲、賃貸を合わせまして２８人ということを推計して、周辺の小学生でこのぐらいの児童が増えるだろうということで、事前に計画の中に盛り込んでおります。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今のご答弁で、小学生２８人ですか。８００戸で２８人ですか。〔「二丁目第１地区」と呼ぶ者あり〕わかりました。では、先ほど、保育園の考えが公団のほうであるとかないとかおっしゃったんですが、その後、どういう中身なのか、わかっていたら教えていただきたい。区はどういうふうに考えているか。そこのところを、区の考え方というのをちょっと聞かせていただければと思います。","respondent":"南雲都市開発課長","answer":"これにつきましては、ほかの周辺も含めまして、公団で相当な戸数の賃貸住宅を管理しておりますので、過去の公団の例からの推計で、大きく数字が違うということはございませんので、おおむね公団の推計した数字ぐらいの生徒が発生するということで。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。先ほどの、もし具体的に何人というのがわかったら、後で教えていただければと思います。保育園のほうのことで、その後のことがわかったら。それから、住宅のことで、先ほど、２ＤＫの例が言われましたけれども、今の時点で、どういう内容で住宅が計画されているのか。広さとか、家賃とか、ポイントをちょっと教えていただければと思います。","respondent":"岩田管理工事課長","answer":"申しわけございません。ちょっと手元に資料がすぐに出てきませんので、今、取りにまいりますので、後ほどご報告します。","id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"質問","question":"二つお伺いします。先ほど、議論が出ましたけれども、青物横丁駅付近の交通量を調査したということは聞きました。それからどうするのかということのほうが、むしろ関心がありますので、調査の交通量の結果が数字として出ますでしょ、その結果をもとに、これからどうしていくのかということをお聞かせくださいということが一つ。二つほど、お願いします。","respondent":"南雲都市開発課長","answer":"先ほど、ありましたように、大崎駅周辺に比べますと、品川シーサイド駅周辺につきましては、広幅員の道路が網の目のように走っているということで、片側２車線以上ある道路が相当あるということで、交通をさばける容量としては、相当深い能力を持っている地域です。","id":"exchange-032"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"推計では渋滞が出ない。実際に、ここにまちができて、交通アクセスとか、いろいろなことに対して非常に快適なものを求めていくわけですし、各委員がおっしゃったように、交通アクセスの問題もそうです、バスのアクセス、それから人とか自転車とか、当然、小さなまちができるわけですから、そういうことに関して、数字の上だけでつかんで、それでいいですよって、私はちょっと違うような気がするんです。","respondent":"中谷まちづくり事業部長","answer":"残りの現実的な問題としては、土日に集中するというようなことがありますから、こういうものについては、例えばジャスコのオープンのときなどを控えては、周辺のソフト対応、先ほど委員のお話もありましたように、例えばガードマン、あるいは臨時看板みたいなものを出すとか。","id":"exchange-033"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"だから、そのことを繰り込んで、今、部長がおっしゃったような、お金をかけない対策ができるわけですから、看板をつけるとか、誘導の工夫をするとか、ジャスコにお願いして店内でもそういうＰＲをしていただくとか、簡単な発想でいろいろな効果ができるはずなんですよ。そういうことを含めて、ぜひ、このまちづくりに関しては進めていっていただきますように要望しておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"保育所のほうは、協議中だということなので、早く結論が出るように願いたいと思います。教育とか、そういうものを含めてのまちづくりだと思っていますので、ちょっとそこのところだけ一言言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"２月１２、１３日に出席された方は、どれぐらいいらっしゃるんでしょうか。このアンケート調査に基づいた区の考え方はこうですということを住民に周知するという部分、そういったことについてはどういうふうに考えていらっしゃるのか、このあたりを聞かせてほしい。","respondent":"浜脇住環境整備課長","answer":"それが４月２４日で２０名です。２５日が２５名です。計４日間、やらせていただきました。周知につきましては、当然、まちづくりニュース等でやって、こういうご意見があったというようなことも含めて、１,７００部ですけれども、ニュースを全戸配布しています。","id":"exchange-036"},{"speaker":"三上委員","kind":"質問・要望","question":"４月にやったというので、少しは安心したんです。最初の説明のとき、２月１２、１３日に何名出席したかという数字も言わないし、これは悲惨な状況だったんだなというような感じがしたんです。こういった防火不燃に対してのまちづくりの考え方ですから、全戸配布ということを、これ１回限りということではなくて、いろいろな状況を利用して徹底していっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"意見","question":"先ほどもちょっと言ったんですけれども、本来、ここだと学区はどこになるんでしたっけ。小学生で８６名だと、単純に言うと３クラスになるわけですね。そこで、教育委員会の発想が、ブロックとしてキャパシティがあるということなのか、どうなのか。そこら辺のところは、街づくり事業部としては、どういうふうに受けとめておられるのか。","respondent":"岩野まちづくり事業部次長","answer":"この計画協議をしていたときには、ブロック以前でございまして、ここの学区の学校の余裕人員と発生の人員ということでやって、大丈夫という結論を出したと考えています。","id":"exchange-038"},{"speaker":"上山委員","kind":"質問・要望","question":"あちこち増えちゃって、もうわからないぐらいに多くなっているような感じがしまして、そのあたり含めてもしあれば、もうちょっとわかりよくまとめていただけないかと、要望しておりますので、よろしくお願いいたします。","respondent":"南雲都市開発課長","answer":"各地区で相当いろいろ開発をしていますので、各地区の概要をまとめたあらましというものをつくっております。まちづくりマップということで、実際の地図上でどの場所をというのがありますので、そちらの資料をごらんいただきたいと思います。必要でしたら、お持ちいたします。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/783739?Template=document&Id=6230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":43483,"voices":118}},{"id":"h14-20020521-5","meetingId":"h14-cm05","date":"2002年5月21日","dateIso":"2002-05-21","committee":"総務委員会","time":"午前１１時０３分～午後 ３時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"今の説明を、非常にさっぱりした感じを受けながらききました。この反対に品川区としてどういう思いを持っているのかというのがほとんど伝わらない説明で、よその話を聞いているような感じを受けたんですけれども、実際に品川区として移転問題にどういうふうに思いをはせているのか、その辺の品川区としての気持ち、考え方をお聞かせ願いたい。","respondent":"小野（孝）政策担当課長","answer":"説明が事実経過だけに限らせていただきましたけれども、品川区は区民憲章でも言っておりますように、東京の東海道一の地区ということで、東京都の中では非常に伝統のある地区ですし、京浜工業地帯の発祥の地、近代日本の産業の発祥の地ということで。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"やっぱり、国が決めることにすべて従うということではなくて、今は地方分権、地方主権とまで言われている時代に入ってきたのなら、首都というものを支えている地方自治体としては、もっと鮮明に打ち出していっていいんじゃないのかなという思いがするんですけれども、すぐに何をというと、パンフレットをつくったらどうのというわけではないんだけれども。","respondent":"中尾根企画部長","answer":"しかし、国会レベルの法律的な段階の中では、思った以上に進展してきておりましたので、そういう意味では第三次長期計画の中での位置づけが自治権拡充の一本の中に出てきましたので。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"我々が行政視察でたまたま候補地にエリアに行って実際の職員に聞いてみると、「上のほうで何かやっているみたいですね」とか、「何々先生は一生懸命のようですけれども、我々にはどうも」という答えが返ってくる。真実はどうかわからないけれども、我々を東京ということでお世辞的に言っているのかもわからないけれども。地方の自治体はそんなに一生懸命に見えない。","respondent":"濱野助役","answer":"この時点に来て、やはり現実のことを目の前にしながら、実際にそうなったらどうなるのかということを考えると、地方自治法自体も大分いじらなければならないような事態だと思いますし。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"移転しなくても危機回避みたいな部分があるわけですから、そういうところをどんどん言っていくべくだし、２３区あるいは三多摩のほうも含めた東京都の市町村が、それこそ手を結んで東京都と連携を取って声を出していく、あるいは首都圏の市町村も含めた連帯を、今助役が言われた向こうの市町村が最初は気合を入れていたのが、今はそれが削がれてきているんだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"土井副委員長","kind":"提案","question":"よその区市町村も含めた方々ですから、１ページ目をあけたら、そこに「品川区は反対です」という場面が流れてくるようなものを早速始めていただきたいと思うんです。これだったら、次の何かの改定のときにちょっとそこに入れることはできるでしょう。ぜひ、それぐらいから始めましょうということで提案をするんですが、お考えをお伺いします。","respondent":"中尾根企画部長","answer":"実際上、そういうことについて今まで何も取り上げてきていなかったということですから、できるところから始めたいということで考えておりましたので、そのことは十分受け止めさせていただきたいと思います。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"確認","question":"確認しておきたいんですけれども、資料１の最初に経過があって、国が主張する移転の意義があってその次に新都市の規模、４番として移転反対の理由とあるんですけれども、移転反対の理由というのはどこが言っている理由なのかよくわからないので、資料の説明をお願いしたいと思います。","respondent":"小野（孝）政策担当課長","answer":"これは東京都が全体の事務局になっているということもありますけれども、東京都、２３区を含めて、こういう視点で反対をしているです。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"その張本人が権力を失って亡くなってしまいましたが、ほかのところへまた話が飛んでいったというような理解をしておりましたけれども、そういうレベルの話が一つとしてあるのは間違いない。少なくとも、東京都のパンフレットの中に多少書いてありますけれども、それがないと何だか感情論に、あるいは既得権益を守るだけの話になってしまうというような気がするんですけれども、どうですか。","respondent":"濱野助役","answer":"そういう論点を絡め合わせて、補強しながら構築していくべきかなということで、政経の場所一致だけでは論点としては弱いのかなという感じは持っております。","id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"政経の場所が一致しているということ、中央集権でなおかつ経済もひっくるめて圧倒的な一極であったということに対する反省というものが、一方で必要である。バブルの泡がしぼんでいるのを、だれを後始末をしなかったというだけの話になってしまうという気がしますので、そこのところを私のほうは留意したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"部長もおっしゃられた熱き思い、あるいはいろいろな形での部分を論理的に組み立てて反対運動を展開するということなんですが、ぜひそれをお願いしたいと思うんです。行政の立場に立ったときの質問なんですが、マイナスがいっぱいあるというのは認識していますが、行政面において首都が現在の都庁なり永田町から国会が離れてしまうことの弊害というのは、どういうふうに認識をされていらっしゃいますか。","respondent":"中尾根企画部長","answer":"単に弊害という部分ですけれども、今の日本の政治経済の構造の中で、実際上は首都ないしは地方という関係から見ると、それがほかのところに行ったら、ほかのところが首都圏の機能をやるとすると、東京が地方になったという関係ですけれど、本質的な問題とすれは。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"みずほの関係なんですけれども、一連のみずほの混乱がどうにかおさまっているというふうに聞いていますけれども、東京都は来週あたりに金融の検討委員会か調査委員会か開いて、指定金融機関も含めて検討するということを発表しているんだけれども、品川区としてはみずほに対して何をするべきかというか、何かするという考えがあるのかどうか聞かせてください。","respondent":"小野（弘）副収入役","answer":"支店のほうでは、やはり具体的な原因については把握している状況ではございませんので、ある程度落ち着いた状況になりましてから、もう一度臨時検査という形で、検査といいましても新銀行になってからのいろいろな処理の仕方。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それにみずほがどう対応してくるのかという問題もひきずっていると思うんです。だったら、やっぱり今日みずほの件に関しては、現段階までの報告をすべきだったと思うので、委員会に何を報告していくことが行政としての役目かというのを考えながら報告を尽くしていってほしいなと思うので、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"土井副委員長","kind":"意見","question":"この１年間、総務委員会の副委員長を務めさせていただきました。委員の皆さん、あるいは理事者の皆さん、また事務局の皆さんに大変なご理解とご協力をいただいて進めてこれたと思いますし、委員長の采配よろしきもございまして、あまり副委員長の出場所がなかったんじゃないかなということで、その意味で感謝を申し上げておきたいというふうに思います。そんな意味で、あいさつに代えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/891081?Template=document&Id=1580#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":12805,"voices":31}},{"id":"h14-20020527-8","meetingId":"h14-cm05","date":"2002年5月27日","dateIso":"2002-05-27","committee":"建設委員会","time":"午前１０時０４分～午後３時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"今の不動前駅の店舗の件なんですが、４事業者で一応合意をしたということであって、あそこの商店街だとかの基本的なベースの話はされたのかどうなのかということが一つと、それから全体の地下化が４年ほど延びるという話があったんですが、目黒駅から不動前のいわゆる高架部分ですね、これはかなりできているように思うんですが、そっちだけとりあえず生かすだとかという話はあるのかないのか。","respondent":"中島街路事業担当課長","answer":"説明不足で申しわけありません。店舗につきましては、こちらにつきましては、駅舎の中で東急で営業するものですから、こちらにつきましては事業者間で調整とかという性格のものではございませんので、東急として、こちらの駅舎の中に店舗を計画しているです。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"それはもうらち外で、これぐらいの規模ならいいよという話なら話でいいんですけれども、いかがなんでしょうか。","respondent":"中島街路事業担当課長","answer":"私どもは、正式に東急と地元の商店街の方とどこまで調整して合意を得ているかどうかというのはちょっと把握してございませんけれども、私どもとしては一定程度の話、公式、非公式はいろいろあると思うんですけれども。","id":"exchange-002"},{"speaker":"辻委員","kind":"質問","question":"この放置自転車の保管されることについて伺いますが、大体予定としてはいつごろ考えているのか。設立というんですか、要するに業務のことですね。それで、大体どのぐらいの予定台数。","respondent":"中島街路事業担当課長","answer":"放置自転車の今後の予定ですけれども、１４年度につきまして設計いたしまして、１５年度に整備着手ということで、１５年度中には完成させていきたい。来年度ですね。１５年度には完成させる予定です。","id":"exchange-003"},{"speaker":"辻委員","kind":"質問","question":"これは八潮にあるのと、八潮との比較で、あそこにもこういったものがあるんですね。大体方面としてはどちらの方向を予定しているのか。要するに２カ所になって、今までは全部品川区は一つにまとめてちゃんちゃんとなっているけれども、１カ所しかなかったので。今回、場所は二つになっているわけだから。今現在目黒駅がスタートしたんですけれども、状況としてはいかがですか。目黒駅周辺。","respondent":"中島街路事業担当課長、奈良交通安全担当課長","answer":"荏原の、それぞれ端端というんですか、品川区の端端ということですから、大体真ん中から荏原寄り、八潮に近いほうという形になると思いますけれども、線引きして。今、定期的に巡回をしておりますけれども、あった場合には八潮のほうに撤去しております。","id":"exchange-004"},{"speaker":"辻委員","kind":"質問・要望","question":"ですから、ある部分では回転がいいという点もあるわけだし、その辺で１,０００台も置くという場所もあるわけですので、その辺のキャパと、今後有料化を進めていく場合に五反田、あるいは目黒の場合はやっているわけですけれども、不動前のほうもこういう形で東急のほうもやるというわけですけれども、この辺のものが、今までは放置自転車、あるいはそういうのは持っていったけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"横山副委員長","kind":"質問・要望","question":"ここにずっと分けられていますＭ－２とかＭ－３を、ブロックブロックでそれぞれまだ利用の決まっていないところがあるわけですけれども、そこの部分については、もう要するに地元割り当ての１５％緑地で手当てされちゃっているんで、そこら辺の開発というか、今後の問題はみんな東急任せになって、品川区がそこにいただけるというか、品川区独自の敷地は求められないんでしょうか。","respondent":"中島街路事業担当課長","answer":"その使用料だとどこまで借りれるんだろうかというような状況ですので、全体のゾーニングがなかなか進まないという部分が要素として一つ大きなものがありますので、その辺、今後東急とも調整しながら、あるいは４事業間を。","id":"exchange-006"},{"speaker":"横山副委員長","kind":"質問","question":"一つには、保管場も品川区が一応２層式で管理しているところと、また東急のほうが、これは率先してというか、東急側のほうでそういった駅周辺の放置自転車対策というような形で不動前のところは事前にこうやって駐輪場を手当てされているんだけれども、それで、ほかの西小山、武蔵小山についても当然なされるべきだと思うんだけれども、そこら辺のニュアンスというか、現状はどんなものなのですか。","respondent":"中島街路事業担当課長","answer":"そういった部分では、こちらから東急に判断をゆだねるということではなく、品川区としてここをどの部分をどういう形で利用していく、活用していくかという主体性を持った形で計画は進めていきたいというふうに考えてありますけれども、ただ、その使用料との関係がありますので。","id":"exchange-007"},{"speaker":"辻委員","kind":"質問","question":"この印刷でいくと、この自転車の保管場所、これは高架下になるんだけれども、これは無料で借りるんですか。何かやっぱりこれは出すの。","respondent":"中島街路事業担当課長","answer":"有料です。こちらにつきましても現在、使用料について東急と協議をしています。","id":"exchange-008"},{"speaker":"辻委員","kind":"質問","question":"その辺金銭的に、今高架下の場合だと京浜急行なんかがあったよね。あの辺から見ると、やはり割高ですか。あの辺、あそこは大分縛りがあったりしているんですけれども、その割合からいくと、この１５％というのも先ほども話が出たけれども、同じで、あそこの部分のことについては、あそこも両方東急、池上線も東急だけど、その考え方について、値段的に高い。","respondent":"中島街路事業担当課長","answer":"基本的に高架下の部分につきましては、いわゆる公租公課が上部の３分の１ということになってあります。そういった意味では、私ども例えば使用料についても上部の３分の１ぐらいになるべきものというふうな考え方に立っていまして、そういったことも含めて調整しています。","id":"exchange-009"},{"speaker":"辻委員","kind":"意見","question":"高いと言っても、いや、だから路線は別として、こういう場合、金額的には別として。それで、実際そのために区間のところをえらい高いお金でという、そのほかのところで、１５％以外のところについては、それはそれで交渉があると思うんですけれども、その点については釈然としない部分があるんだけれども、もうちょっと、より詳しく。","respondent":"中島街路事業担当課長","answer":"そういった部分では、駐輪場を駅周辺に設置するのは、私どもとしても鉄道事業者の責務の一つというふうに考えてございまして、こういったことで、この間検討会の中でもいろいろ話をさせていただきまして、東急としても設置をすると。","id":"exchange-010"},{"speaker":"辻委員","kind":"質問・要望","question":"とにかく、この要するに上部利用に関しては、基本的には東急のほうで権利があるというのはわかるんですけれども、これはもう一つ事業者のほうから見れば、東京都、区全体から見れば先ほどお話があったように緑のラインとしてあるわけだし、要するにオープンスペースとしてあるわけですから、どういう利用を示したって、やはり地元住民から見ればプラスになる方向。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"横山副委員長","kind":"質問","question":"時間がないところ悪いんですけれども、ちょっとだけ聞かせてください。せっかくの機会ですから。","respondent":"中島街路事業担当課長、佐藤委員長、田平建築課長","answer":"それで、先ほど答弁させていただきましたけれども、これができまして、区内に２カ所設置場所ができるわけですので、そういった部分では。ほかになければ、本件を終了します。あるいは書面による説明をする。そういったものが書いてあります。品川区としては分別解体の届け出という部分で、早速５月３０日よりこの手順でいきます。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問","question":"簡単に説明だけ。このコンクリートの分別解体というのは何となくわかるんですけれども、再資源化にはなるんですか。なるとすればどんなものに。ちょっと教えてもらえませんか。","respondent":"田平建築課長","answer":"この木材も鉄も同様なことが言えるわけです。木材につきましても、やはり再利用ということがこれから国民自身が認識しなければならないことだなというふうに思っております。","id":"exchange-013"},{"speaker":"辻委員","kind":"意見","question":"この解体に伴って、今チャート図の中でいくと、ここに事前届け出が７日前ということになるけれども、その中の受注者の中の6)のところで現場における標識の掲示とかというのは、よく建築で解体するときにどうしているんだというのがあったわけですね。建築紛争の場合に。解体の場合は事前のときにいきなりがたがたやったり、そこでどうしていいのかというのがわからなかったんです。","respondent":"田平建築課長","answer":"そういうことが、委員がおっしゃる紛争の未然の解決というか、防止にも、この法律がそれなりの効果を果たすなというふうには思っております。","id":"exchange-014"},{"speaker":"辻委員","kind":"質問・要望","question":"これは、それが法的にどうだということは別問題で、ぜひこれはやっていただきたい。今までそういう意味ではやってしまって、後の建築の実質問題論議しか手が届かなかった部分がありますので、ぜひ有効に活用していただいて。その後も、いろいろ問題があれば、また別途意見をしなきゃいけないかなと思います。ぜひ。今日はそういう機会でございましたので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"横山副委員長","kind":"質問・要望","question":"表面の枠の中で、先ほどちょっと説明があったんですけれども、ここの中で指定建設資材廃棄物、これは木材ということで指定されているようだけれども、この字句の解釈がちょっとわからないので教えてほしいんですけれども、その後に「再資源化施設までの距離が遠いなど、経済性等の制約が大きい場合に、再資源化に代えて」、これは５０キロどうのこうのというのが裏面には出ていますけれども、縮減で足りる。","respondent":"田平建築課長","answer":"これは木材をリサイクルするまでの中間処理施設、ここは品川のところからいって、そこまで相当距離があるという場合につきましては、その廃棄物の用途、それから中間処理場までの距離を考察しまして、縮減で足りるというのは。","id":"exchange-016"},{"speaker":"横山副委員長","kind":"意見","question":"今委員長からお話がありましたように、今日が１年、皆さんと一緒に建設委員会に携わってきて最後ということであります。この１年、大変元気いっぱいな佐藤委員長のもとで、その補佐する役もなく、委員長のもとでしっかりと勉強させていただきました。はともあれ１年大変お世話になりまして、ほんとうにお礼を申し上げて終わらします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/923086?Template=document&Id=3720#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":16390,"voices":51}},{"id":"h14-20020531-6","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"区民委員会","time":"午後１時２１分～午後１時２９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/365953?Template=document&Id=2328#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":457,"voices":5}},{"id":"h14-20020531-7","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"厚生委員会","time":"午後１時２１分～午後１時２９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270319?Template=document&Id=3018#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":463,"voices":5}},{"id":"h14-20020531-8","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"建設委員会","time":"午後１時２１分～午後１時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/923086?Template=document&Id=3722#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":463,"voices":5}},{"id":"h14-20020531-9","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"文教委員会","time":"午後１時２１分～午後１時３５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/207072?Template=document&Id=4438#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":460,"voices":5}},{"id":"h14-20020531-13","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"清掃・リサイクル特別委員会","time":"午後１時４５分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/815229?Template=document&Id=5664#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":491,"voices":6}},{"id":"h14-20020531-5","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"総務委員会","time":"午後１時２２分～午後１時２８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/891081?Template=document&Id=1582#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":459,"voices":5}},{"id":"h14-20020531-14","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"行財政改革特別委員会","time":"午後１時４２分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/114679?Template=document&Id=5708#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":557,"voices":7}},{"id":"h14-20020531-16","meetingId":"h14-cm05","date":"2002年5月31日","dateIso":"2002-05-31","committee":"街づくり特別委員会","time":"午後１時４３分～午後１時５２分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/783739?Template=document&Id=6232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":555,"voices":7}},{"id":"h14-20020607-6","meetingId":"h14-cm06","date":"2002年6月7日","dateIso":"2002-06-07","committee":"区民委員会","time":"午後１時０５分～午後３時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は区民委員会が初めてなので、去年のあれが、議事録をちょっと読ませていただいたんですが、安全条例のところで、この安全のつどいというのは春、秋やっていたというふうなことで書いてあったと思うんですが、この安全のつどいというのと今回の区民のつどいというのは、安全条例を周知させるためにということで取り組むということで。","respondent":"長田地域活動課長","answer":"春につきましては、警察、防犯協会等が中心になってやっているわけですけれども、秋につきましては区と警察と交通安全協会、３者で共催をして実施をしていまして、共催ですので、区としても一定の負担をしている、こういう形で実施をしてきたものです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、今回の区民のつどいと、今までやっていた安全のつどいというのは質が違うものであって、今回のは安全条例の周知ということで１回限りで行われるものであって、この安全のつどいというのはこれからもずっと春秋行っていくということで考えていいんですねということと、あとこの安全のつどいというのはどれぐらいの規模でされていたのかということと、それと今回の区民のつどい。","respondent":"長田地域活動課長","answer":"今回区民のつどいのほうが１回限りかというようなことですけれども、今のところ、そのつもりでいるところです。ただ、今後のやり方につきましては、ある程度この安全のつどいとの内容が重複する部分も若干あります。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この安全条例については、この４月から施行されたわけですけれども、協議会について、前の議事録では５月ぐらいに第１回をやる予定というふうなことで書いてあったと思うんですが、協議会についての報告というのもぜひ、今日でないにしても、また改めて聞いておきたいなというふうに思うんですが、またその協議会の中身が随分論議になっていたと思いますので、その規則とかもあわせて委員会の中に。","respondent":"長田地域活動課長、南委員長、久保田防災課長","answer":"協議会につきましては、第１回、５月から６月ごろということで想定はしていたわけですけれども、第１回が今度の月曜日。今、鈴木委員のほうからも規則等々の資料として提出をという要請もあったと思うんですけれども、正副でちょっと先ほど打ち合わせをしまして。報告事項の２番目、平成１４年度風水害初動活動態勢訓練の実施結果についての説明をお願いいたします。訓練の内容としましてはご覧のとおりですけれども、この中で、５番目の図上演習訓練のほかに、６番目。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７番目のところで土のう製造・補充訓練ということで書かれているんですけれども、以前にかなりの水害があったときから比べると、土のうがかなりいろんな地域に増やされているんじゃないかと思うんですけれども、土のうがどこにどれくらい設置されているのかとかという、そういうのを書かれているような地図とかそういうものというのはつくられているのかどうか、ちょっとお聞きしたいんですが。","respondent":"久保田防災課長","answer":"土のうの担当というか所管は、道路公園課、まちづくり事業部ですが、まちづくり事業部ではそういうような資料等を持って、確実にあるところは把握しているわけですけれども、おおむね川の周辺、これは目黒川の護岸、右岸、左岸、その周辺。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"１４５人の方が集まったということ、１４５人ですね。時間的にはどうなんですか。参集率は出ていますけれども、この早い時間に、しかも抜き打ちというのは本当に抜き打ちで、全く知らなくて、防災課、指令を発するところ以外は知らなくて慌てて参集したというリアルな実態があるのかどうか、その辺ちょっと聞かせていただければと思うんですが。","respondent":"久保田防災課長","answer":"時間的な流れということからお話ししますと、まず４時半に雨が降ったという想定ですので、５時に招集の連絡をまず各職員にかけました。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"今年も６月と月が進んで、このぐらいになって、もう梅雨に入って、こういう状況が起き得る可能性もあるということですけれども、３日から７日を想定していて鋭く対応したという職員もおられるようですけど、局地的な雨というのがありますけれども、いずれにしても、目黒川、立会川は危ないなということをあらかじめ大体予想もつくわけですから、そういう意味では、今回抜き打ちとはいえ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"本田委員","kind":"意見","question":"先ほどちょっとお話があった立会川のＪＲ導水の関連なんですけれども、これは今の説明では下水道だから違うのかなとは思いますが、ＪＲ地下水を月見橋から５,０００ｔ毎日放水するんですね。７月７日から始めると先ほどご報告がありましたね。それで、これで見ると、立会川の水位計ナンバー９、これは月見橋のところだと思うんです。これは下水道側のほうだと思うんですね。それは連携はないのかどうか。","respondent":"久保田防災課長","answer":"今の件については私も深く説明をちょっと受けていなかったので、なかなかうまく報告できませんのですが、一つは当然そこの連携というのはやっていくというふうに考えております。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"私は、これが縦割り行政なのかなと思うんですが、東京都の下水道局と建設局ですか、これが違うからこういうふうにしないのかなと思ったりして、今報告を聞いていたんですけれどもね。それはどうなんですか。","respondent":"久保田防災課長","answer":"今のところにつきましてはかなり専門的な部分もありますので、後ほど私どものほうも所管のほうとよく聞いて、また再度お話しできる機会があればお話ししたいというふうに思っております。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"一方では雨が降ってあふれているのに水はとまらない、こういうことでは困りますので、ですから、こういう光ファイバーで自動的にそれぞれ操作されて、また状況も掌握できるという仕組みにしておくべきだというふうに思っておりますし、おおむねそういうふうになるとは聞いてはいるんですけれども、ここの立会川下水道幹線のところでは入っていないようですので、別枠でつくるのかなとは思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"今回どういう方なのかよくわかりませんが、先ほどの報告で一、二名増やすと。２名を予定しているけれども、一、二名増やすというのは大変いいことで、一、二名ではなく２名できませんかねというふうに、当然構成、その方の応募者の専門性というか、見識とか、そういう点から、ぜひこの人は入れてご意見を伺ったほうがいいという方もいるんだろうと思うんですよね。その辺はいかがでしょうか。","respondent":"金井環境課長","answer":"ただそうした中で、できるだけ増やしたいというのはそういう意味で、１名、増やしても２名程度が、現状ではちょっと厳しいかなという、それ以上はなかなか難しいかなというような気がいたしております。","id":"exchange-010"},{"speaker":"本田委員","kind":"意見","question":"そういう趣旨で、できれば予算の枠があるということではあるけれども、仮にオーバーしても、オーバーしたからといって、この種の問題については、それをあれする人もいないと思うんですよね。ぜひいい基本計画がつくられるように、多方面の見識ある区民公募の方もぜひ増やしていただけるようにお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、ここの中で地域団体で消費者というふうに書いてあるところでは、どういう団体が入るのかを一つ教えていただきたいと思います。それと、環境基本条例というのが東京都でもできていますし、２３区の中、あるいは都内でもつくられているところがあると思うんですけれども、その環境基本条例についての区としての考え方がどういうふうになっているのかについて、教えてください。","respondent":"金井環境課長","answer":"区としては、先ほど申し上げましたけれども、できるだけ理念、これからの地球環境問題も含めた環境問題については、区民、事業者、社会を構成するすべての人たちが実践をしていただく、そういう意味では、こういう基本計画。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大変なご苦労などで大分減っているという。ちなみにこれは金額的に言うとどのくらい。出ているかと思って、数字は違うかなと思って。もし出ていれば教えてください。","respondent":"宍戸ＩＳＯ担当課長","answer":"例えばＬＰＧは増えているんですけれども、その辺はちょっと増えている部分というのは集計していないとか、細かい部分はいろいろあるんですけれども、４,０００万円は超えるのではないかというふうに考えております。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"このようにせっかく皆さんから集めた税金から運用していたので、４,０００万円というのはかなり大きな金額であって、それだけ使える。すごく大きなＩＳＯの実績だと思いますので。大変なことはわかりますけれども、区の中の、皆さんの調整とご協力がかなりあるからこそできると思うので、これからも頑張っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのところで、やはり不燃のプラス９％になっているのが平成１５年度までにマイナス６％ということで、先ほど対策を検討しなければということでいろいろ検討したということでお話はあったんですが、ここのところで言うと、１５％今よりも減らしていかなくちゃいけないというふうなことになると思うんですが、具体的なところでは、これはどういうふうに庁内の不燃廃棄物を減らしていくというふうなところで。","respondent":"宍戸ＩＳＯ担当課長","answer":"その手始めといたしまして、ヤクルトの容器につきましては、今年の２月、３月ぐらいから集めていただいて回収しているというふうなことがあります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりごみになるようなものを使わない工夫というのが本当に必要だなというふうに思います。そういうところでは、これはリサイクルの問題にもなってくると思いますけれども、職員自身がやっぱりそういう観点でやっていくということと、対策そのものをいろいろなところから検討して、ぜひこの問題でも検討できるように頑張っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"キャンペーンはよくわかるんですけれども、ちょっとわかっていないというか、どうしたのかなというのが、例えばさっき言った環境関係の懇談会なんかやりますよね。例えば町会長がお見えになったとき、講師の方がお見えになったとき、やはりそういう背広の格好で来て、区の方たちはそういうときにどういう対応をするのかなと。ちょっとまずそれを教えてください。","respondent":"宍戸ＩＳＯ担当課長","answer":"そういったケースは多々あると思います。それらにつきましては、各所管を通じて、そういった主要メンバーの方に区の取り組みの趣旨等を説明してもらいまして、一緒に取り組んでいただくよう、まずは働きかけていただきたいというふうなことです。","id":"exchange-017","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問","question":"決して否定しているわけではないんだけれども、やっぱり例えば営業の方たち、表、夏場でも背広来て、ネクタイして、背広着て営業しているというのは、それだから、役所に入ったときにどう思うかなとちょっとそこら辺が。どこまで理解してもらうか。それともワイシャツ的な襟つきなのか、ポロシャツまで含んじゃうのか、そこら辺を教えてください。","respondent":"宍戸ＩＳＯ担当課長","answer":"区民の方が１０人中７人ぐらいまでが、これはちょっと遊びに行くんじゃないかというふうなポロシャツはやめてほしいというふうなことです。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"例えば外部のほうへ出ていったときに、これはやっぱり職員の方は中だけの問題で、例えばよく都のほうに行くとか、そういうときにはやはり普通の背広の姿になっちゃうんですか。このキャンペーンと言ったって、意識づけとしたら、ここでやっているんだったら、そっちに対しても品川区はやっているんだぞと見せるのかどうなのか。その辺を教えてください。","respondent":"宍戸ＩＳＯ担当課長","answer":"東京都その他外部に出るときの服装ですけれども、これは基本的にはこの中の２８度というふうなことではあるんですけれども、それぞれの判断の中で、徐々に、キャンペーンでもありますので。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/365953?Template=document&Id=2330#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":52818,"voices":127}},{"id":"h14-20020607-9","meetingId":"h14-cm06","date":"2002年6月7日","dateIso":"2002-06-07","committee":"文教委員会","time":"午後１時０４分～午後５時０９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高星委員","kind":"意見","question":"民主党区民連合の高星です。よろしくどうぞお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"学校改築の耐久年数というんですか、何というんですか、何年サイクルで見ていくのかというのと、全体の分布というんでしょうか、どんな状況になっているのか、台場小学校と荏原第五中学校という名前が挙がったんですけど、ここらは何年ぐらいに改築なのか、ちょっと全体像をもう少し詳しく教えてもらいたい。","respondent":"鷹倉庶務課長","answer":"だから、ローテーション、５０年が一つの目安なわけですけども、それ等を踏まえつつ、そういうものをいろいろ見ていきたいなというふうに思ってあります。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほどちょっと読んでいたんですけど、１７ページの「学校施設の改築に関する意識調査集計」、10)の冷房のところで、「冷房は温暖化等の環境問題からも必要ない」というのに対して、「必要ない」に「そう思う」という書き方なんですが、否定して、また否定して、ちょっとわかりづらいんですが、この中身を教えてもらえますか。これは校長先生に聞いたものですよね。","respondent":"鷹倉庶務課長","answer":"我々もその意識を調査するという形で、いろいろご見解を伺った上で、さらに先ほどの学校改築検討委員会の中で先生方の意見を伺ってあります。基本的に我々がクーラーを入れるか入れないかという問題につきましては、すべての建物が今クーラーが入っているわけです。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"私がその先に聞こうと思ったのを、先に答えられちゃった感じなんですが。私が今聞いたのは、この集計調査表はどういう意味なんですか。普通なら、「クーラーは必要だと思いますか」というのならいいんですけど、「クーラーが必要ない」と聞いて、「そう思う」というのは、ないということなのか、だから、そこをちょっと聞いた。","respondent":"鷹倉庶務課長","answer":"この設問の出し方そのものも、この検討委員会、校長先生、教頭先生が入った中で、設問を一つ一つ丹念につくり上げていきました。この問題の聞き方として、どういう形がふさわしいのかと。それで、十分検討した結果、こういう聞き方で聞こうと、こういう形になったものです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"どちらかといえば、「そう思わない」「どちらかといえば、つけてほしい」というのに２7.５％と読んでいいんですね。──わかりました。そしたら去年、別の、学校が３９度になったと記録しているんだなんていう状況ですから、ぜひ学校改築に当たってクーラー設置を基本としてやっていただきたいなというふうに思います。","respondent":"鷹倉庶務課長","answer":"台場小学校と、それから荏原第五中学校については、学校改築検討委員会の準備会といったものをやってあります。","id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"それを一つの形にしてこういう指針をつくられた。それがある程度まとまった段階でＰＴＡにおろしたり、地域におろしていこうというお考えなのか、最初からそういう人たちを組み入れた形で、この指針をつくり上げていくという発想にはならなかったんですか。","respondent":"鷹倉庶務課長","answer":"現に、この中間のまとめができた後、各、特に当該の学校ですね、予備的にちょっと行って説明している部分があるんですけども、やはり自分たち、ちょっとよくわかりにくいということがあります。というのは、今の従来ある学校、身近な学校、ここ何十年身近にあるわけですね。","id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"ただし、ここにもうたってあるとおり、各種生涯学習、あるいはまちづくり、あるいは地域社会として学校を使ってきたということだと、そういった指針の中にも、地域の方々なり、学校関係だけじゃなく、もう少し広い形の中で意見を聴取して、介護型施設としてはどういうものが適切なのかという意見もここに組み入れていっていただきたいなというふうに思うんですけれども、それは後がいいのか。","respondent":"鷹倉庶務課長","answer":"確かにそういうやり方もありますし、我々もそういうこともやるべきかなと考えたこともあります。ただ、実際この検討委員会、かなり回数を重ねていっております。時間的にもかなり長時間、１回やってあります、視察と。","id":"exchange-007"},{"speaker":"中島委員","kind":"質問","question":"１６ページにほかの市区に学校の視察が５校取り上げてあるんですが、これは各学校それぞれ特徴があると思うんですが、どういったところが特徴なのか教えてください。","respondent":"鷹倉庶務課長","answer":"それから横浜市の軽井沢中学校、これはバリアフリー化に対応した学校でございまして、昇降口に段差がないだけ、これだと当たり前なんですけど、各階段も、階段は当然なんですけど、スロープがかなり壁側といいますか、沿った形でとってございました。","id":"exchange-008"},{"speaker":"中島委員","kind":"質問","question":"それぞれいろんな特色があって、最近私も１校エコスクールのところを見てきたんですが、すべてを、それを品川区に取り入れるということは不可能だと思うんですけども、新しく改築するんであれば、いろんな検討が必要じゃないかなと思うんですね。ですけど、これにかわるような対策というのも検討するべきではないかと思うんですが、その辺はお考えでしょうか。","respondent":"鷹倉庶務課長","answer":"ちょっとグリーンぽいものなんですけども。そういうようなものをしていけば、一つの温度対策になるのかなと、こういうふうに考えてあります。","id":"exchange-009"},{"speaker":"中島委員","kind":"質問・要望","question":"確かにそうだと思います。今のはグリーンダストというものだと思うんですが、この前、私もこれは見てきました。それから、例えば教室のそばに木が１本あっただけでも随分温度が違うと思うんですね。その敷地の面積とか、いろんな状況があると思うんですが、ただ単に冷房ということではなくて、そのほかの対策とか、そういったものもこれから十分検討していただきたいなと、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田委員","kind":"確認","question":"確認なんですが、指針がお出になってということで、今検討委員会が１０回まで開かれて、この検討委員会は指針が出たということで、一度解散するということなのかということが第１点。","respondent":"鷹倉庶務課長","answer":"学校改築検討委員会が１０回持たれて、その後どうなっているのかという話ですが、結論的に言いますと、これは休会状態ということを考えてあります。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"一応この検討委員会は休会という形でいくと思うんですが、それはそれで結構なんですが、今度これが出て、台場小学校と荏原第五中学校でこの１年間の中でいろんな動きが出てくると思うんですが、そのときに、またさまざまな今度動きが変わったときに、これは計画的にやっていかれるわけでしょうから、それに伴う指針の中で変更せざるを得ないなと思うようなときは、休会ですから、すぐ招集をかけてやって。","respondent":"鷹倉庶務課長","answer":"この改築指針、確かに１０年ぐらいは見ているわけですけれども、その間に１０年を待たずして、改訂版的なものをつくる必要が生じてくるというようなことがあるとすれば、それは休会ですので、新たに検討して改訂版をつくっていくということが求められるのかなと思います。","id":"exchange-012"},{"speaker":"佐藤委員","kind":"質問・要望","question":"本件に関して、質問ではないんですが、先ほど課長からいろいろお話しいただいたんですけれども、課長自身も見て驚いたというようなお話をなさっていましたので、委員会のメンバーも改まりましたので、これに関連した視察を委員長のほうでできるだけ早い機会にひとつ設けていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鶴委員長","kind":"質問・要望","question":"ほかになければ、私のほうからちょっと確認の意味で言っておきたいんですが、この教育長の「はじめ」の言葉にもありますように、この学校改築計画指針は２１世紀の夢のある学校の方向性を示すものであって、この指針に基づいて快適な教育環境の総合的な充実を目指して、ユニークというか、特色ある学校づくりに努力していきたいということで、先ほどの庶務課長のご説明にもありましたように。","respondent":"鷹倉庶務課長","answer":"設計屋さんには、単に設計を引いてもらうだけじゃなくて、コンサルト的な立場でいろいろお手伝いしていただく必要があるのかなというふうに考えてあります。通常、一番嫌われていた絵というのは業者が決まって、かいて、はい、説明会。このパターンが一番よくないパターン。","id":"exchange-014"},{"speaker":"高星委員","kind":"質問・要望","question":"例えば、地方公務員法の適用職員であるのか、例えば、俗に言えば組合に入れる人なんですかとか、入れない人なんですかという、任務というのか、そういったところをちょっとわかりやすく教えていただきたいなというふうに思います。","respondent":"青木指導課長","answer":"１点目のリーダーですけれども、あえて申し上げるならば、教務主任とか生活指導主任とか、いわゆる主任級の立場の者をリーダーと言いがち、というか、そういうふうな形で受けとめて皆さんいらっしゃるかと思います。","id":"exchange-015"},{"speaker":"高星委員","kind":"質問","question":"そうすると、今の説明の中であった指導主任とか、教務主任という、主任制度がなくなっちゃうわけじゃないんですか。","respondent":"青木指導課長","answer":"これは主任制度の見直しですので、主任制度そのものを変えるわけではございません。教務主任や生活指導主任をこの主幹が兼務できるということになっております。","id":"exchange-016"},{"speaker":"高星委員","kind":"質問","question":"現実的に、一般の教員の状況把握とか、教員との意思疎通というのは、これまでに私が見ている限りでは、教頭先生で十分間に合うんじゃないかというような感じがするんだけど、いくら都のやることとは言いながら、品川区の学校はやっぱり品川区の学校で、私たちの身近に接するところなんだけども、そういう中で、品川区の場合は少なくとも教頭先生と、先ほど言われた指導主任なり教務主任なり。","respondent":"青木指導課長","answer":"現在の主任制度がどういうところに問題があるのかというようなところからこの検討は始まっておりますので、そこに現行主任制度の限界というようなことで、幾つか問題点が上がっております。","id":"exchange-017"},{"speaker":"高星委員","kind":"質問・要望","question":"東京都教育委員会が１年をかけて協議してこれを取りまとめてきたということが、品川の場合だと２回の教育委員会の中で決めてきた、こういう話があった。いずれにしても、１０月から１１月くらいに面接を行うということになるんですか。そういう形の中で、状況の変化等々においては、またこちらから聞くこともあるでしょうし、必要によっては教育委員会のほうからも再度ご説明をいただきたい。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"原委員","kind":"意見","question":"今の話にちょっとつながるんですが、この主幹制度で、教員の配置は各学校人数によっていろいろあるんでしょうけど、どういう形になりますか。","respondent":"青木指導課長","answer":"現在の教員の中から主幹を希望する者を位置づけますので、教員の人数というのは現在のところは変わるものではございません。主幹は授業を行うという立場にもありますので、人数的には今変わるということはございません。","id":"exchange-019"},{"speaker":"原委員","kind":"質問","question":"そうすると、主任が主幹になる場合もあるわけですよね。そうすると、今まである学校で主任がいて、その方々がいろいろ面倒を見ていらっしゃった部分がある。その人が、面接でもちろんいろいろとあると思う。主幹になって同じところにいる場合もあり得るわけですよ。ただ、主幹という責任上、いろいろな立場上のものの責任は負わさない、あるいは、それだけのものは持つということになるわけですか。","respondent":"青木指導課長","answer":"今、委員がおっしゃられた責任、権限というようなところが大きく変わってきますので、要するに仕事の中とか、教職員の中での位置づけというのは当然変わってきます。","id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"それと主幹という名前なんですけど、東京都が考えられたんだと思うんですけど、例えば品川区は、主幹という意味に対等する、もう少しやわらかい言葉で、それに補うとか、そういうことができるんですか。そうじゃなくて、これは上のほうからの押しつけで、品川区も主幹でやらなきゃだめだ。何となく主幹という感じが、どうもそぐわないかなというふうに思うんですがね。","respondent":"青木指導課長","answer":"今のところは主幹という名称で考えております。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問・要望","question":"校長がいて、教頭がいて、主幹は中学で３人と言いましたか。小学校で２人いて、そのほかに場合によると主任がいる。何か偉いのばっかり、偉いのと言ったらちょっと言い過ぎかもしれないですけど、何かそんな役職をたくさんつくってどうするのかなという気がするんですけれども、その辺はどうなんでしょうか。","respondent":"青木指導課長","answer":"そういう意味で、主幹ということを位置づけることによって、ほかの教員への指導力とか、それから組織の活性化だとか、スピーディーな課題解決だとか、そういうものができるというふうに考えております。","id":"exchange-022"},{"speaker":"沢田委員","kind":"意見","question":"標準規模の学校の教員と、それから今度の主幹制度を入れて、どんなあれなのかということと、それから、第二日野小学校なんていうのは７０名そこそこの学校で、主幹２人を新たに置くというのはどうも現実的じゃないんじゃないかなという気がするんですが、そこらの見解と、それから先ほどの給料表、今までは同じで、今度は違えるというニュアンスの話があったんですが。","respondent":"青木指導課長","answer":"それから２点目ですけれども、その主幹という職に対しての自覚というんですか、それからまた責任という意味で給料表が変わって、給料がほかの教員よりもアップするということは先ほど言ったとおりです。","id":"exchange-023"},{"speaker":"沢田委員","kind":"意見","question":"私、昔職場で働いていたときに、とにかく職制をたくさんつくるんですよ。５名ぐらいいると、班長だとか係長だとか、やたらと職制でないほうが少ないぐらいといったらオーバーですけど、そういうのをやって、やっぱりうまくいかなかった。今、また戻しています。一応意見として、それは述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"主幹というのは面接とか書類調査されるんですが、これはあくまでもその先生のされている、希望されている方ですね、推選ですか。","respondent":"青木指導課長","answer":"これは当然希望されている方です。","id":"exchange-025"},{"speaker":"中島委員","kind":"質問・要望","question":"確かに学校の中、いろんな学校を見せていただくと、人格者というんでしょうか、皆さんに慕われて、そしてリーダー的な、そんな方がいらっしゃるわけですけど、ここでもボトムアップということで、ほかの先生方の意見を聞いていくという、そういう役目も果たす、そういう人格者の中でも、管理職を望まない方っていらっしゃいますよね。","respondent":"青木指導課長","answer":"やはり、子どもから離れない、授業から離れないで、なおかつこうした校内の組織の中核になって働けると、そういう意味で二重の教師としての働きができるんではないかなというふうに考えております。","id":"exchange-026"},{"speaker":"中島委員","kind":"質問・要望","question":"いろんな、現在の教務主任とか、そういう方たちというのは、校長先生の推薦だと思うんですけど、いろんな面でその先生の力量とかを見てつけられているのかなと、外から見て感じているんですけども、そういった意味では、やはりこういった立場に立ってほしい人を推薦できるようなご配慮を要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田委員","kind":"質問・要望","question":"すみません。ちょっと私もわからないんで教えていただきたいんですが、面接で先ほど選任すると言ったんですが、これはだれが選任するんですか。","respondent":"青木指導課長","answer":"今の面接をということでお話はしましたが、当然書類審査だったり、それから抱負などを論文として書いてもらったりして、それを審査しながら面接をして行います。これは東京都教育委員会のほうで行いますので、東京都教育委員会が認めたということになります。","id":"exchange-028"},{"speaker":"石田委員","kind":"質問","question":"そうすると、これは区は全然係わらないで、希望した方が東京都教育委員会にご自分で出されて、そうすると、例えば主幹という資格をもらっていた方が、異動とかそういうときにお１人なのか、お２人なのか、３人なのかわかりませんが、その主幹の資格を持った方同士の異動ということは、そういう形になってしまって、品川区教育委員会が、そこについて、もちろん希望は出していくでしょうが。","respondent":"青木指導課長","answer":"東京都教育委員会に本区の事情とか、一人一人の主幹を希望された方に対しての内申というのは当然行いますので、区の事情、学校の事情を踏まえた形で、東京都教育委員会が主幹を選んでいくと、そういうシステムになるというふうに考えてよいかと思います。","id":"exchange-029"},{"speaker":"石田委員","kind":"質問","question":"そうすると、こういうことができて、主幹という人が地位もあって、いろいろ東京都教育委員会で決めてくるわけでしょうけど、そういう方を品川区もどうしても採らなくてはならないというのが、その人数を決めていく場合は、非常にちょっと解せないというか、何かせっかく品川区でいいことをしているのに、東京都教育委員会に振り回されちゃうんじゃないのかなと、何となく思っちゃうんだけど。","respondent":"青木指導課長","answer":"実際にこの選考に当たって、それからこれは６年、７年かかって完成させていくという時間のかかる作業でもありますので、当然その中で品川の今までの独自性というのを生かした形で話し合いを進めていきたいというふうに考えております。","id":"exchange-030"},{"speaker":"石田委員","kind":"質問・要望","question":"要望なんですが、議長会とかで、この前、人事権の問題とか、いろいろ要望を出したりして、東京都教育委員会とかに出されたりして、それがすべて勤務職員の者が異動されるかというと、そういうことはちょっと非常に難しいかもしれないけれども、権限をある程度移譲して、ある程度ちょっと自由にやらせてほしいよということは、例えばこれから議長会代行とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"沢田委員","kind":"意見","question":"ほかのところはストレスをなくすと言いながら、実際には地域の親御さんたちは学校選びをどうしたらいいかということを非常に不安に思っていることに対して、やっぱり明確に方向を示してほしいというふうに思うんですけれども、最初に言った地元の小学校を卒業すれば、一貫校で中学校の募集枠があるから入れるよと言えるのか、言えないのか、そこらをまずわかりやすく説明してほしいんです。","respondent":"富田教育改革担当課長","answer":"そういった意味で、ご心配の点があるということも把握しておりますので、そういったことを踏まえながら今後検討を進めてまいりたいと考えていますので、よろしくお願いいたします。","id":"exchange-032"},{"speaker":"沢田委員","kind":"質問・要望","question":"とりあえず今の問題を中心とした結論はいつまでに出す目標、例えば今年の秋だとかという、結論を出す目標があったら教えていただきたいということと、ちょっとあと具体的な問題ですけれども、この前、高星委員だったかな、予算特別委員会で質問して、現在の日野中学校のところと東洋製罐のところと、それから三井不動産が持っている用地を一体化してという話だったんですが。","respondent":"富田教育改革担当課長、鷹倉庶務課長","answer":"そういった形で、それでは一貫校のカリキュラム、完全な一貫であればこうだけれども、それでは中学校段階から学級が増えた場合には、どのような形でカリキュラム編成をしていくのか。今、日野中学校というお言葉がありましたけれども、第二日野小学校かと思いますが。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"問題は、今度入るお子さんの間でどこを選ぼうかというふうになっているわけで、今のＰＴＡの皆さんもそうなんですけど、やっぱりこれから入るお子さんあるいは同窓会の同窓生だとか、学校にまつわるいろんな形で地域、学校、家庭が協力を今までして学校をつくってきているわけですから、そういう人たちにも早くやっぱり説明をすべきだと、いずれにせよね。そう思いますけど、そこはいかがでしょうか。","respondent":"富田教育改革担当課長","answer":"今後学校に入るお子さんについてもいろいろ情報提供というようなことかと思いますけれども、先ほど申し上げました「開設準備ニュース」につきましても、大崎第一地区の町会等の回覧のほうをお願いするなどして、できるだけこれから入るお子さん方についての情報提供というのは。","id":"exchange-034"},{"speaker":"高星委員","kind":"質問","question":"幾つかお聞きしたいんですけど、今の沢田委員の途中から編入したりなんかすることに対してはというところの答弁のところで、たしか柔軟に対応する部分があるというような言い方をされたんだけど、これはどの程度柔軟にするのかということでちょっとお聞きしたいなと思った。これからずっと先、柔軟に対応するということであるのかどうなのかということをちょっとお聞きしたいなというふうに思います。","respondent":"富田教育改革担当課長","answer":"小中一貫校の学級数等につきましては、これから検討していく課題ですけれども、小中一貫校にふさわしい学級数というのはどの程度のものなのかということを別に検討はしてまいるわけですけれども、その中で、例えば小学校は各学年何学級で。","id":"exchange-035"},{"speaker":"高星委員","kind":"提案","question":"今のお答えも、今までにないような話なんで、実は私、この前１年間も文教委員をさせていただいたんで、いろいろ途中の経過があるものですから、今の課題は今の課題としてご説明を聞かせていただきたいというふうに思います。その辺のところが、今まで小学校は一切なくすようなことは考えていませんと言いつつも、その辺のところ、どうなの、もう一度確認の意味で聞きたいなというふうに思います。","respondent":"指田教育次長","answer":"同時に、そこを最初からなくそうかというならば、当然それだけのものの器をつくらなければいけないんでしょうけれども、学校選択制ですから、やはり、我々教育委員会としては、今の段階の中では、学校を統廃合する考えは持っていないということを。","id":"exchange-036"},{"speaker":"高星委員","kind":"質問","question":"だから、ほんとうに小中一貫の中で、先ほど言われたような途中でもって編入できないんだと、異動ができないんだというものを払拭して、違う、そういうことじゃないんだよというようなことであるならば、極端なことを言ったら、第一日野小学校でもいいんじゃないですかということになってきちゃうんだけど、第一日野小学校と日野中学校とという形になってきちゃうと思うんだけど、その辺は。","respondent":"鷹倉庶務課長","answer":"さっきも学校改築検討委員会でも言いましたけれども、建物が先じゃないんですね。どういう学校をつくりたいか、その中身の教育はどうするのか、そこをまず十分慎重に審議していただいた上で建物の形が決まってくるということで、ご理解いただきたい。","id":"exchange-037"},{"speaker":"高星委員","kind":"確認","question":"学校は決まっていないけど、場所は決まっているということなんですか、ちょっとそこを確認したい。","respondent":"鷹倉庶務課長","answer":"小中一貫校をつくると。小学校は、中学校はどうするのか。いろいろ検討した結果、学区域、第四日野小学校を包含する日野中学校を持ってくるのが適切だと、こういう判断のもとに提案を申し上げたです。","id":"exchange-038"},{"speaker":"高星委員","kind":"質問・要望","question":"なぜ第二日野小学校のところにありきなのかということが、よくわからない。先日、事務局会議がありました。そういう状況、ほんとうに教育委員会も地元にどんどん触覚を伸ばしていただいて、やっぱり地元の情報を、正しい情報をつかまえていただきたいなというふうに思っていますので、これは情報提供、あまり言っちゃいけないんだけど、情報とお願いということで、私はこの場では終わっておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"原委員","kind":"質問・要望","question":"そのときは、必ず文教委員会の中でご報告があって、それについて私たちは審議しなきゃいけない立場になるわけなんですけども、その時系列的なところの中で、どのぐらい詳しく出てくるかという話になると思うんですが、そこのところを、今後の話になりますから、今高星委員のほうも地域の意見を入れてくれとかといろいろな話があるわけですけれども、その中で。","respondent":"富田教育改革担当課長","answer":"先ほど、推進の組織図を配らせていただきましたけれども、各部会での個別で大切な課題は先々まで引きずる問題ですので、すぐ結論がまとまるということではございませんけれども、例えば学校規模ですとか、募集部分ですとか。","id":"exchange-040"},{"speaker":"原委員","kind":"質問・要望","question":"そうすると、先ほどの話ではないですが、一応タイムリミットは決められているわけですよ。その中で推進委員会なり準備委員会なりが開かれていきながら、一つ一つを明確に出していくと、こういう話ですから、そういう中で、決められたタイムリミットの中で、しっかりとした形をちゃんと出していただきたいというのが私たちの要望なんですが、それはできますよね。","respondent":"指田教育次長","answer":"当然のことながら、審議経過やなんかを含めて、それは中には決まったものですということで出す場合もあるかもわかりませんけれども、例えば、なるべくこまめに情報を提供し、また議会からのご意見もいだたきながら、準備委員会あるいはプラン２１推進委員会。","id":"exchange-041"},{"speaker":"原委員","kind":"質問・要望","question":"したがって、今回の報告事項の中では限界があると思うんですよ。ですから、その中で今いろいろ審議されていますけれど、あまり突っ込んで話をしても、答えが出てこない部分もたくさんあると思う。だから、そういう中で、委員長のほうでうまく裁量していただいて、お進みいただきたい。このように、議事進行まで言って申しわけないですけど、よろしくお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"原委員","kind":"意見","question":"しかも今の話だと、時系列的にこれから出てくるものがかなり量的にある。その中では、委員長がおっしゃった形の中で、次をどんどん進めていく必要があるし、深めていく必要があるとは思うんですけれども、その辺のところでご配慮いただければなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"上山副委員長","kind":"質問・要望","question":"そのときに、どういう形でスタートを考えられるのかな。私なんか、どう考えてもどうやったらそんなふうにしてスタートできるのかよくわからないんですけれども、一番最初の、初年度はどういうふうにスタートするつもりでいるのかなと思っているのが１点です。そこら辺の基本的なことをちょっと３点ばかり教えていただけませんでしょうか。","respondent":"富田教育改革担当課長","answer":"小中一貫校スタート時のイメージですけれども、一貫校としてスタートするのは、平成１８年度からですが、どの程度までできるかわかりませんけれども、ある程度の完全に１８年度から新しいカリキュラムでスタートするのか、あるいは研究開発学校の指定等を受けていますので。","id":"exchange-044"},{"speaker":"上山副委員長","kind":"質問・要望","question":"それで、ちょっとこれで終わりにいたしますけれども、今回の小中一貫校の関係でなんですけれども、例えばこの間、学校選択制などを導入するときは、かなりいろんな住民の皆さんからの要望だとか、かなりそういう声というんですか、世論調査という言葉が的確かどうかはわかりませんけれども、かなりそういう要望がありましたよね。なければないで構わないんですけど、そこら辺はどうだったんでしょうか。","respondent":"指田教育次長","answer":"こういうふうに考えております。","id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"これまでいろんな学校で説明をされていたと思うんです、この小中一貫校に対してのね。その説明に当たって、最初にどのようなお話をされて、ちょっと唐突な質問なんですが、どのようなお話をされて説明会に入られているんでしょうか。","respondent":"指田教育次長","answer":"これからそういうふうに学校規模をどうするんだということやなんかについても、いろいろ細かく検討してまいりたい。したがって、目指す学校という姿についても、どういう授業をやっていけば、この学校が目指す姿なんだろう。","id":"exchange-046"},{"speaker":"中島委員","kind":"質問・要望","question":"そうすると、さっきの上山副委員長のように、じゃあスタート時はどうするんですかというような、こういった、それがまだはっきりしていないとなると、何にも決まっていないのに、何を持ってくるんだ、こういった声になっていくんじゃないかなと思うんです。そうすることによって、ああ、これからしっかりやるんだなという体制で聞く姿勢ができてくると思うんです。","respondent":"指田教育次長","answer":"１８年、我々がいくらイメージを固めたとしても、今の学校教育法の中においては、小中一貫校ということが、要するに中高一貫は法的に認められていますけど、小中一貫というのは、やはり文部科学省のある程度の教育改革校という形のものがないと、いろんな形ができません。","id":"exchange-047"},{"speaker":"中島委員","kind":"質問・要望","question":"そこのところがなかなか説明会でも理解を得られない部分かなと思いますので、やはりそこの言い方とかを工夫をしていただきたいなと思うんです。これと私は分けて考えるべきではないかなと思うんですね。場所の問題となると、地形的な問題、それから街の問題とか、いろいろ出てきますので、これは街づくりとか、そういうところとのタイアップというのが必要だと思うんですが、いかがでしょうか。","respondent":"指田教育次長","answer":"したがって、ただ我々の中においては、やはりイメージ的に全く何にもないんだというわけにもいきませんので、やはりあそこの場所にというところが浮かび上がってまいりましたので、そういうことも踏まえて１８年のときにということを。","id":"exchange-048"},{"speaker":"中島委員","kind":"質問・要望","question":"今の質問は２点にわたって質問させていただいたわけですが、それぞれ分けて、ある程度はしっかり審議をする必要があるんじゃないかなと思うので、先ほど委員長が言われたように、いろんな項目を決めて、次の委員会でやっていきたいなと思います。これは要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"高星委員","kind":"質問","question":"研究開発校の指定を受けたというような説明があったと思うんだけど、富田教育担当課長、そこのところをちょっと説明してください。それで、私は文教委員を１年やったけど、教育指定の申請を出したということも聞いていないし、指定を受けたいというような話はあったけど、出したということも聞いていないし、決定を受けたのなら、その日程的なことを教えて。","respondent":"青木指導課長","answer":"その指定を受けることは確実になっていることは間違いない。それは文部科学省と東京都教育委員会と品川区教育委員会というような流れの中で、まだ指定書は届いておりませんけれども、指定書が間もなく届くであろうというところまでは確実になっております。","id":"exchange-050"},{"speaker":"高星委員","kind":"質問","question":"指定書というのは、これは場所の特定まで含むんですか、どうなんですか。","respondent":"青木指導課長","answer":"これは学校に対して指定があるわけです。学校と、それから東京都教育委員会、その所管の教育委員会ということで、東京都教育委員会とそれぞれの学校に対しての指定ということになります。","id":"exchange-051"},{"speaker":"高星委員","kind":"意見","question":"そうすると、日野中学校と第二日野小学校ということになっちゃって、イコール、場所的にはコンクリート、今中島委員のところで違うような話がありましたけど、それとはまた違う、場所的にはコンクリートされちゃう話になっちゃうのかどうなのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"高星委員","kind":"質問","question":"そういうことになってきますと、当然具体的な第二日野小学校の土地を取得するというような話も予算委員会の中で出ているわけですから、その辺の動きは、そのプロセスというのはどういうふうに動いているのか、ちょっとそこだけ聞いて終わりたいと思います。","respondent":"鷹倉庶務課長","answer":"したがって、来年実施設計ですので、おしりというのは、当然、開校は平成１８年度ということになってありますので、バックしていきますと、タイムリッミというのはおのずと決まってくるわけですけども、それまでには議会のほうにも具体的に提案していかなければならない。","id":"exchange-053"},{"speaker":"高星委員","kind":"質問","question":"要するに、買う土地を決めて、タイムスケジュールがあるから、もう出すよと言っているわけですよね、話の中身としては。まとめますと言っているわけですから。そうすると、どのくらいの来年の実施設計に向けて、どのくらいの、例えば何月ぐらいには土地も買うんだというようなことも出てくるわけでしょう。その辺の動きはどうなの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"石田委員","kind":"確認","question":"日程だけ、ちょっと確認をします。先ほど中島委員が言った中で、話がごっちゃになっている、分けようとかと言っていらっしゃるけれども、先ほど次長がおっしゃった答弁、もう一度、再度確認をしたいんだけれども、学校が自由選択制をとったという形の中で、この新しい小中一貫校という学校は、特色ある学校づくりというか、各学校、いろいろなところで特色があるわけですよね。だから、それに対する答弁。","respondent":"指田教育次長","answer":"今、石田委員から言われましたように、特色ある学校づくりのメニューの一貫であるということは明確であります。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/207072?Template=document&Id=4440#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":77612,"voices":171}},{"id":"h14-20020610-7","meetingId":"h14-cm06","date":"2002年6月10日","dateIso":"2002-06-10","committee":"厚生委員会","time":"午後１時０４分～午後４時５０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"築舘委員","kind":"意見","question":"７５ページの、家庭福祉員制度の保育ママのことですけれども、これは１名ということですが、実績といいますか、今の状況、これは時給幾らというか、その辺の内容の説明をもうちょっとお願いしたいと思います。それから、１１２ページの、社会福祉協議会ですけれども、理事会が１５名でなっているということで、これはどういうメンバーがなっているのか。","respondent":"高橋福祉事業部副参事、金子保育課長","answer":"私のほうから、理事会のメンバーと、派遣職員のことで説明をします。実績ですが、今手元に出てこないんですけれども、たしか年度の前半はゼロでございました。年度の後半で３人入っていましたので、１年間で２０人程度の実績というふうに考えているところです。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺いたいんですけれども、保育園のところで、先ほど未認可保育園の件で説明があったんですけれども、未認可保育園が数としてはちょっと減ってきているようです。認証保育所のほうが増えていると。そういう関係だったかと思うんですけれども、。その関係と、認証保育所との関係というのがどういうふうになっているのかお伺いしたいと思います。","respondent":"金子保育課長","answer":"この問題につきまして東京都でも行く行くは保育室の助成をやめて、認証保育所のＢ型に全部収れんしていくんだというふうな話はお伺いしておりまして、ただ、いつの時点でそれを実施するかというところが、東京都も明らかにしていないところです。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"今の未認可は認証保育所への移行を進めていくという基本方針だということでいいんですか。そこのところをもう一回お願いします。","respondent":"金子保育課長","answer":"今申し上げましたとおり、保育室については、今後東京都のほうで助成を打ち切るという考え方を聞いておりますので、私どもがすべて東京都の部分もかぶって助成していくという考えは持ってございませんので、レベルアップされている認証保育所へのＢ型への移行というのは。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"要するに、一般的に未認可がなくなって、新たにＢ型が増えていくというふうに考えているのか、それとも、今未認可があるのがＢ型に移行していくということを援助していくのか、そこら辺のところをどういうふうにお考えなのか、お伺いしたいと思います。","respondent":"金子保育課長","answer":"質問のお答えになっているかどうかわからないところがありますが、私どもとしては、先ほど申し上げましたとおり、認証保育所というのが認可に準じた一定のレベルを設定しておりますので。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"例えば都営住宅、あるいは区営住宅に住んでいる方と、基準からいくと、アパートに住んでいる方は風呂なしになってしまうかなと思うんですけれども、そこら辺のところで入浴券というのがどういうふうに位置付けられるのか、そこら辺の考え方がどういうふうになっているのか、ちょっとお伺いしたいと思います。","respondent":"黒田生活福祉課長","answer":"入浴券につきましても、平成１２年度が８０枚ということで、今２３区平均が６０枚になってありますけれども、激変緩和ということで、今年度に６０枚ということで、２３区並みになってきたですので、これがそのままずっと維持するかというよりは。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"さっき質問をした中で、例えば区営住宅、都営住宅ですと、大体風呂がついているのが多いんですけれども、アパートだと、今の基準からいくと、現実問題は風呂なしという感じになってしまうと思うんです。その関係で入浴券がどういうふうな位置付けで考えられているのかというのを聞いたんです。","respondent":"黒田生活福祉課長、横山委員長、新美保健高齢事業部長、田中健康課長、早津高齢福祉課長","answer":"ということもありまして、あくまでも最低生活の水準を維持するですので、お風呂があるか、ないかというのが、そういう中身になるのか。ほかにないようですので、福祉事業部の事務事業概要を終了いたします。次に、保健高齢事業部について一括説明を受けてまいります。保健所が５３名、保健センターが７１名、総計２６３名の体制です。各事務事業については、健康課長以下それぞれの課長でご説明をします。","id":"exchange-006"},{"speaker":"山路委員","kind":"質問・要望","question":"２点目は、５４ページ、高齢事業につきまして、シルバーセンターの運営の中で、マッサージサービスをやられている内容ですけれども、このマッサージサービスは専門の方が来てやられているのか、どういう形で受け入れられているのか、これについてお伺いをいたします。品川区はこの件について検討をされたことがあるかどうか、その３点についてお伺いいたします。","respondent":"早津高齢福祉課長、蓼沼高齢事業課長","answer":"高齢化率ですが、全国ベースになりますと、直近のものがございませんで、平成１１年度で１７.０％です。東品川シルバーセンターにおきましては毎週火曜日、その他のシルバーセンターにつきましては月１回というペースで実施をしています。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問・要望","question":"この３年間のうちに相当変わってきているんじゃないかと思うんです。その辺よろしくお願い申し上げます。そういう方たちが実際にできるか、ボランティアだったらできるか、お金を取るということになったら、どういうふうになるのか、その辺の見解をお聞かせいただきたいと思います。","respondent":"新美保健高齢事業部長","answer":"シルバーセンターでマッサージという形のサービスをやっているのは、先ほど申し上げましたように、センター開設時からの視覚障害者団体との協力関係ということがありますので、その他の方々のシルバーセンターのサービスとして整体とか、その他のこともやるかどうかは。","id":"exchange-008"},{"speaker":"築舘委員","kind":"質問","question":"福祉人材の育成拠点ですから、逆にこちらから、この人をひとつ育成したいみたいな、そんなことができているのかなという、逆指名じゃないんですけれども、そういう部分があるのかどうかということをお聞きしたいと思います。","respondent":"田中健康課長、早津高齢福祉課長","answer":"公募委員を５名お願いをしておりますが、年齢的にも、３０歳からの方で構成して、幅広い層に受け入れていただけるような実践的なものをつくりたいということで考えてあります。それはケアマネージャーコースで、ヘルパーにつきましては、しているところと、していないところもあるかもしれません。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"何点か聞きたいんですけれども、まず、高齢者のほうの２８ページのところで、特別養護老人ホームのことを聞きたいんですけれども、この表を見ていてもよくわからないので教えてほしいんですけれども、今時点で特別養護老人ホームの待機者の数が何人というふうになっているのか、そこのところがまず１点。","respondent":"早津高齢福祉課長","answer":"これが４５８名です。入所開始というものは、平成１３年度１年間で入所された方の人数が２０９名です。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"確認","question":"確認ですけれども、ここに書いてある４５８人というのは、取り下げの１５１人を引いた数だということですね。そうすると、いろいろな事情があって取り下げになったんだけれども、本人のほうの当初申し込んでいたのは４５８人足す１５１人ということになるわけですか。","respondent":"早津高齢福祉課長","answer":"言うまでもございませんけれども、例えば家族が死亡されたとか、介護する人がいなくなったりしたような場合には、別途緊急の入所措置を行ってありますので、必要な対応はできているというふうに考えてあります。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"現実に施設の数がありますから、優先順位をつけていくというのも、これはある意味しようがないところがあると思うんですけれども、無理だという、そこのところの判断というのは、どこで、どういうふうに、どんな基準でやるのかというところを教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"特別養護老人ホームの入所の判定に当たっては、要介護度、それからご本人の年齢という、ご本人の状況のほかに、家族の状況がどんなであるかということも調査をいたしまして、例えば高齢の方が介護をしているという老々介護の場合ですと、それについての一定の加算。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そこをどういうふうな運用でやっているのか、どこでどういうふうな判断をしているのか。もう一つ、今度は介護保険の見直しになるわけですけれども、３１ページのところで、推進委員会を５回ぐらいやっていって、ここで審議していくんだというお話があったんですけれども、もうちょっと詳しく、いつ頃にどういうふうな内容を決めていくかというのが分かったら教えていただきたいと思います。","respondent":"早津高齢福祉課長、高橋介護保険担当課長","answer":"会議のメンバーは、民生委員の代表者が１人、両医師会から医師の代表が２人、特別養護老人ホームの施設長の代表者が２人、在宅を承知しております支援センターの代表者が２人というメンバーで構成をしております。今お尋ねの制度推進委員会のことですが、今年度は５回ほど予定しているという中で、今５月が終わりまして、７月、９月、その中で、平成１４年度で３年目ですけれども、今までの介護保険推進委員会でやられたことを検証しながら出して。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問・要望","question":"１０ページのケアプランのところで表が出ていたので、併せてお聞きしたいんですけれども、在宅介護支援センターを新たに２カ所増やすということですけれども、私ども以前から一人当たりのケアプランの作成というのが多過ぎるんじゃないかというふうに思っていたんですけれども、ここら辺の一人当たりのケアマネージャー、ケアプランの作成件数が今どうなっていて。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"各法人、支援センターの事業者が増員をしておりまして、今８０人強の人数がケアマネージャーとして従事しておりまして、８０人のケアマネージャーが４,０００件強ぐらいのケアプランを作成しておりますので。１１月は来期の介護サービス量の見込みもある程度は立てないと予算編成等々できませんので、その辺までを１１月までに検討委員会の中で一通りご議論をいただきまして、２月には来期のテーマ、課題。","id":"exchange-014"},{"speaker":"須藤委員","kind":"意見","question":"１６ページの訪問リハビリテーションのところですが、どのくらいのメンバーが対象になっていらっしゃるのか。それから、そこに「理学療法士等」が入っているんですけれども、「等」というのはどういう人を含んでいるのか。それから、５１ページの高齢者クラブの指導者研修会が平成１４年度から連合会の主催事業になったということですが、これはどういう理由なのか。","respondent":"早津高齢福祉課長、蓼沼高齢事業課長","answer":"６０ページの、やさしいまちづくりの今後ですけれども、これにつきましては、各鉄道事業者と協議をしながら、条件の整ったところからまた進めていくというものです。高齢者クラブ指導者研修会につきましては、従来からあります予算額と同額のものを補助する形で品川区高齢者クラブ連合会の主催事業とするというものです。","id":"exchange-015","title":"議員研修会の内容と所要時間"},{"speaker":"宮崎委員","kind":"質問","question":"５８ページの高齢者借上げ住宅のところで、先ほど訂正で、平成１３年、平成１２年、平成１１年の実績が全部０というふうになっていたんですけれども、ずっと０かなと思うんですけれども、最後の実績があったのはいつ頃なのか、そこのところをお伺いしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"平成８年度が実績としては最後になってあります。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今の借り入れですけれども、高齢者住宅借上げ型で、つくる方のほうからも、いろいろ借りにくいというか、使いづらいというか、要望と制度が合っていないのかなという感じがするところがあるんですけれども、それはそれとしてあるかと思うんですけれども、もう一つ、住宅マスタープランとの関係で基本的な考え方だけ伺っておきたいんですけれども、住宅マスタープランのところでは。","respondent":"蓼沼高齢事業課長","answer":"基本的には現在設置しております２２０戸を活用していくということで考えてございまして、もう一つの住宅あっ旋制度がありますけれども、こちらのほうの活性化をして、今後住宅運営を進めていきたいというふうに考えてあります。","id":"exchange-017"},{"speaker":"辻副委員長","kind":"確認","question":"これはどうなっているのか。もう一つは、Ｃ型肝炎の検査というのがあるんですが、この辺が今後保健所のほうで、希望する方で、輸血などを受けた方に対する、あの辺について今新しい年度としての事業になっているのかなと思うんですけれども、どういう体制で進まれているのか、ちょっと確認しておきたいと思います。","respondent":"田中健康課長、小林品川区保健所保健サービス課長","answer":"Ｃ型肝炎のほうの検査ですが、現在実施に向けて検討中ですけれども、今回区民健診の中に取り込んでという厚生労働省のほうの枠組みの指示の中で４月から実施を目指して、現在検討の詰めに入っているところです。そのほか学校のほうで、小学校１年生、２年生、中学校１年生、２年生で追加のＢＣＧを行っておりますけれども、４歳までに行うＢＣＧは効果があるけれども、追加で小学生。","id":"exchange-018"},{"speaker":"辻副委員長","kind":"質問","question":"もうちょっと少ないかなと思っていたんですが、分かりました。もう一つ、数のほうで、１１ページの薬事衛生の許可というところですけれども、これも最近ドラッグストアという薬局が物凄く目につくようになりました。これも全部ここで言う許可、登録というのが入ってしまうことなんですか。毒・劇物の販売業に関しては、これはどういうものを扱っているのでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"毒・劇物ですけれども、それを取り扱っている店がありまして、例えばアジカナトリウムとか、砒素とか、こういうものを取り扱っているところにつきましては、届出をしてもらうということです。ドラッグストアの定義ですが、大きいドラッグストアは区のほうの許可に入ります。","id":"exchange-019"}]},{"id":"topic-02","title":"続きまして、報告事項の(1)「品川区地域福祉計画」の策定","agenda":"続きまして、報告事項の(1)「品川区地域福祉計画」の策定","exchanges":[{"speaker":"金高委員","kind":"質問・要望","question":"裏面の構成ですけれども、ＮＰＯ１名となっておりますけれども、実際に品川区内で福祉・医療関係団体のＮＰＯというのはどういう団体が、何団体ぐらいあるか、その辺のところを教えていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"私どもは今回計画の策定ですので、当然のことながら、それ相応の実績を持っている団体にご参画をいただくということで考えております。","id":"exchange-020"},{"speaker":"金高委員","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと伺いたいんですけれども、裏面のところで、障害者団体７団体協議会となっているんですが、ここで７団体で１名というのは、ちょっと少ないんじゃないかなという感じがするんです。そうなると、精神障害者の方の意見というのがどういうふうに反映されるのかというところが心配なんですけれども、そこのところはどうなんでしょうか。","respondent":"日下部障害者福祉課長","answer":"委員会の構成ですけれども、実は私ども事務局ということで、この委員会の構成を具体的に検討するにあたって相当悩みました。地域福祉計画ですから、これは申し上げるまでもなく、できるだけ幅広くご参加をいただくということが前提です。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"それと、これは公開ですよね。今いろいろ公開してきているんですけれども、そういうところの委員会の公開はどういうふうに考えているのか、そこのところも併せてお願いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"ということで、私どもは実際には７月開催ということで考えておりますので、具体的に公開するかどうかということも含めて、その辺の具体策については、今後詰めてまいりたいと考えております。","id":"exchange-023"},{"speaker":"築舘委員","kind":"質問","question":"品川区地域福祉計画についてということですけれども、社会福祉協議会がやっているふれあいサポート計画ですか、地域福祉区民活動計画というのがありますね。それとの整合性というか、どういうところが違うのかということ。それと、障害者福祉がやっているということですから、そういうことの理解での地域福祉だというふうに解釈しているんですけれども、それでよろしいのかどうか。","respondent":"日下部障害者福祉課長","answer":"この計画との関係ですけれども、基本的には、国なり東京都が考えておりますのは、実際には三相の計画ということで、今回地域福祉計画をつくりますけれども、これは行政と住民がどうやって一緒になって地域の福祉を進めていくか、行政がつくる計画です。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"事務事業概要の説明のときに、支援費制度というのが出てきたんです。地域福祉計画は、この支援費制度を受けての計画になるんですか。そこの関係がどうなのか。","respondent":"日下部障害者福祉課長","answer":"ですから、個別障害者福祉の支援費制度について、あれやこれやということではございませんけれども、当然のことながら、その辺の中身もある程度反映した中身になっておるです。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"感想になってしまうんですが、支援費制度については、国のほうではまだ具体的な中身が出てきていないんですけれども、そこで年４回程度の委員会だというふうになっていますけれども、国のほうがいつどんな中身のはっきりしたのが出てくるのかよくわからないんですけれども、年４回で、大分大きな変更になるわけですよね。そのところがちょっと心配なんですけれども、どんなものでしょうか。","respondent":"日下部障害者福祉課長、小沼福祉事業部長","answer":"いろいろご心配いただいておりますけれども、ただ、品川区の場合は福祉については、品川の福祉というふうに言われておりますように、これまでのいろいろな実績もありますし、地域福祉そのものについても。聞くところによりますと、７月中ぐらいを目処に何らかのものを国としては出したいというようなことですので、この点についてもまた遅れないような形で、以後の委員会等で適切、適宜にご報告をさせていただければと考えています。","id":"exchange-026"}]},{"id":"topic-03","title":"報告の２番目、食品香料会社（本社・品川区）への調査","agenda":"報告の２番目、食品香料会社（本社・品川区）への調査","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"保育園のところで、満足度調査というのをやったというふうにちらっと聞いたんですけれども、やっていたのかどうなのか。やっていたら、報告をお願いしたいなと思っているんですけれども、そこら辺のところはどうでしょうか。","respondent":"金子保育課長","answer":"委員お尋ねの件につきましては、昨年の１２月に実施しました第三者評価のうちの利用者満足度調査の件だろうと考えておりますが、この件につきましては、現在調査結果をまとめて、委員会に提出するように準備作業中ですので。","id":"exchange-027"},{"speaker":"横山委員長","kind":"質問・要望","question":"その他については終了しますけれども、議長のほうからも言われておりまして、委員会運営について、今までここに報告事項ということで、されるばかりでなくて、委員会からも報告を求めていくような、そういった活発なる委員会にしてほしいという要望も出ておりますので、今後委員会の終わりにそれぞれからそういったご要望があるかないかお尋ねしていきたいと、そんなことも思っておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/270319?Template=document&Id=3020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":59726,"voices":147}},{"id":"h14-20020610-8","meetingId":"h14-cm06","date":"2002年6月10日","dateIso":"2002-06-10","committee":"建設委員会","time":"午後１時０６分～午後４時３０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本間委員","kind":"意見","question":"民主党区民連合の本間隆です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"２の事務事業概要","agenda":"２の事務事業概要","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"同じく、管理工事課の一番最後のページに、駐車場整備基金というのが出ていますけど、これ、先ほど時間貸しの駐車場ですとかを中心にしてということでしたけれども、これ、よくある「タイム２４」とか、ああいう駐車場のことを言っているのか、それとも、また別の形なのか、ちょっとここだけ教えていただきたいと思います。","respondent":"岩田管理工事課長、奈良交通安全担当課長","answer":"払い下げを受けない方につきましては、きちっとした占用手続をとっていただいて、適正に利用していただくということを順次進めてまいります。駐車場整備基金に関する融資の関係ですけども、これは、いわゆる路上駐車を排除して交通の円滑化を図ろうかということで、一応条件はありますけども、例えば、広さが３００平米、あるいは駐車台数が２０台以上の。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"これはちょっとあれですけど。駐車場のほうなんですけれども、企業として、今のお話を聞くと、当然企業として利益を得るということなんですよね。国の制度なのか都の制度なのかはよくわかりませんけれども、この制度が出てきた背景みたいなのがわかりましたら教えていただければと。","respondent":"岩田管理工事課長","answer":"ただ、昨今、景気がこういうふうになりまして、それほどの需要というのが、当時から比べればぐっと減ってまいりまして、今後については、こういった駐車場基金がこのままのやり方で効果があるかどうかというのは、今。","id":"exchange-003"},{"speaker":"堺委員","kind":"質問・要望","question":"ちょっと２点ほど確認をさせていただきたいんですけども、１点目は、３６ページの西品川公園雨水調整池整備工事の件で、私、先ほど、排水管の敷設工事が終わって、この関係については、６月に完成ですか、で、今度１１月ごろまでには現状復旧というんですかね、公園として利用していきたいという。順調に工事が進んでいるやにご説明いただいたかと思うんですが、その辺のことを確認しておきます。","respondent":"中谷まちづくり事業部長、田村住宅課長","answer":"本事業につきましては、設計ができたところから順次発注するということで、緊急整備を要するということで、かなり基礎調査、あるいは設計をしながら工事を発注していったいきさつがございまして、当初の予定ですと。ということで、それの有効活用が図れるのではないかと、宅建側のほうも検討していまして、区のほうも、やはり効率的な管理運営ということを考えますと、何かそういう手だてがないかということで協議を重ねてきたということで、今回。","id":"exchange-004"},{"speaker":"堺委員","kind":"質問","question":"今、ご説明いただいたように、戸越センターですか、あの警備会社、新しく、会社の名前、区民住宅の空き家の相談は、募集の要項の下のほうに、相談や何かも受け付けますというふうに書いてありますよね。そこのところですか、これは。","respondent":"田村住宅課長","answer":"申し込みのしおりに、問い合わせ先にも株式会社品川宅建管理センターということで、これが、先ほど申し上げた新会社です。","id":"exchange-005"},{"speaker":"堺委員","kind":"質問","question":"そうすると、民間の会社ですから、区のほうからの、今まで区がやっていた業務をそこに委託すると。その辺のことはどうなっているんですか。","respondent":"田村住宅課長","answer":"ただし、その団体の設立のための出資金だとか、そういうものは、一切区のほうからは出しておりません。独自に宅建品川支部のほうで、株式会社にする資本金で、そちらの独自の財源で会社を設立したというふうに聞いております。","id":"exchange-006"},{"speaker":"堺委員","kind":"質問","question":"そうすると、今後、仕組みというんですかね、品川区があって、従来、株式会社品川都市整備公社というのがある。そこに新たに宅建業者が新しい会社をつくったということですがね、さっき説明あったのかもしれませんけど、ちょっと聞き漏らしていたらごめんなさい。品川都市整備公社と宅建業者、新しくつくった会社との設立になるんですか。その辺の関係説明はどういうふうになってくるんですか。","respondent":"田村住宅課長","answer":"現在の地方自治法では、品川区がやっている公の施設の管理すべてについて、直接、例えばここで言っております品川宅建管理センターに委託することは法律上できません。地方自治法上できません。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"わかりました。そうすると、本年度よりすべての区民住宅の入居者管理と借り上げ等の一部の住宅を除いてそこにお任せするという表現になっているんですけど、そうすると、区営住宅は委託しないんですか。区営住宅は従来どおり住宅課のほうでやっていくということになるんですか。その辺はどういうふうに。","respondent":"田村住宅課長","answer":"実は、区民住宅以外にも、区営住宅も一時俎上に上げて、区営住宅についてもというお話をしたんですが、当面、区民住宅のほうを先行してやらせてほしいということで、実際に区営住宅については、直営で今までどおり実施するという形になります。","id":"exchange-008"},{"speaker":"堺委員","kind":"意見","question":"今、言葉じりをとらえるわけじゃありませんけど、課長の答弁で、「当面」という表現を使ったんですが、時期が来て状況が許されれば、区民住宅だけでしたけども、区営住宅もその宅建に管理を委託していきますよと。だけど、まだそれはいかないので区営住宅はこちらでやるんだという、さっき「当面」と言っていた。こうおっしゃったので。","respondent":"田村住宅課長","answer":"「当面」と言ったのは、公の施設という意味では、区民住宅と区営住宅とは同じ扱いになりますので、区民住宅が委託できて区営住宅ができないというような法律的な解釈ではないということで……。","id":"exchange-009"},{"speaker":"堺委員","kind":"確認","question":"わかりました。やっぱり、せっかくこういうシステムをつくった、いろんな制約があるのでそれをやるわけにはいかないかとは思いますけどね、こういうことについては、やはりそういう民間活力というんですかね、そちらのほうに形づけれるようになっていけばいいなと。それを確認の意味でお尋ねいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"夜寝られないことがあったと、何か５月に周辺で、うちは夜中の工事がうるさかったという声を聞いていますので、今後の予定なんかもお聞かせいただきたいと思います。ここに載っている予算は用地買収の予算なんでしょうか。今後の予定とか地元の説明会だとか、わかっていたら教えていただきたいと思います。","respondent":"中谷まちづくり事業部長、岩田管理工事課長","answer":"私のほうから、１点目の、品川公園の調整池関係の工事の今後の予定ですが、先ほど、道路公園課長からご説明しましたとおり、配水管工事等につきましてはほぼ終わりまして、現在、Ｌ型側溝、あるいは横断側溝。通常は、ある程度の設計が終わってから住民に入るんですが、ここの場合は、町会長を中心に、議会に、公園等にするために区で買収をしてほしいという請願が採択されている経緯がありますが、一部近隣マンションから。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"雨水調整池の問題は、本当にりんかい線のこととかいろいろあるんで、かなり夜には敏感なんで、その辺、十分、声を聞いて、工事を進めて、本当に集中豪雨の折に、また水害が起こらないように、地域では本当に喜ばれる工事なんで、作業を進めていただきたいと思うのと、西霧ヶ谷公園のあたりも、本当に、町会の皆さんは本当に場所があったら公園にしてほしいと、本当に常々思っているんで、願いなんだけど、今。","respondent":"松代道路公園課長","answer":"ただ、順次ずっとやっておるところですけども、日々成長していますので、陳情等があれば、その陳情等に合わせて対応してまいるというようなこともとってあります。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと済みません、忘れていました。マンションの基礎調査のほうなんですけれども、先ほど、これからちょっと調査を行ってどういう支援ができるかというのを考えていくということだったんですけれども、調査項目ですとか、いつごろからやるとかというのは、ある程度固まっているのかと思うんですけども、その辺を少し教えていただければと思います。","respondent":"田村住宅課長","answer":"７月早々に内容等調査し、年度内にまとめるということでやっていきたいと思います。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"東急目黒線の立体交差事業のところなんですけども、私、予算特別委員会のときにちょっと質問させていただいたんですが、街づくり特別委員会とこっちのほうの関係がよくわからないんですが、その後の進捗状況は今委員会で報告して検討できるのかどうか、資料とかもここでいただけるのかどうかということを。","respondent":"中島街路事業担当課長","answer":"まちづくり特別委員会の調査項目につきましては、３２５号線ですので、目黒線の連続立体事業につきましては本委員会で調査ということになってありますので、この事業に関する内容につきましては当委員会でということになります。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"意見","question":"ということは、この間の予算特別委員会で聞いた以降の、例えば駅前広場の、ここに地図が載っていますけども、今後の建設委員会の中で、あと線路が地下化になった上部の利用とか、高架の下の利用とか、そういう部分で出ている図面とかはいただけますか。","respondent":"中島街路事業担当課長","answer":"ただ、お互いにふくそうしているものもありますので、状況に応じてその辺はご報告させていただきたいということを考えております。","id":"exchange-015"},{"speaker":"林（和）副委員長","kind":"意見","question":"今現在、品川区の１２％ということは、２３区でどの程度のぐらいまで上がっているのか、それから、これから屋上緑化を進めてまいりますけれども、屋上緑化をした場合には、この比率の中に入ってくるのかどうか、その点をちょっとお聞かせください。","respondent":"松代道路公園課長","answer":"やはり、基本的には、今まで進めてまいりました地上部での緑化、これがやはり大事だろうと思っていますので、これを怠ることなく進めながら、また屋上緑化も含めて努力をしてまいりたいと、このように考えておるところです。","id":"exchange-016"},{"speaker":"船波委員","kind":"質問","question":"利用料金の当日利用が１５０円ということになっていますけれども、この開設時間を見ると、午前０時を挟んで３０分間開かれているわけですけど、その０時を超えてしまった３０分間の間に取り出したりした場合でも、この５時１５分から２４時３０分までの間なら１日という換算なんですか。","respondent":"奈良交通安全担当課長","answer":"いわゆる駐輪してから２４時間１５０円ですので、それ以降になりますと、また別料金になりますけども、駐輪してから２４時間が１５０円です。","id":"exchange-017"},{"speaker":"船波委員","kind":"質問","question":"この定期に利用の料金についてですけれども、固定の場合とあとは２段のほうの、５駅９カ所のところもそうですけども、以前、大崎駅の有料の駐輪場について、学割を設定してほしいとか、あるいはもっと防犯に気をつけてほしいというような項目が含まれた請願が出されたと思いますけれども、この、今度の設置事業、あるいは２番のほうの有料化においては、学割というのは。","respondent":"奈良交通安全担当課長","answer":"学割につきましては、以前請願が出されておりましたけども、今回の天王洲アイルにつきましても、それから２番目の、ことし１０月にオープンする予定の５駅９カ所につきましても、いわゆる学割につきましては、非常に区内は、おおむね歩いて１０分ぐらいで最寄りの駅に行ける。","id":"exchange-018"},{"speaker":"田中委員","kind":"確認","question":"今回の自転車駐輪場の特徴は、地下に駅ができたその上の地上部までの間の、上の道を復元する際にこの駐輪場をということで、地下にできるということが、今回の特徴だと思うんですけども、というのは、そのためにも、お話があったように、地下にできにくいということから、警察関係あるいは消防関係からも、防犯のことですとか、防火に対する、いろいろ心配と言いますか、挙げられていると思うんですが。","respondent":"岩田管理工事課長、奈良交通安全担当課長","answer":"ご指摘の不測の火災とか、あるいは何らかの防犯上の事故が起きた場合に、警備会社がすぐ、おおむね３分から５分以内に現場にかけつけて初期対応ができるような警備委託もあわせて今回行う予定です。２番目の、いわゆる将来的に５２０台に増やした場合に、新たな拡幅工事をするのかというご指摘ですけども、現在の３００台につきましては、いわゆるナローラック式、いわゆる自転車を乗せる設備ですけども、それが、現在。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つは料金の問題と、サービスを受けるというところでは、場所の設備ですか、例えば、こういう、バイクは屋根なしとありますよね。五反田、中延、旗の台、戸越及び戸越銀座駅、１０月１日から有料化を実施するとありますけれども、この辺の５駅９カ所の、１０月１日までどう進むのか教えてほしいのと、利用者への説明をぜひ、説明会をしていただきたいなと思うんですけど。","respondent":"奈良交通安全担当課長","answer":"２点目の、いわゆる利用者に対する説明というご指摘ですけども、これにつきましても、６月２１日号で一応ご案内はしますけども、さらに、８月２１日号で詳しく区民に周知徹底を図る予定です。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６月２１日号の広報で区民に周知するということなんですけれども、駐輪場に対しては地元でものすごいし、要求もたくさんあるんですよね。今後の計画はこれを見てくださいということですが、私は、今、ちょっとどういうふうに進むのかなと。利用者の方々は、区民にかかわることなんでね、いつからどう駐輪場に入るのかということもぜひ知りたいと思うので、その辺もぜひ確認していただきたいと思います。","respondent":"奈良交通安全担当課長","answer":"今の、料金の再度ご指摘の話、それから利用者への説明のお話ですけども、料金につきましては、先ほど申し上げたとおり、決して高過ぎないというふうに感じております。利用者への説明ですけども、これについては検討させていただきたいと思います。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"説明会はぜひ実現をしていただきたいと思います。してくださるということなので、お願いします。７月から工事ということなんで、ぜひこの９カ所の図面をいただきたいんですけれども。","respondent":"中谷まちづくり事業部長","answer":"説明会ですが、区としては、利用者に対する説明につきましては、チラシ、看板、それから、あと、先ほど申しました広報等、それからインターネットのホームページでも、これ、ＰＲする予定ですので、これらで十分な区民説明をいただけますし、それから。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"なかなか理解できないことなんですが、利用料につきましては。利用者への周知という意味では、現在の駐輪場を利用されている方に、特にお知らせの方法というか、一般的なことだけじゃなくて、駐輪場にわかりやすく表示をしていただくというのはいかがですか。","respondent":"岩田管理工事課長","answer":"大崎、大井町のときもそうでしたが、実際、定期のご使用者には、開設後に、１カ月前にやりますので、その以前、若干前から現地の予定地には看板をつけまして、これこれこういうふうになりますと。","id":"exchange-023"},{"speaker":"堺委員","kind":"質問・要望","question":"あそこ、おそらく有料化にされるのかなとは思うんですが、そうすると、そこを工事するということになりますと、今までそこを使っていた人たちはそこが使えないわけですから、この工事期間中は自転車の利用はだめですよということにするのか、工事期間中は駐輪はここにしてくださいというふうにするのか、それ、戸越だけでなくて、旗の台、中延、五反田、戸越銀座を含めまして。","respondent":"奈良交通安全担当課長","answer":"今の、いわゆる工事期間中に自転車はどうするのかというご指摘ですけども、７月後半は、ちょうど通勤、通学者がほとんどですけども、ちょうど夏休みの時期ですので、いわゆる通学の方はほぼ少なくなるだろうということで、通勤される方が一部いらっしゃると思いますけども、特に。","id":"exchange-024"},{"speaker":"堺委員","kind":"質問","question":"ましてや代替地がないとなりますと、おそらく通勤の人たち、「じゃあ、工事期間中どうしてくれるんだ」という質問が、必ず、僕は出てくると思うんです。特に、代替地がないところについてはどうして対処していくか。だから、チラシ、看板等でやるということですから、そのところに触れておいたほうが僕はいいような気がするんですがね、その辺いかがでしょうか。","respondent":"奈良交通安全担当課長","answer":"いわゆる１カ所の駐輪場につきまして一気に工事をするわけではございませんので、徐々に、徐々に工事をやっていきますので、一気に自転車を排除するというわけではございませんので、部分的に工事をやっていきますので、十分それで対応できるだろうです。大丈夫です。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問・要望","question":"くどいようですが、その辺のところもね、一般の利用者に説明するなり、あるいはチラシの中にそういうふうに書くなり、要するに、何らかの形で今まで利用している人たちに不安を与えないようにしていただきたいのと、それから完成の暁には、「こういうふうになるよ」ということも含めて、全面的な理解と協力をいただけるような形での、こちらが接し方をしていきませんと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問・要望","question":"一つ、区営があったり、財団があったり、それから民間の委託という形になったりとか、これ、どういう基準でこれが決まっていくのかをちょっと教えていただきたいのと、それと、一点は、先ほど部長、管理費が１億円近くかかるという話でしたよね。今回の場合、設備は別で。","respondent":"岩田管理工事課長、中谷まちづくり事業部長","answer":"最近は、東急関係でも、目黒線の立体化事業の中でも、自主的に、区が設置をお願いした中に、鉄道事業者みずからが駐輪施設を設置する方向を、今東急側は考えてくれるようになりました。はＪＲだろうと。財団につきましては、これは、区のほうで建設費を補助いたしまして、出資いたしまして、そして、共同で設置して、管理運営を財団が行い、これ、旧建設省の外郭団体ですので、国の補助も受けておりますので、まず共同で設置して。","id":"exchange-027"},{"speaker":"本間委員","kind":"質問・要望","question":"実は、過日、５月２８日でしたんですけど、立会川の臭気が異常な発生の仕方をして、付近の方からの苦情をいただいたということがございました。この件につきまして、ご見解と今後の対策について、大変大きな問題といいますか、難しい問題かもしれませんが、ご意見をいただきたいと思います。","respondent":"中谷まちづくり事業部長","answer":"これができますと、３倍までの対応ができ、なおかつ放流した水が５０ミリまでは立会川から出て来ないということになります。今回一番問題となりましたのは、しばらく雨がなかったということで、雨がなかったところで、ちょうど５月２６日の日曜日に、夕方１５ミリの雨が降ったと。","id":"exchange-028"},{"speaker":"本間委員","kind":"質問・要望","question":"非常に、最近の品川区は動きがいいねと、対応が早いねというふうなことがあったものですから、今日までなお続く臭気対策、決定的なものになっておりませんけれども、一生懸命やっているねという部分で、ある程度のおさまりがあるわけですので、これからも、区民の要望、陳情につきましては、なかなか決定的なものになりにくいかもしれませんが、機敏な対応で区民に説明をされるよう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"林（和）副委員長","kind":"質問・要望","question":"今、本間委員が指摘したとおりでございまして、大いに、これからひとつ頑張っていただきたいと思います。ということは、これがあってから急遽これをやるということに決めたんですか。それと同時に、なぜ５月３１日からこれを９月までやるのか、これから毎年これらはどのようにやっていくのか。せっかくある施設でございましたのに、なぜ５月３１日からやったのか、その前からなぜやらなかったのか。","respondent":"中谷まちづくり事業部長","answer":"今後の対応ですが、先ほど、私、ご説明申し上げましたが、今年についてはいろんなパターンで検討しています。","id":"exchange-030"},{"speaker":"林（和）副委員長","kind":"質問","question":"７月７日に毎年やっている立会川の環境美化運動を実施した後に、１１時ごろからＪＲ導水の式典をやるというふうに案が書かれておりますけれども、これはどういうふうなあれなんですか。もう少し具体的に。","respondent":"中谷まちづくり事業部長","answer":"今年、７月７日が川の日ということでございましたが、この７月７日に何とかこの導水を間に合わせたい、できれば、やはり川の日に放水したいと。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"そうすると、勝島運河の一方で、立会川の浄化対策に積極的になる中で、一方で、汚れた水が勝島運河に流れることによって現状よりも勝島運河の水質が悪化するんではないかという一方の懸念があるんですが、そのことに対する対応も並行して考えていただかないと、こちらだけきれいになって、一方では水質が汚いということが起き得ますので、その点の確認を、お考えをお聞かせいただきたいと思います。","respondent":"中谷まちづくり事業部長","answer":"要は、循環効果をどれだけ上げるかですので、５,０００立米といえども、水源が常時確保歩できることになると、常時、そのまま勝島運河から京浜運河へ放流されるですので、あるとき一瞬だけを考えますと、一回それが勝島運河に流れるということはありますが。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問","question":"臭気の測定の話なんですけれども、以前にお聞きしたのは、たしか、何か手持ちで持ち歩くようなもので、近隣の住民の方に常時持っていただいて測定したりできないのかという話をしたことがあるんですが、それはなかなかできないという話があったんですけども、今回のこのあれというのは、どこかに機器を設置して常時はかっていくようなものなのかどうかというところをお聞きしたいのと、それと。","respondent":"中谷まちづくり事業部長","answer":"そうしますと、今の高い護岸につないで環境護岸にその後改修しようですので、順序としましては、下水道整備が、先ほど言いました、約１０年かかりますが、これが終わり、水門工事をその後東京都建設局が行い、その後に環境整備が、護岸が改修されると。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問","question":"今の計器の測定の話なんですけれども、その測定をする日に持っていってということなんですけれども、例えば、この水を流している期間中ずっと設置をしていくという方式というのは考えられないんでしょうかね。そういう中で、区民のどなたか責任者をつくって測定というか、聞いていくというような形というのは考えづらいものなんでしょうか。ちょっとそこだけ。","respondent":"中谷まちづくり事業部長","answer":"費用的にも、ここで既に今回委託が始まっておりまして、５月３１日から委託はもう開始しておりますので、今回の委託経費の中には、常時設置するだけの費用、そういうものを見込んでおりませんので、よろしくご理解いただきたいと思います。","id":"exchange-034"},{"speaker":"堺委員","kind":"質問","question":"この中では、事業認可が平成１４年４月１２日、この補助１６３号線については事業認可がおりたと、そういうことに関連して、どうしてもその道路の拡幅事業に伴って立ち退かざるを得ないとき、いろんな事情があって、こちらでのご商売が無理だとか、大変な形でそこを立ち退く、そういうことも含めての、これからの立ち退きに関係する一本橋通りの方々の個別交渉というんですか。","respondent":"田村住宅課長","answer":"今の時点では、所管と調整して、３戸程度を１３２戸の中で事業用として確保していくという考え方で調整を進めております。","id":"exchange-035"},{"speaker":"堺委員","kind":"質問・要望","question":"ここも同じ品川区内であり、なおかつこっちは新たに区営住宅ですから、こっちにできるのは区民住宅ですけども、２つとも、公募といえども条件があるということをおっしゃっていましたが、こっちの区民住宅でも、あっちの西大井のほうの区営住宅にも、できれば一本橋通りのそういう方々への移転先の確保の場所というんですかね、それはいかがでしょうか。","respondent":"田村住宅課長","answer":"先ほど申し上げたように、これからマテリアルの土地、それと荏原市場跡地もありますし、西大井六丁目も建て替え住宅、建て替え移管も、今仮移転で荏原市場跡地のほうに移って、やっぱり一般の区営住宅として区民の方に募集するということですと、先ほどのマテリアルの件と。","id":"exchange-036"},{"speaker":"堺委員","kind":"意見","question":"先ほど申し上げましたように、一本橋通りの道路の拡幅も含めて、いろんな方々にいろんな形でご理解とご協力をいただける場合に、たまたま、今回こういう形で住宅があるので、渡りに舟じゃありませんが、その可能性があるならばという思いでお尋ねをした中で、そういうことが可能だということでありますから、今後そういうことがあるのかどうかわかりませんが、今後、また同じようなケースがあった場合には。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問・要望","question":"最近の、直近のところでの都営住宅、区営住宅の倍率を教えていただきたいのと、それと、さっきのお話では、都営住宅を区営住宅として新しく建てたということなんですけども、こういう計画がされているところが、ほかには区内にあるのかどうか、ちょっとその辺を教えていただきたいと思います。","respondent":"田村住宅課長","answer":"それと、２点目の建て替えについては同じような形でということですが、現在、予定は、今協議されました西大井六丁目の区営住宅です。","id":"exchange-038"},{"speaker":"菊地委員","kind":"質問","question":"倍率、全部話してくださったんですけど、あっけなかったので、もし後でもらえるんであればお願いしたいと思います。それで、区民住宅の場合はそれなりの収入がないと入れませんですし、家賃そのものも維持できないわけですけども。要するに、１００戸程度のところで、あわせればもう少し戸数を設けられるんじゃないかというような場所というのがあるんであれば教えていただければと思います。","respondent":"田村住宅課長","answer":"先ほどもご説明したように、現在、建て替え等の予定で、区が都と交渉してというのは全く未定の部分ですので、ちょっと想定で、どこだったらそこを建て替えればさらに戸数が何戸増えるだとか、そういうのは、ちょっと今想定でお話ができないので……。","id":"exchange-039"},{"speaker":"北野委員長","kind":"質問・要望","question":"ほかに何かございませんか。私のほうから、次回７月２日の委員会で、行政視察の調査事項、視察先などについて委員の皆様からのご意見をお出しいただきたいと思いますので、よろしくお願いいたします。以上をもちまして本日の予定はすべて終了いたしました。休憩もとらないで委員会運営をさせていただきまして、皆様のご協力、ありがとうございました。お疲れさまでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/923086?Template=document&Id=3724#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":63807,"voices":167}},{"id":"h14-20020610-5","meetingId":"h14-cm06","date":"2002年6月10日","dateIso":"2002-06-10","committee":"総務委員会","time":"午後１時０３分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","topics":[{"id":"topic-01","title":"番の幹部職員紹介","agenda":"番の幹部職員紹介","exchanges":[{"speaker":"桜井委員","kind":"提案","question":"だから、公債の行き先というんですか、それは何か一定程度の規則なり、取り決めがあってやるんだと思うんですけれども、それについて質問したいのが１点。品川区の中で、先ほどのご説明だと、まだ明確にされてないし、損害賠償も含めて、どういうふうにするかということも、今後の検討だということですけれども、区への影響というんでしょうか、どういうふうになっているのか、ご説明いただきたいと思います。","respondent":"市岡企画財政課長、小野（弘）副収入役、南監査委員事務局長","answer":"起債は許可制ですので、どの資金を充てて起債が許可されるかというのは国の判断なんですが、特にご説明する必要があるのは、品川区。１日の口座引き落とし分については１９万１,９００円ほど、それから公共料金につきましては、２４万７６８円プラス。そういう準備が、実績等である程度ありますので、平成１４年度につきましては、それを広げて実施をしていこうと考えているところです。","id":"exchange-001"},{"speaker":"桜井委員","kind":"確認","question":"それと、特にこの間、問題というか、指摘されているのは、品川文化振興事業団の関係ですけれども、通常、監査というと平成１３年度の監査でしょうか。私がちょっと思うのは、この間、直接的にお話を副理事長に聞いたんですけれども、一たんみずほ銀行に行っているわけですから、そこと品川文化振興事業団との関係で、毎年０.６％ずつ５年間にわたって利益を受けると。そこだけ確認しておきます。","respondent":"南監査委員事務局長、市岡企画財政課長","answer":"さかのぼるかどうかですが、本来は、前回、監査以降監査するべきなんですが、それですと大分間があきますので、各団体とも、書類としては、平成１２、１３年度、場合によっては平成１１年度。私ども、全く知らなかったわけではありませんで、そういう譲り渡しが行われるということで、それは大変合理的なことだなというふうに承知しておりました。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問","question":"概要説明ですから、簡潔にいたします。今の経過にしても、何かちょっと疑問ということではないんですけれども、なるほどうまいことをやったのかなという面もあるんです。区と品川文化振興事業団との関係が、今までの経緯がありますから、もう少し何らかの形になるかなと、ちょっと意見を持っているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"お一人の方がやれるものなんですか。組織改正のときに話題になった、要するに企画と財政が一緒になっちゃうと、やりにくい。そういうときに、重点事業を選択して政策評価なり、そういうところで扱っていくというときに、企画と財政と相談をしながらやっていくというのが熟してきたときに、今の組織で平気なんですかという、そういう聞き方をしたい。","respondent":"市岡企画財政課長","answer":"社会状況のいろいろな局面の中で、いつもこれがいいとは限りませんけれども、今はそういう時代かなという判断をして、常日ごろ、両課長、あるいは企画財政の職員にも、決して問題点をあげつらってプロジェクトを殺してしまうんではなくて、問題を解決しながら前へ進む。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"一緒のほうがいい部分ももちろんあるんでしょうけれども、対東京都ということに限って言うと、５ページに書かれているのは交渉という話にはならないんだけれども、実際には、東京都と財調調整の交渉の場があるわけですから、そのあたりのときに、企画担当と財政担当が兼ねているということでのメリット、デメリットというのはあるんですか。","respondent":"市岡企画財政課長","answer":"我々のいき方の一つの選択としては、有効かなと思っています。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"順番でいくと、収入役室のみずほ銀行関係なんですけれども、さっき説明があったんで、一応、確認しておきます。品川区が受けた被害、影響で、なおかつ、区民が影響を受けた、あるいは被害を受けのはどういうところなのかというのを分けて整理をしていく必要があると思うんですよ。なぜかというと、こういう例があるんですよ。４月に口座振り替えされるところが、されなかった。最後に１点。","respondent":"野田口選挙管理委員会事務局長","answer":"今、委員のご指摘のとおり、例年そうなんですけれども、来年度の統一地方選挙の日程を今年の１０月ごろ決めるということになります。通常ですと、４月の第２日曜日が都知事選挙、第４日曜日が区議、区長選挙が行われております。ただ、例外が１回だけあります。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"ポスターとか、たすきとか、違反に近いような、あるいは、厳密に言えば違反になるようなものについても、今年度に限ってはいろいろ仕事ができそうなもので、ぜひお願いをしておきます。すみません、もう１点、情報システム課長の顔が見えたので、「日経パソコン」から発表された電子政府、電子行政、電子自治体のランクは、品川区は何位ぐらいだったんですか。","respondent":"田中情報システム課長","answer":"昨年は全国で１１位だったんです。市政をしいている自治体がたしか６８８で、それに２３区を入れるんですが、そのうち６８位です。５０位近くランクダウンしちゃったわけです。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"情報システム課の事務事業の関係で、ちょっと質問なんですけれども、住基ネット、要するに国の方針として電子政府を目指す中で、データ類を電子化して保存すると、ここまではいいわけです。ここの問題との兼ね合いで、それを使う側のさまざまな状況は、セクションも含めて、どこでどのように考えて進めるのかということが問題だろうと思うんで、ちょっとその辺についてお考えをお聞きしたい。","respondent":"田中情報システム課長","answer":"住基ネットについては、基本的には自治体の事務ですので、そういう形で、全国の自治体でセキュリティのレベルを守るということで対応していくことになります。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問","question":"その使われ方。要するにデータはすべてこっちあるわけですね。そういうものを合わせて、いろいろなアイデアが出されているものの、その使われ方に向かっては、どこでどんな形で審査をしていくのか。そのほかの情報システム課はシステムをつくるほうですから、それ以外のそれを使ってやる部分は、どこが中心になって、どこがやっていくんだろうかなというのも疑問なんです。","respondent":"田中情報システム課長","answer":"２点あったかと思いますが、最初のセキュリティの問題につきましては、全国的な市区町村の運営協議会の標準的な案を受けまして、区として規定整備を行う予定です。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"データを集めたのは、ただ集めて楽しんで、防衛庁みたいなことではないはずですから、それをどう使うかということになるので、問題は、今の仕組みの中で、住基ネット上、外へ出て行くデータ以外にロックをかけられるわけじゃないと思うんで、向こうは使わないということを信じているだけじゃどうしようもないわけですから、その辺を。","respondent":"田中情報システム課長","answer":"住基ネットのデータの持ち方なんですが、住所、氏名、生年月日、性別、それと全国の住基コード、この５項目のデータ項目が住基ネット上に載ります。","id":"exchange-010"},{"speaker":"土井委員","kind":"意見","question":"そういうことですね、今のお話ですと。それが一つ。それからもう一つは、それでいきますと、全国くまなくすべての自治体が参加をしているということが大条件になるはずでもありましょうし、そこでどうセキュリティを保つかということがきちんと決められていて、それが全国的な各自治体、あるいは住民が納得をして、はじめてオーケーとなるはずなんですけれども、その辺との兼ね合いは。","respondent":"田中情報システム課長","answer":"各自治体の参加状況ですが、法律で決まった制度ですので、基本的には参加していただくということで、総務省が対応していると思います。杉並区等、いろいろ経過はありましたが、基本的には参加していく方向になっていると聞いております。","id":"exchange-011"},{"speaker":"土井委員","kind":"意見","question":"わかりました。ここで聞いても、品川区の場合はそういうことで、情報システム課の皆さんも含めてのセキュリティに関する見方も含めて、了解をするところなんですけれども、全国、そういう状況ですと、ある部門でどこかで１カ所破れちゃうと、ずるずるになっちゃう代物なんですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"桜井委員","kind":"質問・要望","question":"２点、ご質問いたします。総務課の４ページですけれども、私立幼稚園の預かり保育モデル事業、きんだぁくらぶなんですけれども、先ほどのご説明で６園とありましたけれども、もう少し、具体的に園名を教えていただきたい。私もよく正確にはつかんでないんですが、これまで、どういうふうな勧奨制度というのがあったんでしょうか。","respondent":"古川総務課長、桑村人事課長","answer":"平常時の平日の場合の利用状況につきましては、平成１２年度は８.５５人でございました。平成１３年度は９.５人。おおむね、大体、１日１０人ぐらいお預かりの実態と考えています。私どもとすると、勧奨した事実がない方に勧奨退職手当は払いませんし、勧奨退職とは見ることができませんので、それは普通退職でしかないということで、そこで見解が分かれているです。","id":"exchange-013"},{"speaker":"桜井委員","kind":"質問","question":"通常、今の勧奨退職ですと、民間だと何歳になったらとかありますよね。区としては、今までどういう年齢の勧奨退職というのをされていたんでしょうか。これまでの実績というか、平成１２年度の実績とか、そういうところもちょっと教えていただけませんでしょうか。","respondent":"桑村人事課長","answer":"その意味で、平成１３年度の判断としましては、こういったものを勧奨する必要がないという判断をして、実施しなかったです。","id":"exchange-014"},{"speaker":"桜井委員","kind":"質問・要望","question":"さっきの預かり保育の話ですけれども、今までは、ちょっと思ったよりも人数的に少なかったのか、あるいは一定程度、こういう形で伸びていけば定着をしていくと見るんでしょうか。１,０００万円という予算なんですけれども、これはどういうふうな予算の振り分けというのか、１人当たり幾らといくのか、あるいはまた、どういうふうな内容でしょうか。","respondent":"古川総務課長","answer":"ちょっと私の説明も不十分だったと思いますが、いわば、きんだぁくらぶということで預かり保育モデル事業として委託をお願いしている園は７園です。","id":"exchange-015"},{"speaker":"藤田委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、９ページの職員被服貸与に関する事務で３,４００万円計上されておりますが、この中身について、ちょっと教えていただきたいということ。それから、職員の名刺というのは、職員は３,０００人近くいますけれども、どれぐらいの予算をかけているのか、１人何枚程度つくるのか。いろいろ言いましたけれども、その辺ちょっと教えていただきたいと思います。","respondent":"桑村人事課長、市岡企画財政課長","answer":"私のほうで、被服貸与のほうを先にお答えします。基本的に、係長以下については私費でつくっております。デザインについては、イメージアップの関係で調整をしておりまして、品川ストライプ、あるいは図案を入れたような統一をしております。","id":"exchange-016"},{"speaker":"藤田委員","kind":"質問","question":"トレーナー、ないしは保健婦の長い白衣ですか、そういうものがそんなに毎年要るものなかどうか、それがちょっと疑問な点があるんですけれども、実態的にそういうことであれば、それは了解するわけですけれども、その辺、もう少しシビアに。だれもかれもということではなくて、係長でも、いろいろな人が訪ねてきて、「あなたはだれですか」と言われれば、私費でつくっているものを出す。","respondent":"桑村人事課長、市岡企画財政課長","answer":"ただ、先ほどおっしゃられたとおり、被服については、一定の見直しが必要だと思いまして、これまでも見直しをしてきてありますので、なるべく長く使えるような形にしてまいりたいと思います。ちょっと説明をはしょっておりましたので、簡単にご説明申し上げます。","id":"exchange-017"},{"speaker":"藤田委員","kind":"質問・要望","question":"きのうですか、広報「しながわ」にサマールックの記事が載っていました。デザインも工夫して、職員がこういうふうに環境に取り組んでいますと、役所もちょっと暑いかもしれませんが、ぜひ、ご了解、ご理解をいただきたいというような文面のものを、ぜひ、つくってもらいたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"土井委員","kind":"質問","question":"研修の関係でお伺いしたいんですけれども、前年と変わったからということでは、派遣研修というスタイルでの研修が行われるようになったんですけれども、この辺については、どんな感じで、どういう流れなのか。","respondent":"桑村人事課長","answer":"その意味では、今までと同じような社会福祉法人等と同じような形で、その団体につきましては、スポーツ協会と文化振興事業団、社会福祉協議会ですけれども、この３団体についても、一般の団体と同じような形の、まさに研修としての派遣をしております。","id":"exchange-019"},{"speaker":"嶋委員","kind":"質問・要望","question":"８ページの人権啓発課なんですが、男女平等推進法フォーラムハートフルしながわ２００２ということで、毎年、１１月に開催をされるんですが、いろいろなところを見させていただいているんですけれども、数日間というのが大体の流れになっているかなと考えています。１日というは大変難しく、今まで、数日間やってほしいとか要望があったのでしょうか。","respondent":"阿部人権啓発課長","answer":"男女平等推進フォーラムにつきましては、実行委員会形式でやっております。いわゆる区民の皆様が、自分たちで内容から実施まですべてやっていただいております。ですから、一応、今までなるべく参加していただきやすい曜日ということで、、土曜日１日やっています。","id":"exchange-020"},{"speaker":"嶋委員","kind":"意見","question":"よくわかるんですが、ほんとうに毎年変わることなく、いわゆる講演と分科会で、区民の方が主体でお任せしているのは大変すばらしいということもあるんですけれども、男女共同参画センターというのがありますので、そういう方たちが主体で、新しい２１世紀になって、何かもうちょっと拡大して、そういう方たちが活動する現場とか、展示とかいろいろあると思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"川西副委員長","kind":"質問","question":"簡単なことですが、ちょっと認識が違っていれば訂正しますけれども、施設担当のことです。旧営繕課が経理課に吸収されて、設計の一部を外注委託するというような組織になったと思うんですが、これについて、変更されてからのメリットと、現況の流れ。それからもう一つは、設計委託などの入札関係のことは、やっぱりこの施設関係の方がおやりなっているんでしょうか、ちょっとお伺いします。","respondent":"片田施設担当課長、西島経理課長","answer":"メリットにつきましては、教育のほうは技術屋が今４名ほどおりまして、事務屋を含めてトータルで１０人態勢ぐらいで庶務課の施設係で対応しています。福祉事業部のほうの児童課のほうに技術職が３名います。それは従来と変わってございません。従来も、大規模な設計関係は民間委託してございましたけれども、今回、それ以外のものも民間委託が増えてまいりますが、従来どおり、入札を経理係のほうで実施してまいります。","id":"exchange-022"},{"speaker":"川西副委員長","kind":"質問","question":"そうしますと、具体的に言うと、例えば学校に雨漏りがした場合、もとの組織のままですと、もう少し時間がかかったものが、迅速性が確保されたと理解しておいていいんですか。","respondent":"片田施設担当課長","answer":"委員おっしゃるとおりです。雨漏り一つということであれば、庶務課の技術担当がすぐに現場に行きまして、施設課のほうで調整をして、起工書を起こすというような体制を考えてあります。","id":"exchange-023"},{"speaker":"川西副委員長","kind":"質問","question":"その場合の、金額の査定というのは、どこかに基準があるんですか。","respondent":"西島経理課長","answer":"権限の問題ですけれども、学校で言いますと、５０万円以下の工事については、従来から所管の権限で実施していますので、その部分については変更ございません。","id":"exchange-024"},{"speaker":"川西副委員長","kind":"質問","question":"今のことはわかりました。ちょっとさっきの被服のことで関連で質問しておきたいんですが、例えば、保育園等で外に子どもを連れて遊びに行きますよね。よく出会うんですけれども、そういうときの被服というのは、せっかく与えた被服を着用していらっしゃるんでしょうかね。細かいことを申し上げて悪いんですけれども、その辺について、どういう指示系統というか、組織がどうなっているのか教えてください。","respondent":"桑村人事課長","answer":"その意味で、いわゆる格好については、ほぼ同じ形だろうと思いますけれども、貸与被服を必ず着ているかということについては、例外があるかと思われます。","id":"exchange-025"},{"speaker":"川西副委員長","kind":"意見","question":"今、比較的短時間勤務、それから再雇用職員が現場に入っていますよね。そういう方たちには、同じように被服貸与があるのかどうかということ。","respondent":"桑村人事課長","answer":"今は、短時間の非常勤職員については、同じように考えてあります。","id":"exchange-026"}]},{"id":"topic-02","title":"の聴取をいたします。 お手元に中央防波堤埋立地の帰属についての資料がございますが、これ","agenda":"の聴取をいたします。 お手元に中央防波堤埋立地の帰属についての資料がございますが、これ","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"(3)の、各区の主張に対する疑義についてというところがありますよね。品川区はどういうふうな主張をされているんですか。","respondent":"小野（孝）政策担当課長","answer":"品川区につきましては、まず、この土地の帰属というものについては、この位置関係からいたしまして、品川区にも大井ふ頭、海岸という形ですので、私どものほうの地崎の土地であるということで、当然、帰属権が品川区にかかってくるということで、ここについては。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"疑義が二つありますよね。一つは帰属問題、一つは施設の問題。帰属の問題は、そういうふうに地崎の関係で、うちにもあると主張されている。そうすると、灰溶融施設の関係は、どういうふうに主張されているんですか。","respondent":"小野（孝）政策担当課長","answer":"私ども品川区としては、灰溶融施設の都市計画の決定については、やはり帰属とは別に切り離して考えるべきであって、帰属の決定が決まらなければ都市計画ができないということではなくて、都市計画のほうを進めてほしいと主張しています。","id":"exchange-028"},{"speaker":"土井委員","kind":"質問","question":"まさしく品川区のそのことが、東京２３区清掃一部事務組合のありようということについての協議にも係わっているみたい感じでもあるわけですね。いわゆる法定の手続というのはどういう中身を含んでいるのか。それによって、例えば、それが速やかに決まる法定というのはどういう形なのかわかりませんけれども、速やかに決まるものなのか、どうなのかということを、まず伺わなければなりません。","respondent":"小野（孝）政策担当課長","answer":"ただ、５区の合意ができないという形になりますと、論争がある場合、地方自治法の９条に、「知事は関係特別区の調停に付することができる」という形になります。","id":"exchange-029"},{"speaker":"土井委員","kind":"質問","question":"そういうことだとすると、１３号地の埋立地のときを事例にとるしかしようがないわけですが、そのときはどうだったんでしょうか。３日で決まったのか、３年かかったのか、２０年かかったのかということですよね。その辺でどうなのか。その見通しも含めた形になっていると思うんです。１３号地の事例では、いかがだったんでしょうかと聞いたほうがいいんでしょうか。","respondent":"小野（孝）政策担当課長","answer":"１３号地の場合は、もともと協議が始まったのが昭和４７年という形で、そこから東京都の音頭で協議が始まりまして、実際にまず調停に付すという申請を行うということが決まったのが昭和５７年１月、ここまで１０年間かかっております。","id":"exchange-030"},{"speaker":"土井委員","kind":"意見","question":"内側の埋立が終わった時点で話し合うはずだったのかどうかわからないけれども、今までやってなかった。それでこれが始まったということからいくと、このままでいったら、また１０年かかっちゃうとなると、これは当分は解決しないという形になっちゃいますよね。そういう流れでは、いろいろと問題が発生をするということならば、どうするかということになるわけです。","respondent":"小野（孝）政策担当課長","answer":"現在の検討協議会、あるいは部会の設置を決定をされたのが今年の１月の時点で、それまで検討してきました部長会のほうは報告しておりますけれども、その中でも、法的手続、いわゆる調停の手続ということも視野に入れて検討すべきであるというような報告をしております。","id":"exchange-031"},{"speaker":"土井委員","kind":"質問","question":"もう１点だけ。そうすると、そういう手続を開始するだけじゃなくて、中身を決めなきゃいけないわけで、それには一定の期間がこれまた必要だろうと思うんですけれども、大体、どんなものなんでしょうか。要するに、いろいろやることの手を打つのが、最後の区切りのところにどう間に合うかという逆算方式も含めて考える上での参考にしたい。","respondent":"小野（孝）政策担当課長","answer":"ですから、６月中旬までに、江東区のほうで都市計画決定をして、告示があれば、このまま今度は設計だとか、いろいろな事務の手続に入って、平成１４年度中の着工、そして一応、国の補助金の対象になるだけの事業というものが確保できるという見込みですけれども。","id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"特別委員会もつくっているわけなんで、灰溶融そのものは、細かい話の関連がいろいろ出てくるとは思うんですけれども、ただ問題は、そちらの政策的なものも含めての影響が大きいわけですから、今のお話でも、都市計画決定の申請をするというのが、仮に帰属が決まったその日から始まったとして、この課のここの説明の段階では、手続が終わるまでには大体こんなぐらいかかるということまでが。","respondent":"中尾根企画部長","answer":"それについては、東京２３区清掃一部事務組合のほうで、先ほど言いましたように、板橋区長が管理者ですから、それはそれで動き始めているというのが現状だということで、ちょっと伏せられている部分をご説明いたしました。","id":"exchange-033"},{"speaker":"土井委員","kind":"質問","question":"そういうことで、いろいろな準備段階が進められている中で、都市計画申請をしたら、結論が出るまでどれぐらいかかりそうなんですか。","respondent":"中尾根企画部長","answer":"これまでの例からすると、当然ながら１０年以下というのはないというのが実例ですから、それ以上かかるということだと思います。ただし、江東区からすると、そこのところまで一気にはっきり筋道が見えれば、見えたで、また判断のしようがあるということだろうと思います。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"今回、特に２番目の、なぜ回答だけがあるのか、「灰溶融施設の都市計画決定手続きについて」、東京２３区清掃一部事務組合が絡んできた話ですから、ここは何を江東区に聞いたのかということがわからないと、答えもいろいろな思惑があって言っていることで、論理的にどうなっているのかよくわからない部分があるわけですから、東京２３区清掃一部事務組合がどういう立場で。","respondent":"中尾根企画部長","answer":"もう既に、ややこしいところに入っているというふうに、私どもは受けとめざるを得ないですね。こういう文書は、実は５区に相談は全くなかったわけです。","id":"exchange-035"},{"speaker":"林（宏）委員","kind":"確認","question":"確認を一番先にさせてもらいますけれども、(1)の５月２０日に行われた検討部会で、東京都の環境局から説明を受けたということは、どういう意味を持っているんですか。","respondent":"小野（孝）政策担当課長","answer":"外側を含めるかどうかということを判断をするのに、この埋立の状況がどういうふうに進んでいるのか。年度としては、平成１７年度３月というのが期限になっているけれども、実際、少し……。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、ここに書かれているのは、その２が環境局の所管であり、その１が港湾局だと。内側はどうなんですか。説明はされてない。","respondent":"小野（孝）政策担当課長","answer":"内側は既に終了しておりますけれども、処分場として使っておりましたので、そういう意味では、当時の清掃局が関係をしていたです。こちらでいくと、内側埋立地の半分、右上のほうが廃棄物、左下半分が建築残土で埋め立てておりますので、そういう関係になっております。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"簡単に説明してくださいよ。その２とその１は、環境局と港湾局。そういうことなんですね。その次の(2)の説明なんですけれども、これについては、この部会は一切、施設建設には関係しません。帰属問題についてのみ検討を加えていきますから、施設建設について、あるいは都市計画決定云々についてもしかり、全部含めて、単純に帰属だけを部会でやっていくだけですよという説明の文書なんですか、これは。","respondent":"中尾根企画部長","answer":"灰溶融施設については、どこの区がこの都市計画決定をやるかという判断は出ています。ただ、灰溶融施設そのものが必要であるのか、大きさがどうであるのかということについては、一切関知をしないという関係にあります。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、今のは微妙なんですけれども、片方で施設建設は念頭にありながら、帰属をやっていくというのか、施設建設はわかっているんだけれども、この検討部会では、帰属をどこにするのかということの意見集約を持つと考えていいですか。","respondent":"中尾根企画部長","answer":"そこから出発しておりますが、この江東区の区長のそれというものは、またその原点に戻って、くつがえしているという意味で、ただし、関係とすれば、今言った経過の中にある関係が、当専門部会の中で検討している事項です。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"３番目の説明なんですけど、この疑義についてというのは、(3)は、いわゆる帰属問題についての話に限ってのことの説明ですか。","respondent":"中尾根企画部長","answer":"そのとおりです。これについては、灰溶融施設がどうだということではなくて、帰属の手続そのものです。","id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問","question":"最初に戻るんですけれども、さっき言った、施設建設を江東区がやると決定をしていると言っているんですけれども、どういう形で決定をしているんですか。","respondent":"中尾根企画部長","answer":"これは、関係区長の中での合意で進めている事項ですので、特にその時点での文書はありませんけれども、そういうことです。","id":"exchange-041"},{"speaker":"林（宏）委員","kind":"意見","question":"文書がないと非常に不安が多いのは、江東区としてもしかりだし、これからいろいろそういう問題が出てくる。２番目の1)に、「決定を行うことは暫定的な覚書の範囲を超えている」と言っているから、覚書の中にはないんじゃないか。決定をしていると言いながらも、江東区がやるということは。","respondent":"小野（孝）政策担当課長","answer":"覚書の内容ですけれども、中央防波堤内埋立地における事務処理に関する覚書、これは、昭和４８年１０月２７日に関係区で交わされたものですが、1)といたしまして、「中央防波堤内埋立地における特別区の処理すべき事務は、暫定的に江東区において処理する」と書かれております。","id":"exchange-042"},{"speaker":"林（宏）委員","kind":"意見","question":"あくまでも、施設建設は東京都が行う事業だという、５区の関係者の理解だったと思うんです。改めて２３区で、この施設建設をこの埋立地につくることをどうするかというのをやればいい。そういうふうにはっきりしていかないと、いつまでも江東区に引っ張られて、５区だけの問題に２３区の問題を引きずり込まれちゃうと、僕は思うんですけれども、その辺をはっきり分けていくべきだと思いますよ。","respondent":"小野（孝）政策担当課長、中尾根企画部長","answer":"江東区長の見解の送付先ですけれども、これにつきましては、写しという形で、その写しが各２３区全体に送られております。ちょっとフォローします。前段の話と後段の話なんです。前段の話ですけれども、５区協議書となっていますが、東京都も既にその当時から入っております。実は、そういうことについて、東京都の意向も含んだ協議になっているんです。","id":"exchange-043"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"最後にします。この二、三カ月で決まるわけです。だからはっきり、もう５区の問題の帰属と２３区の問題の施設建設は分けて、東京２３区清掃一部事務組合がどう判断するのか。もう平成１７年度末を待たなくても、今年中に決定を見ちゃうんです。そういう問題だということを、企画部長も十分ご承知だと思いますけれども、わきまえてやっていただきたいということをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"塚本委員","kind":"意見","question":"今、現状の委員会運営、報告事項、それから、議案審査等ですけれども、委員会の中身の経営責任者である委員長の指導のもと、調査事項を立てられて、どういうふうに運営するかというお話なんでしょうけれども、三つも四つもなかなかできないと思いますので、テーマを絞られて、このことについて２度、３度やられることが大変望ましいことと、私どもも思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"藤田委員","kind":"質問","question":"今、せっかく選挙管理委員会事務局長がいらっしゃいますので、今までいろいろと言われてきていました選挙のあり方といいますか、進め方、一つは看板があの大きさでいいのかどうか、候補者の公営掲示板を含めて。あれだけの大きなものがほんとうに必要なのかどうか。岡山ですか、今回、全国で初めて電子投票をやりますね。１２時、１時までも起きている必要がない、一発で全部当落が決まってしまう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"桜井委員","kind":"質問","question":"テーマというよりも、ちょっと質問なんですけれども、地方交付税の制度、東京都の場合は裕福だから、そのまま地方交付金というのは出てないんですけれども、全国的には、地方交付税の問題が今起きてますね。これは、もし直接区にかかわるとすれば、その辺の制度というんですか、税制問題というか、財政問題というか、ちょっと勉強したいなと思うので、その前段が、もしわかれば質問したい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問","question":"我々、４年勤めてきて、最後になるわけですよね。新しい来期の議員が出てくる。そういう意味で、大きい問題として取り上げていくということですから、何らかの形で、議会が意思表示するのも必要かなという気もしています。ほかの委員会とちょっと違うのは、箱を見に行く委員会と違うので、ソフト面のことが主となると思うんで、そういう意味では、時期を見て実施をしていただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の議論の領土問題に隠れているのは、東京２３区清掃一部事務組合の問題ですから、その問題をどこでやるかというのがあると思います。特別委員会との仕切りの問題があるので、その辺を注意しながら扱っていただきたい。思い出しました、自治体の合併問題について。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"やっぱりいろいろ、さすが総務委員会だと思います。電子自治体のこと、それから、地方交付税、品川文化振興事業団、埋立地の帰属、東京２３区清掃一部事務組合の中のこと、合併問題、それから、行政視察に行く時期等の話が出てまいりました。ほかにテーマはありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"桜井委員","kind":"質問","question":"テーマじゃないんですけど、いいですか。自民党のほうで提起されている登記所移転問題なんですけれども、これは、別に総務委員会というわけでもないし、どこの委員会の問題なのかわかりませんけれども、あまり詳しく内容が聞かれてないんですけれども、これは議長のほうが詳しいんでしょうか。法務局の品川出張所移転問題。大きい問題と言えば、結構大きな問題ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"桜井委員","kind":"意見","question":"だから、自民党としては、例えば、議会で決議的なものを考えているのか、どうか。総務委員会で聞くのは、ちょっとおかしいかもしれませんが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"僕の知っている範囲では、法務局の部長が、６月の初めか、５月の終わりかに、２カ月ぐらい経ってから、今年の４月から就任しましたというあいさつに行きたいというので来て、そのときに、「来年の２月をめどに、大田区の城南出張所に移転したいという計画を持っています。僕との話は、そういう段階です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"塚本委員","kind":"意見","question":"今、自民党の責任者をやっていますので、相談に来られまして、関連する団体の方が大変心配なさっているということを、つぶさに聞きました。やはり、合理性の低い話で、どうしましょうかということで、そろそろ結論が出て、皆さん方にお願いする場面が出てくるかと考えていますけれども、まだ、最終的な決定は見ておりません。そういう状況です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/891081?Template=document&Id=1584#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":61208,"voices":169}}]);
